/* 平成30年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h30.committeeSessions.push(...[{"id":"h30-20180227-9","meetingId":"h30-cm02","date":"2018年2月27日","dateIso":"2018-02-27","committee":"文教委員会","time":"午前１０時００分～午後 ２時２６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を56件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２９年度品川区教育委員会の事務事業の点検および評価報告書","agenda":"平成２９年度品川区教育委員会の事務事業の点検および評価報告書","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"１５事業ですけれども、教育委員会全体の事業のうち１５事業ということなのかを確認したいのと、事業総数をあわせて教えていただきたいと思います。選ばれた１５事業は、４つの条件に該当する事業だったという理解でいいのか確認したいのが１つです。それから、４ページの学校用務の業務委託なのですが、先ほど全校という説明があったと思ったのですけれども、それでいいのか確認したいと思います。","respondent":"品川庶務課長、有馬学務課長、熊谷指導課長、大関教育総合支援センター長","answer":"その中で先ほど説明しました４つの条件に１つでも該当するものという形で１５事業、今回絞った形で評価を行ってあります。あくまでも国や他区の動向というのは教育委員からの意見で、全体的な動向も見ながら検討を進めてほしいというふうに捉えているものです。続きまして、7)番の学力定着度調査ですが、４月１９日にこの調査を実施しまして、その後、６月下旬に学校に調査結果が提供されております。マイスクール五反田で対応するだけでなく、メンタルフレンドが実際にアウトリーチとして学校に出向いていって。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"質問・要望","question":"対象となった１５事業なのですけれども、４つの条件に１つでも該当したらという説明だったと思いますが、それで１５事業というのは、どういうふうに私たちとしては捉えたらいいのか、例えば、物理的に大変だとか、そういうことも含めて、なぜ１５事業としたのかをもう一度教えていただきたいと思います。学力定着度調査については、わかりました。部活動については、わかりました。","respondent":"品川庶務課長","answer":"そういった形で４つの条件をもとにしまして、いろいろと対象事業を絞った中で１５事業をやるというような形で行ったものです。","voiceIndex":10,"id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"わかりました。ただ、１２５事業を全部やるというのは確かに大変だと思います。学事制度の問題、クラブ活動の問題、就学援助などもそうですけれども、そういうところが入っているのかなと理解もするのですけれども、１２５事業のうち１５事業だから、これを計算すると何％なのですか、随分少ないではないですか。そういう点で本当にこれでいいのかという気はします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-003"},{"speaker":"渡部委員","kind":"質問・要望","question":"２点伺います。給食の放射性物質検査のお話、今、説明も聞きましたし、ほかの委員からもありましたけれども、私はもうやめるべきだと思っています。代表質問でもちょっとお伺いしました件で、明日、豊葉の杜学園で行うことについてです。もしご紹介いただけるならご紹介いただきたいのと、スケジュール的なところとか、もし教えていただけたら教えてください。よろしくお願いします。","respondent":"熊谷指導課長","answer":"ちなみに、明日ですけれども、３６社以上のプレスが入るというふうに聞いているところです。ＮＨＫでも、明日、お昼のニュースで報道される予定です。","voiceIndex":13,"id":"exchange-004"},{"speaker":"松永委員","kind":"確認","question":"私からは、クラブ活動の指導についてと、いじめ対策について伺いたいと思います。１つ目は、指導員の単価なのですけれども、まず先に確認をさせてください。この指導員というのは、外部指導員、また教職員も含まれているのか伺いたいと思います。そこで現在の外部指導員、または教職員の方のご意見等が、もし聞かれているのであれば、その点についてまず伺いたいと思います。","respondent":"有馬学務課長","answer":"指導員ですけれども、これはあくまでも外部指導員で教員は入っておりません。それから、日当ということで４,０００円を支払っておりますけれども、教員は当然指導として入っていたとしても、金額の発生はないということです。あくまでも外部指導員に対してとなっております。","voiceIndex":16,"id":"exchange-005"},{"speaker":"松永委員","kind":"質問・要望","question":"今は６０名ぐらいということなのですけれども、やめられた理由がもしわかれば教えていただきたいのですけれども、１つは教職員になられて新たな出発というか、新たに頑張っていかれると思うのですけれども、前は結構いらっしゃったということなのですが、なぜやめられたのか、その理由がもしわかりましたら教えていただきたいと思います。そして、情報共有に関しては、どのような方法で共有をされているのか。","respondent":"有馬学務課長、大関教育総合支援センター長","answer":"もう１つは、単純に引退する、それは年齢のことかもしれませんし、何か仕事の関係かもわかりません。そこは詳しくは聞いていませんが、主にはそういう理由というふうに聞いております。いろいろと、例えば目安箱にどれぐらい入って、どういう対応をしていますという数的なご報告をするだけではなくて、実際に学校でいじめ対策の授業も見学いただき、学校現場の管理職、教員も含めた意見交換なども実施しています。","voiceIndex":18,"id":"exchange-006"},{"speaker":"松永委員","kind":"質問・要望","question":"私は、最初のクラブ活動に関しては、１日１回出れば４,０００円というのは、ちょっと気になったところだったので質問させていただきました。いじめについても、年３回ということで、いろいろと情報共有されているということで安心しました。最後に、２１ページで、さきほど課長からお話があったのですが、通室困難により７名が退室というのは、原因がもしわかりましたら教えていただきたいと思います。","respondent":"大関教育総合支援センター長","answer":"何か特定な、例えば疾病等の病状があるとか、そういうことではなくて、お一人おひとり、多分何か思うこと、あるいは家庭環境はさまざまですので、一概にはご説明できない状況ですが、先ほど申し上げましたとおり、別なスタッフが対応等は丁寧にしているところです。","voiceIndex":21,"id":"exchange-007"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"幾つかお尋ねしたいと思います。小学校ではその方がいらっしゃることで教員がいないときの様子を非常に密接に情報共有できたと伺っているので、中学校に、今年設置されるとき、小学校のよい面がうまく生かされないことを、ちょっと心配しているのですが、小学校の特別支援教室のいいところを、平成３０年度、中学校でどう生かしていくかという点をお尋ねします。","respondent":"品川庶務課長","answer":"１５事業以外の事業はどういうような評価をしているかということで、全部とは言いませんが、おおむね安定している事業が多いと考えています。そうは言いましても、各所管で国や都の動向、それから社会情勢等も見て、しっかりと事業の進捗等の評価をしているというものです。","voiceIndex":24,"id":"exchange-008"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"最後に、学力定着度調査は、総合評価のところに、全国的なシェアを持つ標準型の学力調査を行うことで、他地区との比較ができるということが書いてあるので、やはり他地区と比較してどうかということを示していただいて、もちろんその結果を踏まえて、学校、教育委員会としてどうするかというのは、当然、今後検証しなければならないと思うのですが、その状況を把握できないと、全国学力調査との比較も含め。","respondent":"熊谷指導課長","answer":"今ご質問いただいたところですけれども、今年初めて実施したものですし、経年で見ていくところなのですけれども、繰り返しになりますが、そもそもこの調査は学校でしっかり子どもたちの状況を見とってというところに主眼があるというところで。","voiceIndex":30,"id":"exchange-009"},{"speaker":"こんの委員","kind":"質問・要望","question":"その中で認識の確認を少しだけさせていただきたいのが、学校用務事業委託というところで、これは民間への委託で、私の認識が合っているのかどうかの確認なのですけれども、この用務事業委託をしていたのは、シルバー人材の方々にお願いをしていたと思うのですが、要するに、平成２９年度の実績値は６校でうち、中学校３校、小学校３校というところで、たしか小学校全校に。","respondent":"品川庶務課長","answer":"ですので、今回、事務事業評価で出している業務委託とは別のものです。それから、専門員ではないとだめなのかという点ですけれども、あくまで技能労務職ということですので、特段の専門性についてはないというふうに考えております。","voiceIndex":32,"id":"exchange-010"},{"speaker":"こんの委員","kind":"意見","question":"わかりました。シルバー人材の方は、いわゆる施設管理というか、夜からの業務になっている。その辺について、昼間いらっしゃる業務委託の方のお仕事と、シルバー人材の方がされている業務に対する先生たちの認識と、お願いする範疇は、庶務課としてどのように認識されて、もしそういったシルバー人材の方からどうしたらよいかというご相談があったときにはどういう対応をされていますか。","respondent":"品川庶務課長","answer":"それでも難しいようであれば、教育委員会のほうで対応という形でやっていけばいいかというふうに考えています。","voiceIndex":34,"id":"exchange-011"},{"speaker":"こんの委員","kind":"意見","question":"今のは、業務ができなかったらどうしようということと、もう一方で、働き方改革で先生たちの業務負担を軽減して差し上げたい、シルバー人材の方が気がついて、校内を回って戸締りをしているときに、これをしておいてあげたほうがいいかなみたいなところの手出し、口出しは、してもいい範疇があると思うのですけれども、そうしたものもご相談しながら行うという形でいいのか、その辺をお願いします。","respondent":"品川庶務課長","answer":"繰り返しになりますけれども、基本的には委託業務の範囲内でやっていただくという点があると思うのですが、いろいろと現場内でのやりとりがありますので、その範疇については、やはり学校長が責任者でありますので。","voiceIndex":36,"id":"exchange-012"},{"speaker":"こんの委員","kind":"意見","question":"シルバー人材の方は、どうやったら先生たちの負担を軽くして差し上げられるかなと思ってお仕事をされている方もいらっしゃる。シルバー人材の方にとってもやりがいを感じられるかなと思うので、そうした流れができたらいいのではということで終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-013"},{"speaker":"のだて委員","kind":"質問・要望","question":"取次サービスをやっていくことは、地域の住民にとっても利益があると思うのですけれども、それを委託していくということになると、利用者のプライバシーの問題といいますか、どういった本を読んでいるかということとか、そういったことが流出というのでしょうか、個人情報が外部の人に知れてしまうというのでしょうか、その情報流出の問題があると思うので、委託はやめるべきだと思いますけれども。","respondent":"品川庶務課長、熊谷指導課長、大関教育総合支援センター長、横山品川図書館長","answer":"こういうところが困難な部分については、今後、委託を入れていくというような考えです。授業内容と関係のない調査を実施するのはどうかというご質問でしたけれども。あるいは、学校には行けていないけれども、夕方、児童センターへ行ってバンド活動をやっているなどというお子さんもいらっしゃいますので。もう１点のプライバシー配慮につきましては、個人情報には配慮して、返却の本を受け取った段階でデータを不可視化すること、また。","voiceIndex":39,"id":"exchange-014"},{"speaker":"のだて委員","kind":"質問・要望","question":"一方、直接雇用の職員を置くことによってさまざまな部分で教育が充実していくということになろうかと考えておりますので、そういったところからも委託化は進めていかないよう要望しておきたいと思います。マイスクールのところは、退室された後にマイスクール八潮へ通っている方もいらっしゃると、そして、支援をしっかりやっていくということでしたので、ぜひ柔軟な対応をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"「紙媒体の事典の良さの再認識」というのも、なるほどなと思いましたし、この４点のポイントは、それぞれ納得できる指摘だと思うのですけれども、ここについて再確認ですが、区として、こういう所見を提出していただいたことについての受けとめ方、それをどういうふうに受けとめておられるのか、具体的な改善の方向性が見えているのであれば、紹介をしていただきたいと思います。","respondent":"大関教育総合支援センター長","answer":"タブレットパソコンがあるから辞書が教室から消えるということはございません。は紙の辞書で調べるというのも小学生などは非常に重要な学習の内容の１つだと考えておりますので、タブレットと紙媒体と両方を使いこなせる力を育てるのが教員の仕事だと認識しています。","voiceIndex":45,"id":"exchange-016"},{"speaker":"南委員","kind":"確認","question":"校長連絡会を通じて各校に伝えるということで、各学校にこういう指摘があったということは伝わっても、その先まで、先ほど教員が共通認識を持っているから指摘されたところを受けとめてやりますという認識をしていいのですか。強調というふうには思わないけれども、改めてそこのところを再確認していただけるような教育委員会の働きかけを改めてお願いをしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-017"}]},{"id":"topic-02","title":"学事制度審議会第１４回～第１７回の報告","agenda":"学事制度審議会第１４回～第１７回の報告","exchanges":[{"speaker":"渡部委員","kind":"意見","question":"中間答申が出た後に関するご報告で、まずは正副にぜひお願いなのですけれども、３月２２日に最終答申が出ると書いてありますから、その後の４月１６日に文教委員会がありますので、その中でゆっくり説明していただいて、それに対して私たち議会としてもいろいろな意見がございましょうから、その最終答申がまとまっていて出していただけるようであれば、文教委員会で審議をする機会をいただければと思います。","respondent":"つる委員長","answer":"正副で検討します。","voiceIndex":52,"id":"exchange-018"},{"speaker":"渡部委員","kind":"質問・要望","question":"今回、１つだけ確認したいのが、議事録も１４回、１５回、１６回まで出ていましたから、私ある程度見て、中間答申から、この最終答申に向かって、この間に教育委員会が開かれて、何か大きな変更が出そうなのかどうなのかお話しできる範囲でいいので聞かせていただきたいと思います。","respondent":"篠田学校計画担当課長","answer":"ただ、細かい部分でさまざまご指摘いただいたもので、例えば、中間答申で審議会の中で議論されたことがうまく伝わっていないのではないかといったようなこともございましたので、そういった点については、細かく、より丁寧に説明を加えていこうといったことですとか。","voiceIndex":54,"id":"exchange-019"},{"speaker":"渡部委員","kind":"意見","question":"わかりました。そのお話が聞けましたので、逆に、今どうこうというよりも、やはり出た後、それをどう生かしていくかというところに論点が移っているような気はいたしますし、委員の方々がそれぞれ結構な回数の審議会に出席されて、それぞれのお立場でお話をされているということが手にとるようにわかりますので、そこは全然心配なく進めていただけていると考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":56,"id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"パブリックコメントについては、件数が全体で何件あったのか、数字だけ教えていただきたいと思います。それが１つです。しかし、先ほども申したように、地域の中では、そういう選択をして地域の学校以外のところに行くことについていろいろな混乱があったのだなということを私は思ったのですけれども、その辺について、教育委員会としてはどういうふうに認識されているかを伺いたいと思いました。","respondent":"篠田学校計画担当課長、大関教育総合支援センター長","answer":"これに関しましては、基本的に今、教育委員会で取り組んでおります地域とともにある学校づくりという中で、地域の方々からも１つのご意見として。５・６年生の子どもたちは、７年生、８年生、９年生の姿を見ながら、さらに伸びていきますので、４・３・２の枠組みは、本区にとって非常に成果のある取り組みだというふうに認識しています。","voiceIndex":57,"id":"exchange-021"},{"speaker":"南委員","kind":"質問","question":"今のリーダーシップのところですけれども、確かに学年に応じた発達も当然あるし、そこの発達を飛躍的に引き上げるためにいろいろな手立てが講じられて教育活動が行われるわけですから、それは重要なことだと思うのですけれども、私が心配するのは、今の説明では、４・３・２の流れの中で１つの一番下のグループとして４年生の存在がある。ですから、もしあれば紹介してください。","respondent":"大関教育総合支援センター長","answer":"繰り返しになりますが、６年生のリーダーシップはしっかり小学校で育っております。近隣の中学校あるいは義務教育学校に６年生が出向いていって７年生体験をやるなどの取り組みも実際にやっております。","voiceIndex":60,"id":"exchange-022"},{"speaker":"南委員","kind":"質問・要望","question":"混乱がないということであれば、それはそれでいいのだろうと思うのですけれども、しかし、私たちは４・３・２の、そういうグループ分けの中で育っていないわけですけど、単独小学校、単独中学校があって、そういう経験をしてきている人たちが、この審議会にもメンバーとして入っているから、そういう疑問がいつも出るわけですね、私も含めて。そのことを改めてお願いをしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-023"},{"speaker":"のだて委員","kind":"質問・要望","question":"先ほど、パブコメの意見の件数はあったのですけれども、主にどういった意見があったのか、そして、それに対する教育委員会の見解はどうなのかをまず伺いたいと思います。第１７回目の内容ですが、先ほど少しご説明がありましたけれども、この中身をもう少し詳しくご説明いただければと思います。","respondent":"篠田学校計画担当課長","answer":"第１７回の審議内容ですけれども、今回は、最終答申の案文も整理して、それを検討していただいているものですから、なかなか意見というと、案文の文章の表現がどうだとか、この辺の図がちょっと見づらいかななどの意見もありましたので。","voiceIndex":63,"id":"exchange-024"},{"speaker":"のだて委員","kind":"質問","question":"パブコメの意見については、今、整理中で、今後報告するということですので、よろしくお願いいたします。こういった部分も、今後、最終答申で資料とかに載ってくるということになるのか、それもあわせて伺えればと思います。それを４・３制にするというところで、本当に発達段階に合わせたものになっているのか、伺えればと思います。","respondent":"篠田学校計画担当課長、大関教育総合支援センター長","answer":"というのは、学校選択制、学区域の問題といったものと直接かかわる話ではないですけれども、ただ一方で、義務教育学校のあり方等は教育制度にかかわってくる部分が多くありますし、特に今回。ですので、４年生の直感的あるいは具体的操作期の段階からいろいろ物事を学ぶという段階までの成長報告、それ以降、今度は中学生、義務教育学校（後期課程）の生徒としての段階に徐々に、５年生の段階から定期考査を体験したり。","voiceIndex":65,"id":"exchange-025"},{"speaker":"のだて委員","kind":"確認","question":"成果・課題のところでは、そうすると、資料として報告されたようなことが全て、載ってくるということではないと、案の中に盛り込んでいくということになるということでいいのか確認させていただければと思います。そういった発達面から見ても、なかなか難しいところだと思うのですけれども、そこのところを伺いたいと思います。","respondent":"大関教育総合支援センター長、篠田学校計画担当課長","answer":"品川区においても９年間の義務教育学校があるように、学校種によって一概に比較はできませんが、先ほど、私、世界的にと申し上げたのは、これは教育学の基礎中の基礎として１０歳の壁というのは言われているところですので。義務教育学校については、先ほどから申し上げているとおり、例えば、パブリックコメントでもたくさんのご意見をお寄せいただいていて、区民の方からすると。","voiceIndex":68,"id":"exchange-026"},{"speaker":"こんの委員","kind":"質問","question":"学校のほうなのですけれども、今、中学校のほうは、７年生が３クラス、８年生が１クラスで、９年生はありませんでしたということですけれども、学級閉鎖となる人数に至らなかったとしても、若干の人数は出たのではと予測するのですが、その状況と、高校受験をインフルエンザで受けられなかったというようなことはあったのか、その辺の状況を教えてください。","respondent":"有馬学務課長","answer":"もちろん中学校のほう、全体的に見ると学級閉鎖は少ないですが、途中経過で、１月の中旬ぐらいまで情報把握をした結果によりますと、中学校でも何名かインフルエンザにかかっております。","voiceIndex":77,"id":"exchange-027"},{"speaker":"こんの委員","kind":"質問","question":"現時点ではわからないということですが、受験生に焦点を当てた話ですが、過去にそういうケースはあったのでしょうか。受験生がいわゆるインフルエンザにかかってしまい受験日に受けられなかったみたいなことは、過去にあったかどうかというところはいかがですか。","respondent":"大関教育総合支援センター長","answer":"インフルエンザに限らず、体調不良で受験日に欠席というケースは過去にあったかと思いますが、先週末の都立高校の受験に関しては、特にそういう報告は受けておりません。それぞれ体調管理を万全にして臨んだのではないかと考えております。","voiceIndex":79,"id":"exchange-028"},{"speaker":"鈴木（博）副委員長","kind":"意見","question":"予算特別委員会で詳しくはと思っているのですけれども、１点だけ。資料に、学級閉鎖の休業期間に日曜日が入っているところと入っていない学校があるのですけれども、日曜日はもともと休みですよね。意味がよくわからないのですが。","respondent":"有馬学務課長","answer":"日曜日は、例えば５７番の八潮学園などは、２月４日と日曜日が入っていますけれども、ちょうどこの日は作品展があって、子どもたちが出てくる日ということです。","voiceIndex":82,"id":"exchange-029"},{"speaker":"鈴木（博）副委員長","kind":"質問","question":"正規の登校日ではないのだけれども、登校しなければいけないときに、この日は来なくていいですよということで休業期間に日曜日が入っているのですね。よくわかりました。今年は都立高校では、インフルエンザになった場合は、日にちを変更して試験をして受けられるみたいだという報道があったのですけれども、それは事実でしょうか。","respondent":"有馬学務課長","answer":"そういう予備日を設けて、再試験日というか、そういう日を設けたというふうに聞いています。","voiceIndex":86,"id":"exchange-030"}]},{"id":"topic-03","title":"中延二丁目認可保育所整備・運営事業者の選定","agenda":"中延二丁目認可保育所整備・運営事業者の選定","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今、説明があったので、ここに書いてある内容はわかったつもりでいるのですけれども、確認のために伺いたいと思います。貸付期間が２５年６カ月ということなので、なぜ６カ月という、中途半端な数字であるのかと思ったのですが、開設準備期間等を含むということですか。","respondent":"大澤待機児童対策担当課長","answer":"時期のご質問ですけれども、平成３０年４月から事業者にお貸しして、平成３１年４月までの間に保育園を建てていただき、平成３１年４月に開園する予定です。","voiceIndex":92,"id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"できたら、定員１０７人の年齢構成とその定数をわかる範囲で教えていただきたいです。病児保育については、医師の配置についてはどういうふうに考えているのか、１年先とはいっても、時間はすぐに経ってしまうと思うので、病後児では医師の配置を品川区は求めて医療機関にお願いしているという経過もある中で、病児保育の医師の配置はどういうふうに考えているのかを教えていただきたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"定員の内訳です。０歳児が１２名、１歳児が１５名、２歳児が１８名、３歳児が２０名、４・５歳児が２１名ずつを予定しております。ただ、これはあくまでも提案段階ですので、今後、区との調整の中で変わってくる可能性はあります。","voiceIndex":94,"id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"ただ、さっき言ったように、これだけの規模の子どもたちの遊べるスペースが確保されることが望ましいと考えていますので、そのあたりはどういうふうに考えたらいいのか、設計もまだ途中の段階なのかと、想像ですけれども、でも、もう建設が始まっていくという時期から見れば、ある程度固まってきていると思いますので、そのあたりのことも教えていただきたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"それとは別に３階に７８m2の遊戯場をつくるということでご提案をいただいております。残念ながら１２１m2の園庭では、屋外遊戯場としての必要面積の半分にしかなりませんので、この園庭とは別にどこか近くの公園を屋外遊戯場として指定することになろうかと思います。","voiceIndex":96,"id":"exchange-033"},{"speaker":"南委員","kind":"確認","question":"３階に吹き抜けで７８m2の遊戯場を作るということなのだろうと思うのですけれども、遊戯場というと、私の認識では、保育室のほかにあるいわゆるホール、そういうものなのかなと思っていたのですけれども、吹き抜けだから必ずしもそうではないというふうに思うのですが、ここの３階にできる遊戯場のほかに、１階や２階に、いわゆるホールは設備されるのかどうかを確認して終わりたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"３階の吹き抜けのお部屋は、委員おっしゃるとおりに、保育園のホールというイメージで、保育室とは別に広く遊べるお部屋というふうに捉えていただいていいかと思います。","voiceIndex":98,"id":"exchange-034"},{"speaker":"南委員","kind":"質問","question":"さきほど終わりと言ったのですけれども、済みません。吹き抜けの３階の遊戯場は、７８m2だから、決して広くないと思うのですけれども、しかも吹き抜けであるので、壁をつくることになるため、日当たりのことも気になるし、そういう意味で子どもたちの遊ぶスペースとしては適切と言えないと私は思うのですけれども、そういう関係でどうなのか伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"１階は、庭が１２１m2と、病児保育室と０歳児保育室と１歳児保育室です。２階に、２・３・４・５歳児の保育室があって、３階に遊戯場、いわゆるホールを設置するという計画で、そちらのほうは日当たりをできるだけよくするために、天窓というご提案を受けているところです。","voiceIndex":102,"id":"exchange-035"},{"speaker":"のだて委員","kind":"質問","question":"この２５年６カ月という貸付期間についてです。保育園開設に当たって、今回、品川区内でこころケアプランが開設するのは５園目になると思うのですけれども、今年の４月時点で４園あって、またその次の年に開くので、保育士の確保とか、そういった面はどうなのかということも伺えればと思います。","respondent":"大澤待機児童対策担当課長","answer":"２５年の理由ですけれども、保育需要が今後２０年から２５年続くというふうに見込んでいる中で、プロポーザルが始まるずっと前から、保育事業者の何社かに聞き取りをしておりまして、事業者が採算を考えると、２０年ではちょっと苦しいというようなお話もございましたので。","voiceIndex":104,"id":"exchange-036"},{"speaker":"こんの委員","kind":"質問","question":"ちょっと感覚的な話で恐縮なのですが、私もいろいろな自治体の議員と話をする機会で、品川はなぜこのように開設が進むのか、こんなに保育士を確保するのが大変と言っている中で、新規開設を毎年できるのはなぜということを聞かれることもあるのですが、品川区としては、他の自治体と比べてというのはあれなのですが、これだけ新規開設をして定員を増やしているその努力というか。","respondent":"大澤待機児童対策担当課長","answer":"現在、大体８月までに全て決まるようなスケジュール感で進めておりますので、そういうことも少し成果としては見えてきているのかというふうに考えております。","voiceIndex":106,"id":"exchange-037"},{"speaker":"高橋（し）委員","kind":"意見","question":"私立保育園の運営には、いろいろ助成といいますか、家賃補助等しているのですが、公設民営の場合、ほかにもぷりすくーる西五反田やひろまち保育園、ひがしやつやま保育園がそうだと思うのですが、今回の貸付の条件だとか、そういった貸すための費用といいましょうか、一定のルールがあると思うのですが、金額はどのようにして決めているのかをお尋ねします。","respondent":"大澤待機児童対策担当課長","answer":"区としましては、事業者に土地の賃借料ということでいただくことになっています。その後の建設に関しましては、民設ですので、ほかの保育園の開設の場合と同じように、国や都からも補助金は出ます。","voiceIndex":109,"id":"exchange-038"},{"speaker":"高橋（し）委員","kind":"質問","question":"ということは、先ほどの福祉施設のように、賃貸料は地価の半額でということなので、そのほかのいわゆる家賃補助だとか、保育士への補助だとか、そういう保育の特有の補助ではないということですか。そういうものは置いておいて、福祉などと同じように、賃借料については、保育園に限らずそういった軽減のルールがあって、それでやられているということでいいでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"土地の賃借料については、福祉施設の場合は、いろいろな条件がありますけれども、半額、２分の１程度というのが目安になっておりまして、それに合わせた形で賃借料をいただきます。","voiceIndex":113,"id":"exchange-039"},{"speaker":"南委員","kind":"質問","question":"ごめんなさい。さっき聞けなかったので質問します。この保育園には室内の園庭がないので、この遊戯場が室内の園庭に相当し、採光のための天窓なのだというふうにおっしゃった、そこと吹き抜けとの関係がよくわからないので、ごめんなさい、もう一度教えてください。","respondent":"大澤待機児童対策担当課長","answer":"園庭は、１階に１２１m2あります。それとは全く別に３階に７８m2のホールがあります。そのホールについては、日当たりがいいように天窓にするということで提案を受けています。","voiceIndex":115,"id":"exchange-040"}]},{"id":"topic-04","title":"公有地活用による公設民営型保育園の開設","agenda":"公有地活用による公設民営型保育園の開設","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回の場合、公設民営保育園で、先ほどは土地を区が貸し出しして私立園にということでしたけれども、どういった判断で公設民営になるのか、土地を貸し出すと私立園になるのか、そういったところを教えていただければと思います。アクセスが入り乱れるような形になってしまわないか懸念するのですが、どういった形になるのか伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"入り口の説明ですが、図が小さくて申しわけございません。黄色い図の左側のほうにある「保育園」というのが、この公設民営保育園の入り口です。それから、真ん中辺にある「地域」と書いてあるところは、この保育園と地域の間には境目があります。","voiceIndex":122,"id":"exchange-041"}]},{"id":"topic-05","title":"保育園の改築","agenda":"保育園の改築","exchanges":[{"speaker":"南委員","kind":"質問","question":"新しく東大井保育園・児童センターが平成３４年度から開設になる、大井保育園は平成３７年で、説明はわかったのですが、新しく改築された施設の規模について、今までと同じ規模が確保されて開設となるのか、そのあたりを教えてください。","respondent":"吉田保育施設調整担当課長","answer":"日影規制など、高さに対する影ができる範囲の制限も当時と基準が異なっていたりしておりまして、高さについての制約もあります。今後、実施設計に入りますけれども、現状と全く同じ大きさのものが建てられない状況です。","voiceIndex":129,"id":"exchange-042"},{"speaker":"南委員","kind":"確認","question":"１人当たりの広さについて基準がありますが、そういうことは当然クリアされるということでいいのかということを確認したいです。","respondent":"吉田保育施設調整担当課長","answer":"何歳児に対する何平米という決まりについては、保育の基準によって定められているので、それを下回ることはありません。","voiceIndex":131,"id":"exchange-043"},{"speaker":"南委員","kind":"意見","question":"東大井保育園は、道路ぎりぎりで、園庭を少し残してぎりぎり建っているはずですね。歩道もすごく狭くて、なかなかあそこで送り迎えをするお母さんたちも苦労していらっしゃる、そういうふうに見えるのです。そういう中で、園庭といえるのかと思うような園庭もなくなってしまうという感じなので、非常に残念だなと思うのですけれども、それは意見として言っておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":133,"id":"exchange-044"},{"speaker":"のだて委員","kind":"質問・要望","question":"この保育園の改築について、今、いろいろなところで改築を進めておりますが、全体的な考えといいましょうか、どこから進めていくとか、そういった考えをお伺いしたいと思います。今、民営化が進められておりますけれども、この２園を民営化していくということはないか確認させていただきたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"代替地の確保が速やかにいかない場合がありますので、代替地が見つかり次第、もしくは条件が合うものがあった段階で徐々に行っていくという形式を今のところはとっております。それから、今回の２園の民営化につきましては、今のところ、まだ計画はしておりません。","voiceIndex":134,"id":"exchange-045"},{"speaker":"のだて委員","kind":"質問・要望","question":"民営化をしないように求めて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":136,"id":"exchange-046"},{"speaker":"高橋（し）委員","kind":"質問","question":"仮設園舎のほうなのですけれども、児童センター機能が３階にあるということで、今、在宅の子育ての方々への支援をされているのですが、仮設園舎の３階に使いやすくものをつくるのはなかなか厳しいのかもしれません。新しくなった児童センターとかそういうところは、エレベーターを取りつけて利用しやすいようになっているのですが、仮園舎については、その辺はどうでしょうか。","respondent":"吉田保育施設調整担当課長","answer":"この仮園舎につきましては、エレベーターをつける予定でおります。","voiceIndex":137,"id":"exchange-047"},{"speaker":"高橋（し）委員","kind":"質問","question":"もう１つ、東大井公園の隣の元芝アパートが廃止ということをお聞きしていますので、この平成３２年になったときにまたそういった話になると思うのですが、そちらの解体工事や何か、どうなのかわかりませんが、それと重なって、仮設園舎に通われることになったりということも考えられます。その辺のお話で、ちょっと所管が違うかもしれないので申しわけないですが、わかる範囲で結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":139,"id":"exchange-048"},{"speaker":"高橋（し）委員","kind":"質問","question":"仮設園舎にお子さんが通われるときには、もう解体をしていないということなのですか。","respondent":"吉田保育施設調整担当課長","answer":"今のところ、解体時期は、保育園に通われる方の影響は出ないのではないかというふうに理解しております。","voiceIndex":144,"id":"exchange-049"}]},{"id":"topic-06","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"南議員の保育に関する質問の答弁の中で、二次の空きが９８４名で、認証の枠も３１６名あるということでしたけれども、二次の空きと認証保育所の枠、両方の、０から２歳の空きは、年齢別で何人なのか伺いたいと思います。既に認証保育所に通っている０歳、１歳の子で何人が認可保育園に入れたのかも伺います。どうやって把握していくお考えなのか伺いたいと思います。よろしくお願いします。","respondent":"大澤待機児童対策担当課長、熊谷指導課長","answer":"入園の二次の空き状況です。０歳児が１０名、１歳児が８名、２歳児が５６名となっています。次に、認証保育所から認可保育園に一次で内定の出た方の数は、１歳児が１１９名、２歳児が１４８名となっています。教員の長時間労働の現実を教育委員会としてどのように認識しているのかというお尋ねですけれども、長時間労働は、過労死等を発生するリスクを高める重大な課題であると認識しております。","voiceIndex":148,"id":"exchange-050"},{"speaker":"のだて委員","kind":"質問","question":"認証保育所の枠の中で、０歳から２歳の空きが何名だったのかということもお聞きしたので、それについてもご答弁いただければと思います。東京都の実態調査の件ですけれども、そうすると、ご答弁の中では、品川の結果が出たのかと思ったのですが、あれは品川のものではないということでしょうか。","respondent":"大澤待機児童対策担当課長、熊谷指導課長","answer":"認証保育所の４月の空きは、区の認可保育園の二次の結果が出た後に公表になりますので、今のところ、３月２０日頃を予定しております。本会議で答弁させていただいた１日の平均１１時間５２分、それから在校時間が週６０時間を超えた教員の割合は約５１％ということにつきましては、本区の抽出校のデータであります。","voiceIndex":153,"id":"exchange-051"},{"speaker":"のだて委員","kind":"質問・要望","question":"つまり、０歳で待機児童が出るのではないかということです。土日出勤の把握では、教員からの報告とか施設管理日誌を確認することもあるということでしたけれども、それによって適切に正確に勤務実態を把握していくということができるのかということも改めてお伺いしたいと思います。","respondent":"大澤待機児童対策担当課長、熊谷指導課長","answer":"０歳児の不承諾数のお尋ねですけれども、現時点で昨年の実績等から予測できる範囲で不承諾数から待機児童に含まない数を引くと、０歳児は、今の時点では７名ぐらいであろうというような見込みを立てております。ですので、一概に学校に来たからといって、勤務をしている、そこの部分だけを勤務とするということはできないと思いますので、やはりワーク・ライフ・バランスを考えたときには、まずは個人からの報告であったり。","voiceIndex":156,"id":"exchange-052"},{"speaker":"のだて委員","kind":"提案","question":"そういったところで教員の報告や施設管理日誌を見てというお話もありましたけれども、やはり、しっかりと実態を把握していくということをぜひやっていただいて、この間私たちが提案していますけれども、人を増やしていく、そういった中で少人数学級の導入なども含めて、教員の多忙化解消をしていっていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":159,"id":"exchange-053"},{"speaker":"南委員","kind":"質問・要望","question":"企業型保育所に申し込んだわけではなくて、やむなく不承諾を受けてしまったので、働かなければいけないから企業型保育所も含めて申し込みをするという、こういうことになるわけですから、入られて安心して働ける分にはいいけれども、そういう数も含めて、待機児童だというふうにカウントしなければいけないと私は思うのですけれども、その辺の認識はどうなのでしょうか。","respondent":"熊谷指導課長、大澤待機児童対策担当課長","answer":"施設管理日誌ですけれども、学校によって異なりまして、施設管理員が書く学校もありますし、本人が書く場合もあります。平日につきましては、出退勤システムがありますので、そちらで管理しているということなります。先ほど申し上げた７名というのは、企業主導型を入れずに７名なので、その方たちが企業主導型保育園を利用すれば、一定解消できるのではないかという説明です。","voiceIndex":160,"id":"exchange-054"},{"speaker":"南委員","kind":"提案","question":"保育のほうです。それには、私も代表質問で提案しましたけれども、やはり緊急対策として、区が責任を持って保育園を増設する、どういう形であってもつくるということしか解消方法がないと思いますので、ぜひそこは本当に具体的に検討をしていただきたいということをあえて要望しておきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":163,"id":"exchange-055"},{"speaker":"のだて委員","kind":"質問","question":"東京の勤務実態調査なのですけれども、ご答弁いただきましたのは中学校のものだったと思うのですけれども、小学校のほうはわからないのでしょうか。","respondent":"熊谷指導課長","answer":"抽出校ということで、学校名等も公表できない、校種等も公表しないということになっておりますので、答弁申し上げた内容でご判断いただければというふうに思います。","voiceIndex":164,"id":"exchange-056"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4936#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":59988,"voices":173}},{"id":"h30-20180227-5","meetingId":"h30-cm02","date":"2018年2月27日","dateIso":"2018-02-27","committee":"総務委員会","time":"午前１０時００分～午前１１時１６分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を20件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の「平成３０年度組織改正（案）」","agenda":"の「平成３０年度組織改正（案）」","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"順番にお伺いします。これが、プラス１の職員が増えた部分がここに行くのかどうかということと、テロなどの脅威という部分と、自然災害とは全く異質のものだと思うのですが、どうして防災のほうに行ったのか。もう一回、そこのところをお伺いしたいのが１点です。呼び方の問題なのですけれども、「担当（主査）制」と「担当（主査）」の違いを１点教えていただきたいと思います。","respondent":"柏原企画調整課長","answer":"国民保護担当は、これまでの国民保護計画は防災課で所管してつくってありますので、そういったところのつながりで、国民保護担当というものを防災課の中に設置して、連携体制が強化できるようにという意味合いです。それから、２点目のところです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"子ども未来部のところなのですけれども、ここのところは区長も施政方針の中で、この８年間で保育の施設関係を２倍に増やしましたとおっしゃっておられるように、保育園に限らず、いろいろな保育の施設が増えているので、その支援体制がものすごく必須となっているなと感じたのです。その辺がどのように厚くなっていくのか、もう少し詳しく教えていただきたいと思います。","respondent":"柏原企画調整課長","answer":"組織上、区といたしましても、特に総合的な待機児童対策というところで進めている部分においては、特に私立の保育施設の開設支援というものが業務的にも拡大してきたというところがあります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今の続きなのですけれども、保育課のところは、多分、最初の段階で職員５１名になっていたかと思うのですが、先ほどプラスになったところがここに入るということなのか。特に新設されている保育支援課がどういう人数体制になるのか、わかったら教えていただきたいのが１点です。２ページ目の福祉のところなのですが、介護・医療連携担当、ここはいいです。ごめんなさい。ここを教えてください。","respondent":"柏原企画調整課長","answer":"これにつきましては、これから区といたしましても、いわゆる健康への施策は非常に大切だろうという認識のもとで、特に保健衛生業務、これは専門職も含めてですけれども、今、庁舎の中にあります保健所、それから、健康課、それから。","voiceIndex":9,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１つは健康のところなのですが、健康づくりはとても大事。その辺について、充実していくとか、厚くしていくというお考えはあるのかどうかということ。特に一番大事な出会いの窓口の業務の精度を上げていただきたいなと思いますので、その辺はよろしくお願いいたします。","respondent":"柏原企画調整課長","answer":"先ほど少し触れましたけれども、専門職も含めて、そういった連携であったり、そういった部分の充実は、施策実施に向けて充実を図れるようにということでのポスト設置です。","voiceIndex":11,"id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"今の質問の続きのようになりますが、障害者福祉課のところです。今まで一つ一つのご相談が、本当に人についていた感じなのです。係の方の能力の問題ではなく、やはり数が足りないのではないかということをおっしゃるのです。この体制で、新設という形で工夫されていくということなのですが、実際、仕事の量との関係で言うと、それをどのようにスムーズにこなしていかれるのかということを伺いたいと思います。","respondent":"柏原企画調整課長","answer":"これは、ほかの部署でもそうですけれども、区民の方々がご利用される際に混乱のないようにということで、今回は４月１日スタートということで予定しておりますけれども、その前には周知をということで、少なくとも３月の終わりの広報紙には周知できるような形で動いております。","voiceIndex":13,"id":"exchange-005"},{"speaker":"吉田委員","kind":"質問・要望","question":"地域の中に分けないというところがあるので、特にその辺はきめ細やかにしていただきたいと思います。決算特別委員会でも質問しましたけれども、児童の計画相談については、国の計画ではとっくに全部済んでいなければいけないのが、まだ全然済んでいないというところでは、実際にそういうことも起きておりますので、今後、一層その辺は気を配っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-006"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"少し確認させていただきたいのですが、危機管理のところで、「その他の危機管理室業務については総務課に引き継ぐ」と書いてあるのです。それぞれ新設の係等ができていますが、これはトータルでいわゆる係長たちが増えるということなのか。なぜかと言うと、今管理職の担い手不足ということが言われている中で、品川区においては、その辺がしっかりとされているのかということも含めて確認させてください。","respondent":"柏原企画調整課長","answer":"係長の部分に関して、ポストの部分ですけれども、これは人員配置がまだですから、組織のポストということで言いますと、係長のポストは１減になります。","voiceIndex":16,"id":"exchange-007"},{"speaker":"石田（し）委員","kind":"意見","question":"総務のほうで全体的な危機管理の部分を行って、各所管で事柄によって動いていくというのは理解するのです。例えばＢＣＰというのは、ずっとこれまで総務課の危機管理室を含めて担当されていて、災害が起きたときに、外の部分はもちろん防災まちづくり部でやられるのでしょうけれども、内部的な部分に関しては、引き続き総務課で担当されるのかどうか。そこだけ最後によろしくお願いします。","respondent":"柏原企画調整課長","answer":"ご指摘いただいたとおりなのですけれども、今までもそういった形で災害などがあったときの部分について、防災まちづくり部が外の動きをやったり、内部でも当然動いてはいるのですが、トータルの内部の調整は危機管理室、総務課が行うところですので。","voiceIndex":18,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"品川区のホームページなどを見たときに、今だと危機管理室ということで、はっきり連絡先がわかると思うのですが、名称はそのまま残るのですかね。これでいいのでしょうか。国民保護とは何ですか。我々は、いろいろ議会でも勉強しているからわかるのですが、国民保護とは何を保護しているの、ということになって、この名称が果たしていいのかなというのは、少し疑問に思うのですが、どうなのでしょうか。","respondent":"柏原企画調整課長","answer":"あまり名称が長過ぎてもわかりづらいという逆の面が出たりするので、いろいろ中でも検討したところでありますけれども、この保育支援という形で行きたいと思ってあります。福祉部のほうです。","voiceIndex":20,"id":"exchange-009"},{"speaker":"須貝委員","kind":"質問・要望","question":"理由はわかりました。職員の組織、区が運営するにあたっての組織はよくわかりました。これを読めばよくわかるのですが、一般の区民が見て、今はいろいろなホームページから何から、さまざま区民に開かれたというか、どこで誰が見てもすぐに品川区の情報をつかめます。やはり区民にとってわかりやすい言葉が、開かれた品川区、身近な品川区につながると思うので、何かうまい工夫をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-010"},{"speaker":"あくつ副委員長","kind":"質問","question":"３点お伺いしたいと思います。福祉部の介護・医療連携担当の主査の新設なのですけれども、これは私どもの会派からも以前、質問させていただいたことがあるのです。そういう医療的、医学的な知識がないと、当然やりとりはできないと思うのですが、その辺についての方向性を伺いたいのが１つ。たしか係長は保健師だったなと思って、そこのところを伺いたいと思います。そこについて伺いたいと思います。","respondent":"柏原企画調整課長","answer":"ただ、今おっしゃっていただいたように、介護・医療の部分、それから、保健医療の部分、認知症の部分は、医療と密接な関係がありますので、そういったところも考えながらですが、ご報告としては、今日お話しした組織のありようといいますか。","voiceIndex":23,"id":"exchange-011"},{"speaker":"吉田委員","kind":"確認","question":"すみません。言葉の端を捉えるようでまことに申しわけないのですが、先ほど障害者相談支援担当の係長を複数置くので、「例えば」とおっしゃったのであえて言わなかったのですけれども、地域割というのが、そのようになってしまうのでしょうか。そこがとても気になります。この係長複数制ということで、そういう方向だと理解したほうがいいのでしょうか。その辺を確認だけさせてください。","respondent":"柏原企画調整課長","answer":"そういったところを含めて、所管で今検討していると聞いております。","voiceIndex":25,"id":"exchange-012"},{"speaker":"飯沼委員","kind":"質問","question":"すみません。今のところなのですが、私たちも障害を持っていらっしゃる皆様お一人お一人が相談先を選べる。地域割にはしていただきたくないなと思っています。１点はお願いです。そういった意味で、「旧」のところを見たら、庶務課に学校計画担当課長が一緒になっているのですけれども、この課長のポストはそのままなのでしょうか。そこをお願いします。","respondent":"柏原企画調整課長","answer":"特に担当課長、担当部長等につきましては、現段階ではまだ決まっているものではございません。これは、人員の配置の部分もありますので、今、組織としてお示ししたのは、こういった内容が決定といいますか、この形でご報告をさせていただいてあります。","voiceIndex":27,"id":"exchange-013"}]},{"id":"topic-02","title":"平成３０年度都区財政調整について","agenda":"平成３０年度都区財政調整について","exchanges":[{"speaker":"石田（し）委員","kind":"提案","question":"都区の財政調整で、２３区側から標準区の経費見直しについての提案を６６項目出されていて、この資料の中にも、幾つか「新規算定」と書いてあるのです。これは、どのくらい反映されているのか。具体的ではなくてもいいのですけれども、全体的にどのくらい区が要望したことが受け入れられているのかというのをお聞きしたい。これは、今どのような状況になっているのか。その点もあわせて教えてください。","respondent":"秋山財政課長","answer":"都区のあり方です。事実上、動いておりません。特別区側からも、あり方の検討を進めたいということで、平成２９年度版から、東京都への要望事項の中に、検討を進めるということを入れております。これについては、引き続き要望していくというつもりでおります。","voiceIndex":34,"id":"exchange-014"},{"speaker":"石田（し）委員","kind":"質問","question":"引き続き頑張っていただければなと思います。今、個別案件が出て、児童相談所については、区としても、これから平成３０年度の予算審議になりますが、ここでも準備の経費が上がってくるのかなと思うのです。今回、都区財政調整には入ってこないということは、この準備のものに関しては、基本的に区の持ち出しで進めなければいけないという認識なのかどうか。そこだけ少し教えてください。","respondent":"秋山財政課長","answer":"こちらは、普通交付金の算定の中で協議を整えるということを目標としておりますか、今３区が先行してやっております準備の関係の経費も出ておりますので、とりあえず区としては特別交付金で要求していこうです。","voiceIndex":36,"id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"資料１ページ目の第二の「基準財政需要額」の２のところで、毎年秋から見直しを行っていて合意をしたということなのです。今回の議論の中で、中心的な課題が何かあったのかどうか。もしあったら、それを聞かせていただきたい。方針が出された後、「平成３０年度測定単位の数値の確認を待って行う」とあるのですが、この後、作業的なスケジュールでどうやって額が決まっていくのかを教えてください。","respondent":"秋山財政課長","answer":"それを前提で臨んでおりますので、大きなものは、やはり都区の中で、今まで合意ができていない配分変更の変更事由にあたるものであるとか、先ほどもお話しさせていただきましたけれども、特別交付金の割合であるとか、都市計画交付金等。","voiceIndex":38,"id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問","question":"いろいろ議論のところで、３ページの「新規算定等の主な項目」で、平成２９年度もそうですけれども、保育のところがいろいろ新たに設けられたり、改善されていくというあたりで都の考えがあらわれていると思うので、基本的な考えがわかったら教えてほしい。ここに「国民健康保険事業助成費」と書かれていますが、国民健康保険の広域化に伴う変更などがあるのかどうか。そこも教えてください。","respondent":"秋山財政課長","answer":"東京都としても、協議を出した区側の提案を全て「だめ」と言っているものではなくて、必要なところにはつけていく考え方だと認識しています。","voiceIndex":40,"id":"exchange-017"}]},{"id":"topic-03","title":"その他」を行います。 まず、(1)の「所管質問","agenda":"その他」を行います。 まず、(1)の「所管質問","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"増減もあわせて伺います。仕事量にふさわしい職員増を求めますがいかがでしょうかという質問内容だったのです。こう答弁がありましたけれども、具体的に残業は減ったのでしょうか。具体的にその辺をお知らせいただきたいのが１点です。答弁の中に、病気休暇職員は何人ですか。増えたのですか、減ったのですかと聞いていることに対して答えがなかったのです。その辺をわかったら教えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-018"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ具体的に数字などを伺ったときは、本会議の場であっても、きちんとご答弁いただきたいと思うのです。最後のところなのです。病欠者は超過勤務、残業に起因していないというのは、どなたがどのように判断されるのでしょうか。課長が、その前の残業時間などを見て、数字的なもので判断されるのでしょうか。これは、担当課や職員からの意見を聞いているのでしょうか。あわせてお伺いします。","respondent":"黒田人事課長","answer":"直接、その席に人事課長が同席しているわけではございませんが、そういった産業医面談の内容を確認したり、その前の超過勤務の状況などを確認した上で、超過勤務が直接の病欠と関連があるとは認識していないと判断しているものです。","voiceIndex":53,"id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後になりますけれども、いろいろな方からご意見をきちんと聞いていただきたいというのは、先ほど申し上げました。メンタルの面でも、ほかの面でも、体調不良の場合は超過勤務を配慮するとか、免除されるとか、そういう手立てはとられているのでしょうか。","respondent":"黒田人事課長","answer":"保育課で言いますと、平成２８年度から平成２９年度につきましては、保育課の職員を増員するということもありますので、そういった中で必要なところには人を配置して対応しています。","voiceIndex":55,"id":"exchange-020"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2102#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":22933,"voices":67}},{"id":"h30-20180228-14","meetingId":"h30-cm02","date":"2018年2月28日","dateIso":"2018-02-28","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 ２時５４分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を89件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成３０年請願第１号 ２０２０年実施計画に基づく「品川上空飛行ルート」の中止を国交省に求める請願、(2)平成３０年請願第５号 羽田空港増便による低空飛行","agenda":"平成３０年請願第１号 ２０２０年実施計画に基づく「品川上空飛行ルート」の中止を国交省に求める請願、(2)平成３０年請願第５号 羽田空港増便による低空飛行","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"この３つの請願・陳情で、今読み上げられましたけれども、まず国交省との交渉のことについて伺いたいと思います。それで、この資料を見ますと、平成２８年４月１８日に濱野区長が武藤国土交通審議官に会って、羽田の機能強化は重要だと、日本にとって不可欠な事業であり、理解する立場ということで、しかし配慮をいただきたいということで、安全対策等々、そしてメリット等を要望しているわけですね。","respondent":"中村都市計画課長","answer":"この審議官・事務次官に面会をしたときの同席者ですけれども、まず４月１８日、審議官に面会をした際には、都市環境部長が同席をしております。その次、事務次官面会の際には都市計画課長が同席をしています。","voiceIndex":4,"id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうしますと、大臣には会われていないということなのでしょうか。ですので、国交大臣にまず先に会ってなのか、文書なのかはわからないですけれども、伝えているということが区長自ら語られているわけですけれども、ここを区は全く把握していないということなのでしょうか。","respondent":"中村都市計画課長","answer":"これは、把握することはなかなか難しいとは思いますけれども、ただ、私は同席した立場として、当時、事務次官にお会いしたときに、国土交通大臣にしっかりお伝えをしてくださいというふうに発言があったことを確認をしております。","voiceIndex":6,"id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"事務次官・審議官に会ったときに、国交大臣にお伝えくださいと言うのは、挨拶程度に言うことだと思うのです。誰でも。ということは、国交大臣には会っていない、国交大臣にその旨を伝えというのは、事務次官・審議官を通じてよろしくお伝えくださいという程度だったのでしょうか。","respondent":"中村都市計画課長","answer":"当然のことながら、自治体の首長が次席と面会をするということは、これは大臣にその旨をお伝えいただくというのは、これはもう暗黙の了解でもありますけれども、ただ、それを念のために、さらに口頭でお願いをしたというものです。","voiceIndex":8,"id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"区長は、もし国交大臣に会っているとしたら、勝手に行かれたということなのですか。そして、タウンミーティングで区長が、これは責任を持って語っていただいていると思うのですけれども、区長として区民に対して、それを区民は驚いて受けとめたわけです。これに対して把握をしていないというのは、どういうことなのか、これは区長に聞かないとわからないことなのでしょうか。伺います。","respondent":"中村都市計画課長","answer":"自治体の首長が行動する際に、その全てについて部長あるいは課長、そういったところの了解を得るということは、現実的ではないと思います。そういった意味からすれば、勝手に行ったという、そういった表現については、そういった認識はないところです。","voiceIndex":12,"id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問","question":"これは品川区の大問題なのですよね。それを把握しない。ですので、お友達に会いに行くとかそういうものではないわけですから、国交大臣に、品川区が被害を受けるとなって、これだけ毎議会請願も陳情も出される、これだけの問題を、区長の動きを把握していないというのは、これは問題ではないでしょうか。ですので、この了承していないという区の立場と区長の立場は、違うものなのでしょうか。伺います。","respondent":"中村都市計画課長","answer":"ただ、この理解というものは、品川区上空を飛ぶという、決してそういった意味ということではなくて、この新飛行ルート案につきましてはさまざまな課題があるということで、これに対して、国に対して申し入れを今まで行ってきているです。","voiceIndex":14,"id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですので、区長は国交大臣に会いに行っているかいないかというのは、区は全くもって把握はしていないし、そういうふうに動いた区長を、もう容認と言うか、別に構わないと。これだけ区の、品川区の大問題について、区長が、区が把握していない中で動いて、そして、この理解をするということを伝えていたということを、区はもう認めてしまうということなのでしょうか。","respondent":"中村都市計画課長","answer":"国として、国土交通省として、この影響に配慮した方策が出されたものです。これはすなわち、品川区の首長に対して要望を伝え、そして国として回答があったということで、確実に国土交通大臣に区の思いが伝わったというものではないかと捉えております。","voiceIndex":16,"id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"区長が国交大臣にその旨を伝え、その後、事務次官・審議官に会ってと、私はこのタウンミーティングでの区長の発言をもってお伺いしているので、これは区長に聞かないとわからないということですかね。もう課長たちは把握していない。では、区長は動いている本人ですから、国交大臣に会ったのか、会っていないのか、これは区長に聞かなければ、課長たちも部長たちもわからないということでしょうか。","respondent":"中村都市計画課長","answer":"私としましては、直接会ったか会わないかよりも、きちんと思いが、考えが伝わったかどうかというところが重要だと考えております。そういった意味からすれば、目的としては達成できていると考えております。","voiceIndex":20,"id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"質問","question":"思いが伝わったか伝わっていないかではなくて、しかもこの思いが、了承した思いでは困るわけですよ。私たちは。区長が国交大臣に会っているかいないか、そして何を伝えたのか、ここが最大に重要だと私は思っていまして、部長もここは把握はされていないのでしょうか。","respondent":"中村都市計画課長","answer":"区といたしまして、区の首長が国土交通審議官と、それから事務次官に伝えた思いは、こちらに今、書面があるとおりですので、確実にこれは伝わっているです。","voiceIndex":22,"id":"exchange-008"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひタウンミーティングのときの、多分議事録等もあるはずだと思いますので、ぜひそこを確認していただきたいのですけれども、まず、国土交通大臣にその旨を伝えて、もう何度も言っていますけれども、その後、事務次官・審議官に会ってお話をしてきたというふうに区長は言っているのです。そしてタウンミーティングで初めて、国交大臣にも会っていた。お願いしたいのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-009"},{"speaker":"安藤委員","kind":"質問・要望","question":"今のやりとりでも、部長さんも課長の言うとおりですということだったので、大臣に区長が単独で会いにいったかどうかは把握してないということでよろしかったのか、そういうことだと思うのですね。そこだけ確認させていただきたいのですけれども。","respondent":"中村都市計画課長","answer":"それは、確認はとれてございません。しかしながら、今日提示していただいたこの文章を拝見いたしまして、この議事録の中に品川区が飛行を了承したというような意味でとれる文章というのは、私としては感じとれないと考えております。","voiceIndex":29,"id":"exchange-010"},{"speaker":"安藤委員","kind":"質問","question":"ですから、やはり区のトップとして、国、大臣、あるいは大臣に次ぐ次席の方と一体何を話したのかというのは、やはり区民全体にとっても大問題で、その対応によっては、品川区が了承した、品川区がこの計画にゴーサインを出したということになりかねない、そういうことなので、これは絶対、私は区長に委員会として出席していただいて、そうでないというのであれば、きちんと区長の言葉で説明していただく。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問","question":"やはり、私たちはぜひ区長に聞きたいと思っていますけれども、そうではない、呼ぶべきだ、呼ばないべきだといった意見があると思うので、意見を伺いたいと思います。皆さんに。呼ぶにしろ、呼ばないにしろ、その理由を皆さんにお聞きしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-012"},{"speaker":"渡部委員","kind":"確認","question":"区長はお越しいただかなくて結構です。今、もう区の幹部職員の方々が説明をされていて、それで国交省の事務次官ですとか審議官にお会いしているということは、おのずとこれは大臣のほうに話が行くべき話になりますので。当然、区長の考えは、個人がどうこうではなくて品川区のことを考えて動いてらっしゃるわけで、そこを確認するということはもう全く必要ないことだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-013"},{"speaker":"若林委員","kind":"確認","question":"一委員としては見解はありますけれども、やはり初めてこういうことが委員会であったので、１回、その手順の確認も含めて、委員長の今の仕切りもありますので、委員長の仕切りで進めても、私はいいかなと。会派で意見をまとめてというのは、そういう過程はあってもいいかとは思いますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-014"},{"speaker":"あくつ委員","kind":"質問・要望","question":"各会派の態度をこの後、聞かれると思うのですが、その前に少し確認をさせていただいて、その上で結論については会派としては申し上げたいと思うのですが。先ほどのやりとりを聞いている中で確認をさせていただきたいところが２点あります。品川区としては、どういうことをされたのかというところを確認をしたい。時系列をまず１点、確認をさせていただきたいということ。","respondent":"中村都市計画課長","answer":"この首長の動きについて全てを把握ですけれども、公式の行事、こういったものについては当然把握はしていますけれども、ただ、細かい行事、イベント等、こういったところで同席する者について、またそこで交わされた会話。","voiceIndex":40,"id":"exchange-015"},{"speaker":"あくつ委員","kind":"確認","question":"済みません。もう１点だけ。そのタウンミーティングの際に、そのタウンミーティングの話ですよ。区長は国交大臣に会ったと、このようにおっしゃってらっしゃるのですか。そこは私も確認のしようがないので、確認をさせてもらいたいということです。","respondent":"中村都市計画課長","answer":"こちらは、審議官・事務次官のほうに面会して、大臣に話をお伝えいただくように依頼をしたところです。","voiceIndex":42,"id":"exchange-016"},{"speaker":"あくつ委員","kind":"確認","question":"ありがとうございました。私からは以上なのですけれども、１点だけ、委員長のほうにもお話というか意見を申し述べたいのですが、先ほどもほかの委員が発言をされている中で、恐縮なのですが傍聴人の方が非常に大きな声を出されて、質疑に差し支えている状況が、私は確認ができました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今、タウンミーティングのお話もありましたけれども、私たちは、会派の議員もそのタウンミーティングに参加しましたし、区民の皆さんからもお話を伺いました。そして、そのときの議事録はきっとあるのですよね。そこは確認したことがなかったので確認させていただきたいのですけれども、私どもが聞いた中では、タウンミーティングで、区民の方が区長に、この新ルートの問題について質問をしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-018"},{"speaker":"あくつ委員","kind":"確認","question":"話の途中で申しわけない。今、ここで言っていることは、先ほどの質疑、まさにそのとおりおっしゃっていらっしゃいました。ということは、会ったということはおっしゃっていないということは確認できているということですね。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、会ったものだと私たちは思っているから、代表質問でも質問したのですが、こういう公の場できちんとおこなわれている催しであるわけですから、委員長にもお願いしたいのですけれども、先ほど部長も、タウンミーティングの発言を少しこの場で紹介していましたが、やはりきちんと議事録として、資料として出していただきたいと思うのですけれども、それはお願いしたいのですけれども。","respondent":"鈴木（ひ）委員長","answer":"この場でということですか。それとも、次回のということでよろしいのでしょうか。次回のということであれば、正副で検討させていただきたいと思いますが。","voiceIndex":48,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"この後、意見を述べたら決に入るということなのですかね。その前に態度表明とかしたほうがいいのですかね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-021"},{"speaker":"若林委員","kind":"質問","question":"冒頭に質疑もさせていただいて、品川区の把握していることを詳細にお聞きしたという認識でおりますので、その必要はないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-022"},{"speaker":"石田（ち）委員","kind":"意見","question":"私たちも２月８日に国交省との懇談を、住民の皆さんと一緒に行ったのですけれども、国交省に対して、この新ルートの決定はどのようにされるのかと聞いたところ、首都圏空港機能強化の具体化に向けた協議会に理解をはかって、それらを受けて国交大臣が決定すると言ったのです。ですので、ぜひ区長に真実を聞きたいというのが私たちの思いですので、ぜひよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":61,"id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"確認","question":"それは議事録という形で、こういうことを話しましたという概要ではなく、区長が言ったことがおおむね正確に載っているというものになるのでしょうか。今こちらも確認しようと思うのですが。","respondent":"中村都市計画課長","answer":"区の公のページに載せるものですので、その趣旨をしっかり伝えるための記録として掲載がされております。","voiceIndex":69,"id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問","question":"これだけ重大な問題なのに。区の安全・安心がかかっているのにと思いますけれども。先ほど課長から、機能強化には一定理解するということで、品川区に対しても課題はあるので、それの解決に向けた懇談というか、面接だったということなのですけれども、要は機能強化に一定理解するという、このこと自体がもう新ルートへの理解ということになるのではないでしょうか。伺います。","respondent":"中村都市計画課長","answer":"この首都圏空港の機能強化についての区の理解というのは、これは繰り返しの答弁になりますけれども、世界の中の日本、そして日本国内の経済の発展、こういった趣旨について一定の理解をするというものです。ただ、品川区上空を飛ぶことについては課題があるという認識です。","voiceIndex":74,"id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"質問","question":"タウンミーティングの話を出するのですが、この場で区長は、この羽田の増便は国策として、日本の国としてオリンピック・パラリンピックを成功させるためには、インバウンドを充実していく国の政策として不可欠だと、それは理解するとおっしゃっているのです。羽田の増便は国策として不可欠だと。これは新ルートのことではないのでしょうか。伺います。","respondent":"中村都市計画課長","answer":"国が言っている機能強化は増便ということが一番大きなポイントです。これは、機能強化は増便ですが、その増便が品川区上空というふうに区としては捉えておりません。","voiceIndex":76,"id":"exchange-026"},{"speaker":"石田（ち）委員","kind":"質問","question":"機能強化というのは、より安全性を高める機能強化なら私たちも何も言わないのです。ですけれども、今回の機能強化は都心上空を巨大旅客機が低空飛行すると、この品川にとっては超低空で飛行するというのが機能強化策ですよね。ですので、この機能強化というのは新ルートも含まれ、品川上空低空飛行も含まれているということだと思うのですけれども、いかがでしょうか。","respondent":"中村都市計画課長","answer":"事実といたしましては、この新ルートは品川区上空を飛行する、こういった案が出されたものです。ただ、区が理解しているという理解の意味は、それとは別のことで、先ほどの答弁を申し上げたとおりです。","voiceIndex":78,"id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"提案","question":"これだけ請願も陳情も出されて、この新ルートのことが問題になっていまして、それに対して区長が発言したことが大きな問題になり、そしてそれに対してもう課長たちが火消しにかかっている、そういう感じにしか受け取れません。ですので、これはぜひお認めいただいて、この機能強化イコール新ルートということで議論を進めていきたいのですけれども、いかがでしょうか。","respondent":"中村都市計画課長","answer":"ただ、これについて国のほうではまだ案がとれたというような認識はないということ、また、品川区がこれを了承した、あるいは了解した、こういった認識も国としてもない、これは当然区のほうもそういった回答をしていないものですから、当然ではありますけれども。","voiceIndex":80,"id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"もう、この場では、課長としては機能強化イコール新ルートというふうには言えないのかなということだと思います。それで、先ほどもありましたけれども、こうした区長の直接の面接によって、品川区関連の配慮事項につながったとおっしゃっていますけれども、これは配慮事項といっても、全くもって区民が求めるものではないですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":82,"id":"exchange-029"},{"speaker":"安藤委員","kind":"質問・要望","question":"先ほどの議事録の話なのですけれども、やはり抜粋なのですよ。ですから、これはちょっと不十分なので、やはり資料請求をします。ぜひすべきだと思いますし、生のデータはあると思うのですよね。データを出していただきたいというか、データをそのまま文字に起こしたものを出していただく必要が、私はあると思いますので、まずはそのことを委員長に求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":84,"id":"exchange-030"},{"speaker":"渡部委員","kind":"意見","question":"もう先ほどと全く同じで、区のしかるべき幹部の職員の方々、区長と同席をして審議官なり事務次官と会っているということは、もう国土交通省と会っているということで、もうイコールですので、これ以上必要ないと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":86,"id":"exchange-031"},{"speaker":"若林委員","kind":"意見","question":"この、いわゆる羽田関連についての質疑の中では、もう一定の質疑、本当に理解、認識できる質疑が私はあったと認識していますので、この場で請求はどうかと聞かれれば、もう必要ありませんという答えです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":87,"id":"exchange-032"},{"speaker":"安藤委員","kind":"質問・要望","question":"それは、でも皆さんの判断ですから、それは判断の自由はありますけれども、意見だけ述べします。結局、機能強化は理解していますけれども、新ルートは理解していませんというのは、誰がどう聞いても、普通の感覚の区民の人が聞いたら、それって違うことなのですか。これはないと思うのですけれども、私はイコールとして国が出していると思うのですけれども、そちらはどうなのでしょうか。伺いたいと思います。","respondent":"中村都市計画課長","answer":"国から出された今回の新飛行経路案に対しましては、さまざまなルートを検証したですけれども、やはり一番、国としても目標を達成する、実現するための方法としては、今回の新ルートが最適だと、そういう説明を受けております。","voiceIndex":91,"id":"exchange-033"},{"speaker":"安藤委員","kind":"質問","question":"しかも、１１月３０日の行革委員会の請願審査の中で請願の内容に書いてあったのですが、なぜ４３年前の区の判断が今回変わったのですか、以前は反対していたじゃないですかと聞いたら、課長さんが、過去にルートの変更案があったときには、さまざまな案の中でもっと品川区にとっていい案があったということで、そちらを採用してくださいということであったと。もう一度伺いたいと思います。","respondent":"中村都市計画課長","answer":"国の機関であります国土交通省の考えとしては、日本が諸外国と対等に経済活動が行われる、そういった地位をしっかりと維持していく、こういった大きな目標があるという、これは区としても国の動きに対して理解をするというところで。","voiceIndex":93,"id":"exchange-034"},{"speaker":"安藤委員","kind":"質問","question":"そうした国に理解を示している、大事な国策だと言っていますその機能強化を、今回の新ルート以外に、何かその強化策は出されているのですか。今回の品川の上を飛ぶルート以外に、何かほかの方策を国は出していますか。出していないと思うのですけれども、いかがですか。","respondent":"中村都市計画課長","answer":"現在、案が出されているのは、現在の案１つだです。","voiceIndex":95,"id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"だから、品川区は、もうこの機能強化に賛成するということは、イコールこの案に賛成するということと同じだということを、もう強く自覚していただきたいし、そのような理解を私は示すべきではないと思います。機能強化だって反対すべきでしょうと私は思いますよ。この、今の国が示しているような機能強化に関しては、断固反対すべきでしょう。なぜ反対しないのですか。伺いたいと思います。","respondent":"中村都市計画課長","answer":"これは具体的なルートや、あるいは騒音、こういったものもありますし、またそれに対して国としてどういった対応が考えられるのか、こういったところが具体的に国として出されませんと、区としても判断をしかねるというところから。","voiceIndex":97,"id":"exchange-036"},{"speaker":"安藤委員","kind":"質問","question":"それはもう認識が甘いですよね。ですから、どのような具体的な情報が来ようが、私はもうこの時点でそれを待っているなどというのは、区民の命と財産を預かる区の判断としては間違っていると思いますけれども、いかがでしょうか。","respondent":"中村都市計画課長","answer":"区として、まだこの新ルート案に対して、了解あるいは承認、こういったことを行った事実はございませんので、今の時点、現時点におきましては、国としてどのような対策が考えられるのか、そういったものを提示をしていただくというところを。","voiceIndex":99,"id":"exchange-037"},{"speaker":"安藤委員","kind":"質問・要望","question":"はっきり言って。品川区が計画の撤回を主張すれば計画はとまるというようなことを歴史の事実が証明しているのだということで、過去の沖合移転、海上ルートに変えさせた国交大臣と、そうした海上ルートへの変更を約束させた確認書などを紹介したり、あるいは浦安市の問題、２００４年にもそういったことがあったということを紹介してきましたけれども、肝心の区はそのように思っているのですかね。","respondent":"中村都市計画課長","answer":"今まで区は、国に対して必要な情報と具体的な対応策について求めてきているところですけれども、このまま国が具体的なものを示さずに進めるということがあれば、それに対して区は、やはり納得できるものではないというふうに考えてあります。","voiceIndex":101,"id":"exchange-038"},{"speaker":"安藤委員","kind":"質問","question":"私が伺ったのは、区が計画の撤回を主張すれば、反対を表明すれば、計画はとまると思わないのですかということを伺ったので、もう一度お聞かせください。","respondent":"中村都市計画課長","answer":"これから区がどのように行動を行っていくかというところについては、これは今までも申し上げておりますとおり、国から必要な情報の提供を受け、そして必要な対応策、これを具体的に示していただく、こういったものが必要だと考えております。","voiceIndex":103,"id":"exchange-039"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっとお答えがないのですよね。不安の払拭、払拭と言いますけれども、払拭されると思うのですかね。その不安が払拭されることがないのを払拭するよう求め続けていくというのは、これは事実上もう計画に反対しない、未来永劫反対しないということにしか聞こえないのですけれども、いかがでしょうか。","respondent":"中村都市計画課長","answer":"そのためには、国がやはり地域の皆様に対して、この飛行ルート案がどのような内容か、またそれに対してどのような影響があり、どのような対応策が考えられるのか、こういったものをしっかりと説明をする義務があると区は考えております。","voiceIndex":105,"id":"exchange-040"},{"speaker":"安藤委員","kind":"質問","question":"大気汚染だって、ではきちんと理解を深めることが必要、どのような計画かと言うのだったら、このルートによって現在でも基準を超えているＰＭ２.５の値がどうなるかということすら明らかにされていないではないですか。ですから、全然私は今の品川区の認識というのは、品川区民の思いともかみ合っていないし、とるべき対応ではないというふうに言いたいと思います。それを伺いたいと思います。","respondent":"中村都市計画課長","answer":"その後に審議官・事務次官が理解に対して感謝ですので、この国策としての機能強化案に対して理解をしたということについて感謝をしていただいているものというふうに認識をしております。","voiceIndex":107,"id":"exchange-041"},{"speaker":"安藤委員","kind":"質問・要望","question":"もしそういうふうに言うのであれば、あくまでこれは機能強化、一般の理解に対する感謝なのだと言うのであれば、改めて、増便一般を理解しただけであって、新ルート案を了承したものではないですよと国に伝えるべきだと思うのですよ。それを求めたいのですけれども、いかがでしょうか。","respondent":"中村都市計画課長","answer":"これは、国がもしこの政策を進めるのであればです。したがいまして、区といたしましては、今、賛成・反対といったところの判断をするという段階ではございませんので、まず地域の皆様に対する不安の払拭、こういったものを国に対して引き続き求めていくです。","voiceIndex":109,"id":"exchange-042"},{"speaker":"安藤委員","kind":"質問","question":"私が伺ったのは、あくまで機能強化一般に対する理解に対する感謝というふうに言い張るのであれば、そういうふうに判断しているのであれば、この委員会でも何度も区自身がおっしゃっているのですね。新ルート案は了承したものではありませんよということを、きちんと改めて国に伝えるべきだと思うのですけれども、いかがでしょうかというふうに伺ったので、お答えいただければと思います。","respondent":"中村都市計画課長","answer":"そういったところで、区も国に対して申し入れを行った際には、国としても、やはり区から直接了解あるいは承諾、こういったものをいただいた認識はないというふうに、国からも説明を受けております。","voiceIndex":111,"id":"exchange-043"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後に伺いたいのは、代表質問で国と品川区の一連のやりとりについて情報公開請求をしました。区は不存在と回答しましたけれども、国交省への要請内容を文書にしたのですか、しなかったのであればその理由は何でしょうか、また、つくったのに保存していないのか、保存しない理由を伺いますというような旨を代表質問で質問いただいましたが、しかしこれについての明確な答弁はなかったかなと。","respondent":"中村都市計画課長","answer":"これは、区といたしましても、公式的な会議などは別だと考えますけれども、全てのやりとり、個々のやりとりに対して文書で記録を残すということは、現実問題としてはなかなか難しいと考えます。","voiceIndex":113,"id":"exchange-044"},{"speaker":"安藤委員","kind":"意見","question":"これは、いろいろなやりとりがあると思うのですけれども、品川区の将来にとって、区民にとって重要なやりとりの中の１つだと思うのですね。そうした中で、今回のやりとりの中であえて文書にしなかったという理由は何かと聞いたので、お答えください。","respondent":"中村都市計画課長","answer":"特に文書にしなかったという事に理由はございません。文書にする必要性がなかったです。","voiceIndex":115,"id":"exchange-045"},{"speaker":"安藤委員","kind":"質問・要望","question":"必要性がない。この件について必要性がないというふうには普通は思わないような重大問題、やりとりだと思うのですけれども、何で必要性がないというふうに思ったのですかね。何か理由があるのですかね。普通は文書を、しっかりとした区長の要望を伝えるわけですから、しっかりと伝えるためには文書を普通つくると思うのですね。その必要性がないと、この件に関してはという、その理由を伺いたいと思います。","respondent":"中村都市計画課長","answer":"一般の会議であるとか公式な会議と違いまして、こういった個々の１つ１つのやりとりについてあえて記録を残して過去に言った言わない、あるいはこの約束が履行されていないからどうだという、そういった、後でこれを読み返すとか、そういった必要も特にないというところです。","voiceIndex":117,"id":"exchange-046"},{"speaker":"安藤委員","kind":"質問・要望","question":"そして合わせて、最後になりますが、課長さんが去年１１月３０日の行革委員会で、事務次官と審議官に会ったのはいつですかと私が聞いたときに、記憶では一昨年だったと思いますということでお答えしていたのですね。実際には、昨年は２０１７年なので、一昨年となると２０１５年ということになるのですけれども、なぜ一昨年と言ったのかなと。伺いたいと思います。","respondent":"中村都市計画課長","answer":"この文書というものが存在しないことは事実です。私が昨年、記憶でおととしと言ったものも、あくまで記憶であり、失念をしておりました。まことに申しわけございませんでした。この一昨年に実際に会った事実というのは、これは私の職責に誓いまして、ございません。","voiceIndex":119,"id":"exchange-047"},{"speaker":"塚本委員","kind":"質問・要望","question":"請願第５号のほうの請願要旨のところについて、若干今までの質疑ともかぶるところはあるかもしれませんけれども、改めてきちんと確認をしたいという意味もこめて質問をさせていただきたいのですけれども、この新ルート案等に対して、国交省との交渉の到達点を区民に公開すること、国交省との交渉状況について区民の意見を聞く場をつくること、こういうふうに述べられておりますけれども。","respondent":"中村都市計画課長","answer":"合意もなしに実施をしないようにですが、これはやはりしっかりと国に対して、区も説明を受け、また区民の、地域の皆様にも説明をしていただいて、そういった中で区としても考えを示していく必要があるかと考えております。","voiceIndex":122,"id":"exchange-048"},{"speaker":"渡部委員","kind":"意見","question":"本日結論を出していただいて結構です。私どもとしましては、この請願に対しまして不採択というところでお願いを申し上げます。もうこの間、行財政改革特別委員会の中でさまざまな意見等も発言をしています。会派として各種勉強会も重ねました。地域からのヒアリングもそれぞれのチャンネルを通じて行っております。そのようなところで、こちらのほう不採択です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":128,"id":"exchange-049"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、採択なのですが、やはり２０２０年の実施計画まで２年を切りまして、品川区議会もしっかりと区民の皆さんの願いを受けとめて、計画撤回の決議も上げるべきだと、私は思います。採択を主張いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":132,"id":"exchange-050"},{"speaker":"大倉委員","kind":"意見","question":"本日結論を出すということで、不採択でお願いしたいと思います。今までも私どももさまざま勉強会をしていく中で、今まで議会としても意見書を出しておりますし、今国から示されている案の中でというところでしっかりとまたこのまま議論を続けていくという前提で不採択でお願いしたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":134,"id":"exchange-051"},{"speaker":"渡部委員","kind":"質問・要望","question":"こちらも、本日結論を出していただいて、不採択でお願いをいたします。私ども議会といたしましても、国交省のほうにはさまざまな形で、去年の意見書の提出などでも細かい不安の払拭を図るための説明会等も求めてまいりますので、直接やはり国交省が説明をしていただくべきと考えますので、不採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":140,"id":"exchange-052"},{"speaker":"安藤委員","kind":"質問・要望","question":"ですから、区がそういう説明の場を、意見を聞く場、説明する場を求めるという内容ですので、私はこれは当然採択すべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":146,"id":"exchange-053"},{"speaker":"大倉委員","kind":"質問・要望","question":"本日結論を出すで、態度については不採択でお願いいたします。品川区もさまざま今、国交省のほうに求めていて、区民の意見を聞くというのは非常に大切なのですが、区が直接この意見を聞く場を設けるということではなくて、しっかりその辺は国のほうで対応していただくことが大事だと考えていますので、それでお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":148,"id":"exchange-054"},{"speaker":"渡部委員","kind":"確認","question":"それで何よりも、私どもこの話というのはもう３年半以上前から議論をしておりまして、降って湧いたと言いましても、もう３年半以上たっている話です。その中で内容も確認させていただきましたが、引っ越して１年がたとうというところでございまして、もうそのころには議会も活発に議論をしていたところかなというふうに考えてあります。不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":152,"id":"exchange-055"},{"speaker":"安藤委員","kind":"意見","question":"本日結論を出すで、採択なのですが、やはり計画の撤回を区は強く主張すべきだと私は思います。それが計画撤回につながります。資産価値の問題も深刻だと思います。ですので、やはり行政も資産価値に影響があるのだということで、固定資産税などの措置をしているのだと思います。やはりこれは影響が大きいと思いますので、この点からもこの計画は撤回をすべき、この陳情は採択すべきだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":156,"id":"exchange-056"},{"speaker":"大倉委員","kind":"意見","question":"本日結論を出すということで、態度としては不採択でお願いいたします。この間、先ほども話があったように、議会ではさまざま議論をしてきて、意見書も提出したところであります。まだ案というところで、この陳情に関しては不採択でお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":158,"id":"exchange-057"}]},{"id":"topic-02","title":"本日は、基礎自治体のあり方に関することのうち、地域共生社会","agenda":"本日は、基礎自治体のあり方に関することのうち、地域共生社会","exchanges":[{"speaker":"あくつ委員","kind":"質問","question":"それともう１点合わせて、もう１回伺いますが、２のところで、「策定に当たっては、国が提唱する地域共生社会の実現に向け」というところで、第三期地域福祉計画の策定とあるのですが、私どもの会派の代表質問でも若干触れておりましたが、品川区としては今後、この福祉というものの考え方については、国が提唱する地域共生社会の実現に向けてというところで、これにのっとって行われるのか。","respondent":"大串福祉計画課長","answer":"そうした中で今般、国のほうから共生社会といったところで示されましたので、また次年度策定する地域福祉計画につきましても、その考え方をベースにしたものをつくっていければと考えていますし、福祉を進めていくといったところでは、これまでもやはり高齢であったり。","voiceIndex":168,"id":"exchange-058"},{"speaker":"あくつ委員","kind":"質問","question":"今までと変わっていないと、それは当然そうだと思うのですけれども、なぜこれを国が打ち出しているのか、なぜ今になって地域共生社会ということを打ち出されているのか、これを品川区としてどのようにお考えになっているのか伺いたいと思います。","respondent":"大串福祉計画課長","answer":"ただ、そうした中で、どうしてもそこの制度のはざまができている、あるいははざまに落ちてしまうような方がいる、そういった方に対しても、まさに丸ごとといったところで支援の手を差し伸べ、あるいは逆に地域にお住まいの方におかれましても我が事と捉えながら。","voiceIndex":170,"id":"exchange-059"},{"speaker":"あくつ委員","kind":"質問","question":"私みたいな第２次ベビーブームの世代が子どもを余り産まなかった。国としてはですね。その上で伺いたいのですけれども、この真ん中の四角のところに、「福祉の各分野における共通事項を定め、個別計画の上位計画として位置づける」と、先ほどもご説明あったのですが、この個別計画、具体的には介護とか高齢者、当然あると思うのですが、個別計画、福祉の分野、どの計画を指しているのかを教えてください。","respondent":"大串福祉計画課長","answer":"児童福祉の分野の計画、こういったところがこの個別計画というところに入ってくるものです。この中での福祉分野における上位というところで地域福祉が位置づけられたといったところですので、それを踏まえた形で新しい計画については策定をしていきたいと考えております。","voiceIndex":172,"id":"exchange-060"},{"speaker":"あくつ委員","kind":"質問","question":"さまざまなところでの福祉分野を丸ごと抱えていこうというところの計画ということで、非常にこれから大事な計画になってくるのかなと思うのですが、その中で伺いたいのは、この裏側のページを見ると、障害者の部分、理解促進のための取り組みというのはわかるのですけれども、確かに理解促進のためにこの３事業はやっていると思うのですが、例えば今。","respondent":"大串福祉計画課長","answer":"委員からご紹介いただきましたように、新しい総合支援施設です。そちらを請け負う、運営する法人としては４法人が今のところ予定されております。","voiceIndex":174,"id":"exchange-061"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そういうノウハウは非常にお持ちだと思いますので、今後の展開の中で、まさに縦割りではなくて横串というところが今回の肝だと思いますので、ちょうど明日ですか、そこの説明会も行うというお話なのですが、そこについてもぜひ今後ともその活用方法を考えていただきたいということが１つ。２０２１年度からは特別養護老人ホーム、定員２００人規模、これは杉並区でもかなり大きいほうだと。","respondent":"大串福祉計画課長","answer":"委員がご紹介していただいた杉並の施設の事例です。確かにそういった形で共生型ワンストップでできるのは非常に望ましいと考えていますし、具体例を挙げられました林試の森のところについても、今、鋭意その辺を企画調整課とも連携しながら検討を進めております。","voiceIndex":176,"id":"exchange-062"},{"speaker":"あくつ委員","kind":"質問・要望","question":"障害者の世界、障害者の特に事業者さんの世界では、どんどん地域に戻っていこうという流れ、国としてもそういう流れですけれども、そういうところもぜひ品川区として、そういう意識というか姿勢を、区民に理解を求めるような姿勢をどんどんアピールしていっていただきたいというところが１つなのですが、その点を最後にお伺いしたいと思います。","respondent":"大串福祉計画課長","answer":"ただ、障害者福祉の関係では、やはり地域との連携といったところ、またそういった障害をお持ちの方でも自分らしく住み続けられる地域、これがまさに共生社会の大きなポイントになってこようかと思いますので。","voiceIndex":178,"id":"exchange-063"},{"speaker":"あくつ委員","kind":"質問・要望","question":"この議論の中で、議会で聞いていると、これは公共の役割を放棄しているという、そういう私からすれば間違った指摘をされるような方もいるようですけれども、それはそういうことではなくて、公共は公共としての役割の中で、そして地域としては地域の役割の中で、より幸せになっていこうという制度だと私は認識をしておりますので、ぜひこの取り組みを進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":180,"id":"exchange-064"},{"speaker":"渡辺委員","kind":"質問","question":"資料の裏面といいますか、多世代交流施設、ゆうゆうプラザというのを軸に伺いたいと思います。それぞれ共生社会という中で、どれもが大事だと思います。今のご質問も含めて。そこで何を伺いたいかと言うと、設置当初の想定があったと思うのですね。設置をするまでの想定、いざ稼働してからも想定以上の効果がおそらくあったのではないかと思うのですが、その点、具体事例を教えていただければと思います。","respondent":"大串福祉計画課長","answer":"こうした中で、さまざまな交流活動等々をこれからも進めていければ、大きな効果、成果が出てくるかと考えていますし、このゆうゆうプラザということで名称をつけましたけれども、まさにこういった形での多世代交流がより地域の中でも促進できればと思っているところです。","voiceIndex":182,"id":"exchange-065"},{"speaker":"渡辺委員","kind":"質問","question":"次に伺いたいのは、資料の説明にもあるように、普通、私たちがやはり地域で一番わかりやすい、そして一番なじみのあるのが町会であり高齢者クラブ、ここが軸だと思っていたのですが、視察時もそうですし、他の行事で伺ったときも、この資料にあるように地域のサークル、子育てのサークルであったり高齢者のサークルが結構利用頻度が高いということがわかりました。","respondent":"大串福祉計画課長","answer":"この大崎ゆうゆうプラザ、あるいは平塚橋、社会福祉協議会であったり、あるいは三徳会であったり、社会福祉法人であったりといったところが指定管理ということで、あるいは委託ということでやっておりますけれども。","voiceIndex":184,"id":"exchange-066"},{"speaker":"渡辺委員","kind":"質問","question":"今後の展開というところで、最後に伺いたいと思います。今言ったようにこの２拠点は、大崎と平塚橋ですが、区全体の中でどのような行政ニーズ、地域ニーズに応えていけるか。やはり、これからの優先順位などもかなり高められるのではないかと思うのですが、その点、設置へのこれからの展開への意欲等を伺いたいと思います。","respondent":"大串福祉計画課長","answer":"ここも活用しながらゆうゆうプラザという形で整備をしていこうと今考えております。委員ご指摘のように、身近なところでといったところで地域のバランスを考えながら、総合的に今後も配置等々を機会を捉えながら進めていきたいと考えております。","voiceIndex":186,"id":"exchange-067"},{"speaker":"渡部委員","kind":"質問","question":"それを幾つも幾つもつくれと言うと、これはなかなか財政的な負担もかかるしできないと思うのだけれども、例えば本当に各エリアごとにと言ったらおかしいですけれども、あのような高齢者の方々がちょっと集える、それで少しレクリエーションができるような施設であったり、逆に言えばあれだけ広くオープンな状態であって、子どもたちも帰りに寄ってねというような施設は。","respondent":"大串福祉計画課長","answer":"こういった多世代交流施設、ゆうゆうプラザに限らず、拠点というのは非常に大きなポイントかなと、共生社会を進めていく上で、あるいは地域包括ケアを進めていく上で非常に大きなポイントだと認識をしております。","voiceIndex":189,"id":"exchange-068"},{"speaker":"渡部委員","kind":"質問・要望","question":"ですからそういうふうに、すぐちょっと歩いて行けるようなところ、お散歩で行けるようなところに活動拠点を設けるというのは、品川区、こういう密集したような都市部においてはすごくいいアイデアであって、在宅で地域の中で頑張っていかれることにとっては非常に重要なのかなと、これはいいヒントだなというふうに、私たち会派としても思っておりますので、今ご答弁でもいただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":191,"id":"exchange-069"},{"speaker":"若林委員","kind":"質問・要望","question":"昨日の厚生委員会でも報告がございましたので、引き続きというか。残るは中３回の２、３、４ということで、なおかつテーマごとということになりますと、先ほどの介護、それから障害をお持ちの方、それから子どもという、それぞれこれで３つになるのだろうなと思うのですけれども、そこの確認をまずさせていただきたいと思います。","respondent":"大串福祉計画課長","answer":"それをまとめる形をとるのか、あるいは１回ごとに、そういうテーマごとに設定をするのかというのは、ちょっとまた委員長ともご相談をさせていただきながら、また委員は４０名程度を想定しておりまして、かなり大所帯の会議体になってくると思いますので。","voiceIndex":193,"id":"exchange-070"},{"speaker":"若林委員","kind":"質問","question":"そうしますと、まだ当然、委員長が決まらないとということで、それはそういうことだと思うのですが、今の計画がありますね。その辺の現計画についての総括の考え方を１つお聞きするのと、一緒に、そうすると今回は先ほどの話になりますけれども、各個別の計画は今までどおり、今まで以上にしっかりやると、今回この共生という理念が入ってくると、委員会の進め方もそうはいかないのだろうなと。","respondent":"大串福祉計画課長","answer":"そうした中で、品川区の地域福祉というもの、これについて今現在はこれまでの取り組みを踏まえた上でという形のお答えになってしまうかもしれませんけれども、そうした中で次の時代、次代の地域、これをどのようにしていくのかといったところを改めて定義づけ。","voiceIndex":195,"id":"exchange-071"},{"speaker":"若林委員","kind":"意見","question":"了解しました。これを見ながら１つだけ、第三期地域福祉計画の中心となるのはやはり支え愛・ほっとステーション、大きな柱としてはこれをさらに発展してまさに地域でというところだと、そのキーパーソンというのはやはりコーディネーターになるのだろうと思うのですよね。これで最後になります。","respondent":"大串福祉計画課長","answer":"ただ、それにつきましてもやはり各地区との実際の調整等々入ってまいりますし、あるいは各コーディネーターとの調整といったものも入ってまいりますので、今のところそういったことを考えておりますけれども。","voiceIndex":199,"id":"exchange-072"},{"speaker":"若林委員","kind":"意見","question":"そうすると、まさに計画策定に携わるという意味では、やはりこういうお立場、地域の中心でのコーディネーターになっていく方が策定委員になったほうがいいのかなという感想を持ったので、ご検討いただければということで終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":201,"id":"exchange-073"},{"speaker":"石田（ち）委員","kind":"質問","question":"本当に国が決めてわっとおりてきたものを区が進めていくというか、やっていかなければいけないというところでは、本当に大変だなと思ったのですけれども、そうした１つの事業所がなかなかこういったことを進めていくというのは難しいという中で、こういった相談、課長さんでわかるのか、厚生委員会で聞かないとわからないことかもしれないのですけれども、こういった事業所が相談してきていたり。","respondent":"大串福祉計画課長","answer":"申しわけございません。そういった個別の相談となると、各所管ごとになってしまいますので、私のほうでは把握はしておりません。","voiceIndex":203,"id":"exchange-074"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"済みません。個人情報を把握して共有することを求めるというところまでなるものなのか、伺いたいと思います。","respondent":"大串福祉計画課長","answer":"その中で当然我々も一緒に入って議論をする中で、行政としてできること、あるいはなかなか行政としてはできにくいもの、そうした中で、ではそれ以外の主体のほうであれば可能なものとか、そういったさまざまな側面、多面的な形での議論をさせていただきながら。","voiceIndex":205,"id":"exchange-075"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それで、やはり行政も力を入れて進めていると思うので、これらを本当にきめ細かく進めていくことで、自然と自主的・自発的な支え合いや助け合いの取り組みになっていくと思いますので、社会保障の姿を変えていくほど、法律を変えてまで進めていく国のやり方というのは、違うなと思っていまして、それを一足飛びに品川区では進められる状況ではないと思いますので。","respondent":"大串福祉計画課長","answer":"共生社会、これをどのような形で品川区が具現化していくのかにつきましては、次年度委員会の中でさまざま皆さんからご意見を賜りながら、あるいは地域の皆様と意見交換をしながら進めていければと考えているところです。","voiceIndex":207,"id":"exchange-076"},{"speaker":"石田（ち）委員","kind":"意見","question":"地域福祉計画でこの共生社会というのが具体的に計画、進んでいく方向性としてつくられていくということで、私たちも注視していきたいと思っていますけれども、やはり行政の公的な支援なしには、この地域の支え合い、助け合いというのはつくられないと私は思いますので、やはり大もとからの問題解決、人口減少がなぜ起きているのか、それをこちらの地域のほうに投げられてもという思いが私はしますので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":209,"id":"exchange-077"},{"speaker":"あくつ委員","kind":"質問","question":"先ほど、石田ちひろ委員の発言の中で、人口減少云々ということをおっしゃいましたけれども、これは国会でももちろん議論があったとおりで、それはもう当然、待機児童対策であるとか、子育て支援のもと、これはもちろん対策を打った上で、こういう例え話を聞いたことがあるかもしれませんけれども、毒矢が刺さった人に、あなたに刺さっているその毒の矢の毒は何の成分ですかと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":211,"id":"exchange-078"},{"speaker":"松永委員","kind":"質問","question":"私からは、この支え愛・ほっとステーションについて伺いたいと思います。今後、高齢化とか利用者というのは年々増えてくるとは思うのですけれども、今のコーディネーターの配置数で間に合っているのか、今後どうしていく方向性なのかというのを伺いたいと思います。そこで、例えば少しずつありますが、文化センター等にも設置してみてはということについても伺いたいと思います。","respondent":"大串福祉計画課長","answer":"ただ、そうした中で各地区さまざまな状況が出てまいりますので、もしそういったところでのお声、あるいは内容等々出てきた場合には、またその辺で適宜判断をしてまいろうと考えております。","voiceIndex":213,"id":"exchange-079"},{"speaker":"松永委員","kind":"質問","question":"居酒屋とかそうしたお店の中などにチラシを置かせてもらえるところについてはそうしたことをやってみてはどうかと思ったのですけれども、区として周知方法について、今のままでいいのか、それともまたほかに案があるのかというのを伺いたいと思います。","respondent":"大串福祉計画課長","answer":"これまでの周知といたしましては、各町会の掲示板等々へチラシをはったりとか、そういったことも行っております。今後もそういった取り組みを重ねながら、浸透、周知を図ってまいりたいと考えております。","voiceIndex":215,"id":"exchange-080"},{"speaker":"松永委員","kind":"意見","question":"先ほどの商店街等の件もぜひお願いしたいと思います。これは国も一緒に進めていく取り組みであって、一時的なものではないと思いますので、今後もそうした周知の方法についてもまた考えていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":217,"id":"exchange-081"},{"speaker":"安藤委員","kind":"質問","question":"これは今どうなっているのか。２番目として、高齢者と障害者が同一の事業所でサービスを受けられる共生型サービスというもの、品川区としてこれにどう取り組んでいっているのか、現状ですね。３つ目は介護医療院ですね。療養病床のかわりに何かしようという話のようですけれども、介護医療院の新設という点では関連条例も出ているようなこともありますけれども、現在どうなっているのか、それぞれ伺います。","respondent":"大串福祉計画課長","answer":"窓口の設置です。こちらにつきましては、今のところまだ具体的にというところではございません。それから、サービスの関係につきましては、今回の定例会でもご提案をさせていただきました。","voiceIndex":219,"id":"exchange-082"},{"speaker":"安藤委員","kind":"質問・要望","question":"これは別に共産党だけが言っているわけではなくて、各メディアですとか専門家の方も指摘をしていることなのですが、この点については品川区としては、私はそういったことになると思うのですけれども、あくまで行政がしっかり責任を果たした上で、さらに上乗せでこういうこともやりますよということだったらわかるのですけれども、我が事・丸ごとということを強調されてしまうと。","respondent":"大串福祉計画課長","answer":"あくまでもそういったものにつきましては、これまでと同様変わりなく責任を持った形で行いながら、なおかつ大きな連携を進めていく、そうしなければ今後社会としてなかなか難しい局面に入ってくるのではないかといったことで、この共生社会という概念が出てきたと捉えております。","voiceIndex":225,"id":"exchange-083"},{"speaker":"安藤委員","kind":"質問","question":"２つ目として、やはりどうしても先ほど来、出ていますような人口減による担い手の件ですとか、あるいは財政面の社会保障費の増大というところから出ているという２つ目の側面というのはかなり大きなところがあると思っていまして、そういった点では先ほどのような行政の役割は必ず果たしていきますという、その意気込みは非常にすばらしいことだと思うのですけれども、やはり財政上と言いますか。","respondent":"大串福祉計画課長","answer":"そういった形で他人事ではなく、まさに我が事と捉えながら、今住んでいるこの品川区、これをよくしていこうと考えていこうというのがこの趣旨です。そういった趣旨を踏まえながら、我々としても共生社会の実現に向けた形でそれぞれの取り組みを進めていきたいと考えております。","voiceIndex":227,"id":"exchange-084"},{"speaker":"安藤委員","kind":"質問","question":"品川区としては、この我が事・丸ごとというのを積極的に進めていきたいという立場なのでしょうかというのを１つお伺いします。私はこういった状況、そもそもそういった矛盾もあるということを考えると、うまくいかないのではないでしょうかと思うのですよ。私はうまくいかないと思ってしまうのですけれども、その辺についてはどのようにお考えになるでしょうか。","respondent":"柏原企画調整課長","answer":"そういったところに対して、区が後押し、支援をするということが、後半のほうでご質問出ていましたけれども、いわゆるおっしゃっていた地域力、地域の力にも大きくつながると、ひいてはそれが品川区全体の力、活性化、こういったものにつながっていくのだという考えのもとに。","voiceIndex":229,"id":"exchange-085"}]},{"id":"topic-03","title":"はじめに、(1)議会閉会中継続審査調査事項","agenda":"はじめに、(1)議会閉会中継続審査調査事項","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"まとめていただきました。２つの項目についてまとめということなのですけれども、確かに区有施設・公有地等活用と、羽田空港の機能強化に関すること、前者に関してはもう毎年のようにやっていること、羽田空港の機能強化に関しても、これも長年やってきていることなのですが、これをまとめて、あれですか。何か議会、議長に対して提出をして、それを区のほうに求めていくという、こういう手順なのでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":236,"id":"exchange-086"},{"speaker":"あくつ委員","kind":"質問","question":"特に羽田のところなのですけれども、今初めて私、これは資料としていただいていたのですかね。済みません。これは委員会の総意ということで出されるということなのでしょうか。","respondent":"鈴木（ひ）委員長","answer":"皆様の中から、まだこういう意見も出したなどということであれば、またその後でご案内をしたいと思っているのですけれども、そういう意見も、あとはこれ以外のところでもありましたらまた出していただいて、それをもとにしながら正副でまとめて、そして皆様のところに。","voiceIndex":238,"id":"exchange-087"},{"speaker":"あくつ委員","kind":"意見","question":"よくわかりました。特に羽田に関しては、ここに書いてある、いまざっと読ませていただくと、多分共通認識の部分もあると思いますし、もちろんそうでない部分もこれから出てくるのかなと思いますので、よくわかりました。そういう点では、それで結構です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":240,"id":"exchange-088"},{"speaker":"若林委員","kind":"提案","question":"最初の特定事件、(1)の基礎自治体のあり方に関することは、今回はまとめないと聞いたのですが、この提出された資料、共生社会は本日議論で、さすがにこれはというのはありますけれども、この(2)の人口動向については一定の議論がされて、この点について総意としてさまざまな要望も含めて、提案も含めて、区のほうも一定の理解も示されたり答弁もあったりということで。","respondent":"鈴木（ひ）委員長","answer":"お手持ちの参考資料をもとに案文を作成したいと思いますが、また今ご意見をいただいたそのことについても検討しながら作成したいと思いますけれども、万一追加したい項目がありましたら、各会派で取りまとめた上に。","voiceIndex":242,"id":"exchange-089"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6044#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":59013,"voices":244}},{"id":"h30-20180301-18","meetingId":"h30-cm03","date":"2018年3月1日","dateIso":"2018-03-01","committee":"オリンピック・パラリンピック推進特別委員会","time":"午前１０時００分～午後 ４時４５分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今、請願読み上げられましたけれども、全くそのとおりだなと考えています。今、競技場などいろいろ建設が行われておりますけれども、この建設工事従事者の方々が今汗水垂らしてつくっているという状況ですが、請願提出者からいただいた資料を見たのですが、鉄道工事の例が載っていました。あわせて区のほうも、組織委員会のほうにぜひ働きかけていただきたいと思いますけれども、いかがでしょうか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"開会式・閉会式につきましては、今ご説明しましたように組織委員会のほうで全員が参画をするということを目標に現在検討を進めているです。そうした組織委員会の動きをとりあえず区としては見守っていきたいと考えています。","voiceIndex":6,"id":"exchange-001"},{"speaker":"吉田委員","kind":"確認","question":"２点、あります。１点は、本当に言葉の細かい確認で、改めて東京２０２０大会の正式名称がどうだったのかなという正式名称の問題ですけれども、東京オリンピック・パラリンピック競技大会組織委員会のほうは、東京オリンピック・パラリンピックというふうになっているということで、この第３２回オリンピック競技大会が正式名称ということなのでしょうか。この請願の趣旨の中にどの辺まで含まれているのか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"ただ、略称につきまして、例えば東京２０２０オリンピック、東京２０２０パラリンピックということで、オリンピックとパラリンピックを分けた言い方をすることも可能だというような説明を受けているところです。","voiceIndex":9,"id":"exchange-002"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"我々の会派にも請願者の方にお越しをいただいて、お話をうかがいました。その点について把握をされているのか。それで、我々も例えばいろいろ今要望を東京都にもしていますけれども、では東京都にすることと、組織委員会にすることをどうやって分けて、その話をしていったらいいのか。我々の要望をどうやったら実らせていったらいいのかということを、どうお考えなのかを教えていただきたい。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"開会式、閉会式につきましては、初めにご説明させていただきましたとおり、組織委員会のほうが役割分担として全てを担うというふうに東京都から確認しています。","voiceIndex":12,"id":"exchange-003"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そうではなくて一体となって行うのか。役割については組織委員会なのか東京都なのか。今ご説明いただいた開会式・閉会式は、それは組織委員会ですよというのは、今わかったけれども、ほかのそういうイベント的なものも含めて、我々も要望しているものもあるのですが、それをどういうふうに我々としてこれから具体的に実現させていくにはどうしたらいいのか、あわせてお話を伺えればありがたいなと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"ただ、直接的な要望ということになりますと、やはり組織委員会にダイレクトに要望する方法は、大きな意義があるかとは思います。今、この場で私のほうで、東京都がいいのか組織委員会がいいのかというような、なかなか即答はできないところではあります。","voiceIndex":14,"id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"我々の会派としても、議論をした中で署名をさせていただきました。これは委員長にお願いでありますけれども、毎年委員会として東京都に要望しており、この前も要望しに行ったりとかいろいろなことをしていますよね。やはりもう一度この委員会で期間を定めていただいて、要望を取りまとめて出していくという必要があるのだろうなと思っています。それから、要望はこの請願の項目１つだけではない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-005"},{"speaker":"いながわ委員","kind":"質問・要望","question":"１点お伺いしたいのですが、ここオリンピック競技大会（２０２０／東京）ということで、多分パラリンピックも入っているニュアンスなのかなと思う中で、先ほど頭に冠がついたものは全て組織委員会がやるという理事者のご答弁だったのですが、これが例えば、要は開会式とか閉会式等のセレモニーの「等」の中には、おそらく品川区内で行われるビーチバレーであったり、ホッケーであったりというのも含めた中で。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そうした意味で、こうした団体のほうで、区の例えばしながわサポーターという制度もありますので、そういった形で一緒にイベントに応援していただくというような、参画していただくような形は十分あり得ることかと考えております。","voiceIndex":17,"id":"exchange-006"},{"speaker":"いながわ委員","kind":"提案","question":"それもオリンピックにかかわっているわけであります。一言あればお願いします。この請願については、趣旨は重々理解しているので、これも結論めいたことを先ほど石田秀男委員がおっしゃっていましたけれども、しっかりこの委員会として、これも含むさまざまな観点で要望書を提出するということを、私ども会派からもご提案をさせていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":19,"id":"exchange-007"},{"speaker":"本多委員","kind":"質問・要望","question":"会派の考え方や方向性につきましては石田秀男委員が述べましたので、１点だけ確認というか教えていただきたいことがあります。こういう開会式や閉会式についても組織委員会のほうで柔軟にできることなのか、それともすごく厳しいルールがあるのか。その感覚だけ教えていただければと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"お話のありました聖火ランナーにつきましても、まさにこれから検討していくというようなことは聞いております。日本の中でどういったコースを走るのかということ。それからどういった方たちに走っていただくのかというようなこと。","voiceIndex":21,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"品川区に１点伺いたいのですけれども、この請願にも書かれているとおり、建設労働者の開会式などの参加について、今後の東京都、まだスケジュールなども決まっていないということで、見守っていきたいという話ですけれども、決まっていなければなおのこと、品川区でも今ホッケーの会場を建設するわけですが、品川区としてもしっかり建設労働者が開会式に参加ができて。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"労働組合の方だけに限定することなく、区としてはそういった思いで見ていきたいと考えています。","voiceIndex":25,"id":"exchange-009"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"結論を出すでお願いをしたいと考えています。それで先ほども言いましたように、この請願については趣旨採択で、意見書は提出をしないという扱いでお願いをできればと考えています。先ほど言いましたように、全体の中で、この委員会の中で要望書を出していく中でこの願意も入れていくということで我々は考えたいと考えていますので、結論を出す、趣旨採択、これに対する意見書は出さない。これでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-010"},{"speaker":"つる委員","kind":"質問・要望","question":"態度は結論を出すで、うちも趣旨採択ということで、今、石田秀男委員がご発言されていましたけれども、先ほど理事者のほうからの説明があって、組織委員会の考え方ということで参画の部分については、皆がかかわっていると感じられるようにするとありまして、この請願自体は労働従事者ということで、その方だけに限った形での請願という形になっていますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"今日結論を出すということと、意見書を出したいと思います。先ほど、委員会として要望を出そうじゃないかというご意見そのものには理解をするわけですけれども、また、先ほど来からの議論を聞いていましても、全体の方向として、ここに書かれていることの中身については理解があるということですが、請願者の思いにしっかり答えていきたいということで、意見書を出したいという結論になりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-012"},{"speaker":"いながわ委員","kind":"質問・要望","question":"そして全ての方に光の当たるようにするような形で、組織委員会または必要であれば東京都に対して要望書をこの委員会からしっかりと何項目か挙げて、提出する必要性もあるのかなと思いますので、趣旨採択ということで、お願いをしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-013"},{"speaker":"吉田委員","kind":"質問","question":"生活者ネットワークとしても、先ほど質問した結果、多分この請願代表者の方も、パラリンピックの大会の開会式じゃ嫌だとおっしゃっているわけでもないでしょうし、それから建設工事従事者の方たちにスポットを当てたいという気持ちもそのとおりだと思いますので、その趣旨には賛成をいたしますけれども、１点、文言上ではありますが、やはりパラリンピックも含めて全体として捉えたいなというのと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"先ほど、採択を主張させていただきましたけれども、皆さんのご意見をうかがう中で、趣旨は理解できるし、委員会としても要望をしていきたい方向が確認されましたので、趣旨採択に変更したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-015"}]},{"id":"topic-02","title":"願第４号 第３２回オリンピック競技大会（２０２０／東京）における競技施設等工事において","agenda":"願第４号 第３２回オリンピック競技大会（２０２０／東京）における競技施設等工事において","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"あわせて、１点区のほうにお伺いしたいのですが、区としても、この競技会場の所在地というところで、区としても組織委員会のほうに、組織委員会もやるとは言っておりますけれども、改めて品川区のほうからもしっかり調達コードを守るよう求めていただきたいと思いますが、いかがでしょうか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"改善要求の働きかけに協力させるというようなことを、最終的には十分に取り組んでいないと認められるような場合には契約を解除するというところまで踏み込んで書かれてあります。そうしたところで組織委員会のほうが対応していただけるというふうに考えているところです。","voiceIndex":51,"id":"exchange-016"},{"speaker":"いながわ委員","kind":"質問・要望","question":"先日も搬入ですか。もう既に２月末、３月頭にはホッケー場、品川区内で行われる競技の競技場の建設が今始まっていると思いますが、やはり品川区としても、そういった調達コードの遵守がされているかどうかというのを再確認する意味、啓発も含めて、しっかりとかかわれるかどうかは別にしても、やはり他人事ではないというか、そういう思いでしっかりとやっていただきたいのですが、いかがでしょうか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"区内で工事をされるということですので、区としてもしっかり見守りたいとは思いますが、そういったことを監督するような立場に区はございませんので、そういった意味できちんと情報収集しながら、組織委員会とはいろいろな関係でかかわっておりますので。","voiceIndex":54,"id":"exchange-017"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ぜひそこはやっていただきたいと思います。２年前にリオの視察に行ったときも、もう如実にそこはあらわれていたのですが、やはり競技場の周りはまだ工事最中、オリンピックがもう始まっているにもかかわらず、まだ工事をしていたという現状であります。日本の粋を集めれば、あと２年後の開催までには全てが間に合うと思うのですが、もうお尻は決まっている工事であります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":56,"id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"意見","question":"我が会派は、この請願者の方ともお会いをさせていただいて、いろいろな話を、議論もさせていただきました。署名はなぜしなかったのかというところがあると思います。もう１つ言えば保険の問題とか、今、建設業界の中で、若い人たちにいかに担っていただくかという。ある国では、今変な話年間４万人ぐらいを育てて送り込もうという話があったり、じゃあ日本人の労働者がどういう形で今いるのか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":58,"id":"exchange-019"},{"speaker":"つる委員","kind":"質問・要望","question":"公明党も会派で請願を見て議論させていただきました。今、石田秀男委員からもありましたけれども、ここに、鍵括弧の中には長時間労働の禁止等とあるのですが、趣旨の中には、その長時間労働に関することを主におかれて記載があるような部分もあることも含め、それだけではない部分もありますし、全体を立てて見ていかないといけないのかなというところで、継続にさせていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-020"},{"speaker":"中塚委員","kind":"意見","question":"共産党としては結論を出すということと、採択をして、意見書を出すべきだと思います。長時間労働のこと、公契約のこと、若い人の担い手など、推移を見ながら全体をさらに深めていきたいということは理解を示しますけれども、請願の内容にしっかりと答えていきたいので、結論を出すと。採択して、意見書を出すということでお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":62,"id":"exchange-021"},{"speaker":"いながわ委員","kind":"質問・要望","question":"本日結論を出すということで、紹介議員にもなっているということで、採択を主張させていただきたいと思います。さらに言うのであれば、やはり今後のさまざまな契約案件の中で工期の設定もしっかりと行っていかなければ最終的には長時間労働につながっていくのではないかなと考えていますので、今回の請願については、我が会派としては、採択を主張させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-022"}]},{"id":"topic-03","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"文化芸術振興協議会の準備会のご報告をいただきましたが、今回この３１団体が挙げられておりますが、これは今後増えていくということもお話をいただきましたので、また拡大をしていただきたいと思うのですが、これは団体のみが登録をされるのか、例えば品川区内にお住まいの個人の方、どういう方がいらっしゃるかわかりませんけれども、芸術にかかわっている方とか、また、芸能人の方とか。","respondent":"鈴木文化観光課長","answer":"協議会に参加する団体または個人の芸術関係の方ですが、基本的に今現時点では、団体に限定する予定はございません。ただ、今準備会の段階では、一定程度各分野の方から広く意見をお伺いしたいと。","voiceIndex":79,"id":"exchange-023"},{"speaker":"いながわ委員","kind":"質問・要望","question":"「しながわ文化プログラム」に参加しようというところから、お伺いしたいのですが、この文化プログラム自体が、多分オリンピック・パラリンピックがあるから、この文化プログラムという概念というか、こういうのが出てきて、品川区としてやるというのは重々理解しているのですが、このパンフレットの内容が、「しながわ文化プログラム」のロゴマークがお使いいただけますとか。","respondent":"小川オリンピック・パラリンピック準備課長、鈴木文化観光課長","answer":"さまざまいろいろな今後もご意見を伺いながら、デザインにつきましては、意見を伺いながら検討してまいりたいと思います。ただ、この皆さんの中で共通しているのが、自分たちの活動事業はしっかりとしているけれども、ほかの団体と連携することで新しいことや何かもっと大きなことができるのではないかということが皆さん共通の認識でございました。","voiceIndex":83,"id":"exchange-024"},{"speaker":"いながわ委員","kind":"質問・要望","question":"「しながわ文化プログラムに参加しよう！文化芸術振興協議会に関しては、これからまた人数も増えるかと思います。団体がうちはこうなのだという方もいらっしゃるかもしれませんが、そこはぜひファシリテーターというのですか。仕切る方がしっかりとそういうことがないように、本当に連携だけはとっていただいて、東京２０２０大会後も品川の文化芸術の振興に努めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":86,"id":"exchange-025"},{"speaker":"たけうち委員","kind":"質問","question":"１点だけ文化芸術振興協議会準備会に関連してなのですけれども、こういう形でいろいろ進んでくると、いろいろな形でお金がかかってくると思うのです。そうすると、予算書をよく見ていないのでわからないですが、基金が２年ぐらい前にできたと思うのですが、これを、例えば今後の予定の中のキックオフイベントだとか、いろいろなところでそういったものを活用していくのか。もしわかれば教えてください。","respondent":"柏原企画調整課長","answer":"そういった趣旨を鑑みながら、基金というのも、当然ここにかかわるような形で使いようというのが出てくると思いますので、実際どういう形でそれを充てていくかというのは、いろいろ事業の中身を検討しながらというのもありますけれども。","voiceIndex":88,"id":"exchange-026"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"幾つか教えていただきたいのですが、まず準備会のことです。なぜそのようなことを言うかというと、今、児童遊園になっているのを屋外広告物条例で今度、都市公園にしようとか、いろいろな考え方がある。それからハードの部分があるではないですか。それを文化芸術では、ハードのが必ず出てくるではないですか。そういう方々といかに連携をしたりもしているのかというのをまず教えていただきたい。","respondent":"鈴木文化観光課長","answer":"１点目の準備会での参加いただいた団体の皆さんからのご意見の中で特徴的なものですが、１つは、そもそも区のほうで協議会を構想、検討しているときに、区民芸術祭でかかわっていただいている団体から、同様の趣旨で、広く多くの団体に声をかけて。","voiceIndex":91,"id":"exchange-027"},{"speaker":"石田（秀）委員","kind":"質問","question":"例えば、この前ちょっと質問でも出たけれども、４月の７日、８日にエクストリーム大会が広島市民球場跡地で開かれる。これは多分２桁万人の動員規模のレベルでやろうとしているわけです。これは区民芸術祭で、そういうのも含めてやっていくのはいいのだけれども、そういう多くの人を集客できるようなイベントというものも考えていくべきではないのかなと思うのだけれども、ここら辺の考えはどうお考えですか。","respondent":"鈴木文化観光課長","answer":"文化観光課で観光の事業もやっておりますので、文化芸術のイベント、大規模なものを実施しながら、それを観光の資源として活用する。シティプロモーションによる魅力発信というところも想定をして、考えているところです。","voiceIndex":93,"id":"exchange-028"},{"speaker":"つる委員","kind":"質問","question":"この文化プログラム。品川のというところで、参考までなのですが、オリンピックが決定して以降だけではなく以前も含めてで結構なのですが、まずファッションショーありますよね。シルバーの方のファッションショーとかそういうものがあるのですけれども、いわゆるファッションショーが行われたことがあるかどうか、わかる範疇で教えてください。","respondent":"鈴木文化観光課長","answer":"あちらの学生の方がやはりいろいろデザインした服をファッションショーでやられたり、最近は文化のほうでお世話になっている喜多能楽堂が杉野学園とコラボをして、学生が能楽堂の衣装を研究した上で新しいデザインをして。","voiceIndex":96,"id":"exchange-029"},{"speaker":"つる委員","kind":"質問","question":"予算特別委員会とかでもまた改めて伺おうかなと思っているのですが、当然区からというよりも、これはどちらかというと文化プログラムで、それぞれの地域のいろいろな方、団体とかが、各地域で行われているよというのが趣旨だと思うのですけれども、そういった例えば文化と一口に言ってもいろいろな文化があるなというところで、せっかくやるならば、この文化プログラムの条件としては。","respondent":"鈴木文化観光課長","answer":"ご質問いただきました商店街や地域の商業関係の事業所との連携、協力体制ですが、実は来年度以降、やはり総合的な文化芸術、それからスポーツ、そういうもののイベントを実施したいと思っておりまして、そのときに、やはり近隣の商店街や町会、地域の団体にもお声かけをして。","voiceIndex":98,"id":"exchange-030"}]},{"id":"topic-04","title":"ＩＢＳＡブラインドサッカーワールドグランプリ２０１８","agenda":"ＩＢＳＡブラインドサッカーワールドグランプリ２０１８","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"これは基本的にはこちらの主催者の問題だろうと、ＩＢＳＡの問題だろうと思っていたのですが、品川区が特別共催ということなので、わかる範囲で教えていただきたいのですが、ブラインドサッカーということなので、視覚障害者への情報提供のことです。全体的な考え方と、このことに関しての２つをお願いします。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"この本大会におきましても、当然そういったことをしていくことと聞いてあります。","voiceIndex":105,"id":"exchange-031"},{"speaker":"吉田委員","kind":"提案","question":"そういう配慮がされていたということでよかったと思います。その後、私たち、生活者ネットワークとしても、きちんとした提案をしていないのが悪いのですけれども、その辺のことも今後オリンピック・パラリンピック準備課のほうから、いろいろなところに働きかけていただけると、有効な情報提供につながるかなと思いますので、その辺ぜひご検討いただければと思います。これは意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":107,"id":"exchange-032"},{"speaker":"いながわ委員","kind":"質問","question":"場所の提供をしているから、非常に日本全国を見ても、品川区は非常にブラインドサッカーに対して造詣が深い部分だと思うので、会場などにＳＰコードやら様々な取り組みをされているというのは重々理解はできるのですが、ではこれがオリンピック・パラリンピックのときに、青海の会場になると思うのですけれども。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"組織委員会の取り組みですが、東京都ですとかいろいろなところが出している、これからご紹介しますものについても、ＳＰコードがついているものとついていないものがあるのですけれども、組織委員会がどういうふうにするかはわかりませんが、パラリンピックについては。","voiceIndex":109,"id":"exchange-033"}]},{"id":"topic-05","title":"その他を先に議題に供します。 まず(1)の議会閉会中継続審査調査事項","agenda":"その他を先に議題に供します。 まず(1)の議会閉会中継続審査調査事項","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"１点だけ教えてください。ボランティアの件なのですけれども、どういう広報をしてどれぐらい知らせていくのか。こういうことは、ただ情報が来たのはいいのだけれども、その辺のところというのもわかりやすくやりたい方に手が届くように、ただこの１枚が東京都から来てもよくわからないし、どういうふうになっていくと我々は思っておけばいいのですか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"都市ボランティアにつきましては、来年の２月から５月を面接として予定していると。研修につきましては、２０１９年の来年の１０月ぐらいから研修をするというようなところまでの情報ですが、私どもが把握しているのは、以上です。","voiceIndex":117,"id":"exchange-034"},{"speaker":"石田（秀）委員","kind":"質問","question":"ぜひこういうのは、意地悪で言っているわけではなくて、それは書いてあることを今お聞きしたと。我々も聞かれたときに答えられる。こういう期間というのはインターネットで見るのですか。ボランティアだってやりたいと思っているけれども、みんなインターネットなのですか。こういうのがわからないではないですか。いつ研修があるとかいったら、会社を休まなくてはならないわけではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":119,"id":"exchange-035"},{"speaker":"いながわ委員","kind":"質問","question":"すみません。お考えなのか、お考えではないのであれば、東京都に言われたとおりにただ配置されていくだけなのかとか、その辺について簡単でいいので教えてください。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そうした意味で、まだ都市ボランティアがどういうふうに配置されるかというようなことが明らかに見えてございませんので、そうした組織委員会の動きを見ながら、区としても考えてまいりたいと考えています。","voiceIndex":121,"id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6530#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":36977,"voices":128}},{"id":"h30-20180305-3","meetingId":"h30-c-budget","date":"2018年3月5日","dateIso":"2018-03-05","committee":"予算特別委員会","time":"午前１０時００分～午後 ６時０３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を175件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"たけうち副委員長","kind":"質問・要望","question":"会派におかれましては、１人当たりの質問時間は、答弁時間も含めて、１０分、１５分、２０分のいずれかとし、会派で割り振ることとしております。なお、無所属の委員の質問時間は、答弁時間も含めて、１日につき１０分となります。終了時間のお知らせにつきましては、残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":4,"id":"exchange-001"},{"speaker":"渡部委員","kind":"提案","question":"おはようあります。総括質疑まで長い期間続きますが、会派としてもさまざま勉強等積んでまいりましたので、いろいろ教えていただければと思います。提案、要望等もしますので、よろしくお願いします。一番最初なのですけれども、ページ数はないのですが、先週ご報告いただきました福井県坂井市の雪害等に関する状況ということで、区から今回も義援金が出されるというご説明がありました。","respondent":"米田危機管理室長","answer":"これまで坂井市側と被害状況、支援の必要性に関する連絡を所管のほうでとり合ってきたのですけれども、市側の豪雪への緊急対応の状況も落ち着いてきて、費用もかなりかかっているというようなことですので、品川区大規模災害被災地に対する支援に関する条例に基づき。","voiceIndex":9,"id":"exchange-002"},{"speaker":"渡部委員","kind":"質問・要望","question":"考えるところ、人口も増えている、景気もよくなっているなどの要因が挙げられると思うのですが、実際今回もこれだけの増額補正が入った経緯、わかれば教えていただきたいのと、あわせて伺いますけれども、実は補正の裏に隠れている、先ほど冒頭区長からのご挨拶の中にもありましたふるさと納税で、前回の決算特別委員会等の中でもいろいろご説明もいただいておりまして、本年度の流出がおおむね６億円。","respondent":"秋山財政課長、伊東税務課長","answer":"特別区民税の見込みですけれども、このところ人口が増えております。入りの部分ですけれども、平成２９年度としては全くその額には及ばないところではありますが、今現在、１１０万円ほどの入りを見込んでいるところです。","voiceIndex":11,"id":"exchange-003"},{"speaker":"渡部委員","kind":"提案","question":"状況を聞かせていただきました。これも平成２９年度は終わってしまうことでありまして、明日から始まります平成３０年度予算のほうのところで、さまざまご提案等も私どもでさせていただきたいとは考えておりますが、２３区さまざまなところでさまざまな取組みがされていると思います。Ｙａｈｏｏ！それと手数料のところはあらあら承知していますが、少し教えてください。","respondent":"伊東税務課長","answer":"クレジット納付の状況ですが、今年の１月からクレジットカードでの納付を開始したところです。速報値ですが、２月末で１６４件のクレジット納付があったということで報告がされております。金額にしては約１,３００万円ほどです。","voiceIndex":14,"id":"exchange-004"},{"speaker":"渡部委員","kind":"質問・要望","question":"件数を聞きましても、１月スタートでこれだけの件数で入ってきているということは、それなりにご利用されている方、希望されている方がいらっしゃるのかなとは感じています。この後、税もそうですし、新年度は国保等でも始まると思いますが、さまざまな形、推移を見ながら、これから先もさまざまな納付方法の研究をしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"私からは３６ページ、次世代育成支援対策施設整備交付金、それと４４ページの学校施設トイレ整備支援事業補助金、４２ページのまちづくり緊急推進事業補助金、公衆便所費、公園・児童遊園維持管理費からお伺いしたいと思います。","respondent":"佐藤保育課長","answer":"具体的には平塚シルバーセンター跡のオアシスルームと、第三庁舎内のオアシスムールに関しまして、この間ずっと調整をしてきたのですが、採択がおりましたので、こちらのほうをお願いしています。","voiceIndex":18,"id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"このオアシスルームですけれども、オアシスルームとは、現在品川区に９カ所あり、またこれから２カ所増えていくというところです。その視点からお伺いをさせていただきたいと考えています。そこでまず、平成２８年度の利用実績は大体１万６,０００人と認識をしておりますが、この平成２９年度、現在までの利用状況と、各施設での利用の傾向をお知らせいただきたいと思います。","respondent":"佐藤保育課長","answer":"オアシスルームに関するお尋ねです。１点目の利用状況は、今委員ご指摘のとおり、大体１万６,０００人から１万７,０００人ぐらいの間で、平成２９年度の実績は出るものと考えております。","voiceIndex":20,"id":"exchange-007"},{"speaker":"新妻委員","kind":"質問・要望","question":"新しい施設でありますので、皆さん関心を持って使われていくのかと思うところもありましたけれども、この利用率の低さというところで、何かこれが原因といいますか、理由というのはどのようにお考えでしょうか。このオアシスルームにおいても、それぞれの箇所の特徴も入れながら、このマップを作成していただきたいと思いますが、いかがでしょうか。","respondent":"佐藤保育課長","answer":"委員ご提案のマップの掲載ですが、インターネットシステムは区のホームページから入っていって、オアシスルームのページからまたリンクを張る予定ですので、そのあたりにわかりやすい地図のほうを載せて、より周知に努めてまいりたいと考えております。","voiceIndex":22,"id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"区民の方がわかりやすく確認ができるような体制を整えていただきたいと思います。そして、平成３０年度から、このようにデータ化をされてネットでの予約が開始されます。コールセンターでの細かい対応もしていただけるということです。区にもこのような要望が来ているかと思いますが、この勝島・八潮地域へのオアシスルームの展開というのはどのようにお考えかお聞かせください。","respondent":"佐藤保育課長","answer":"１点目の手続のほうの簡素化なのですが、一応オアシスルーム、一時利用ではありますけれども、命を預かる施設ということで、一度ご利用する施設のほうでの面接というものは省略できないと考えておりますが、一度面接したところ。","voiceIndex":24,"id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"場所を確保することも大変な困難が伴うこともあると思いますけれども、ぜひよろしくお願いいたします。次に、学校施設トイレ整備支援事業補助金について伺います。現在、我が会派からもたびたびトイレの洋式化を要望させていただきまして、大幅に、大きく進んでいることと認識をしております。どのようなスピード感で進んでいくのかということをお知らせいただきたいと思います。","respondent":"品川庶務課長","answer":"洋式のほうが６６、和式が３４という形です。それから今年度、また力を入れて進めていきたいと考えております。一応来年度末の予測としましては７０対３０、７割が達成できるというような見込みで進めている状況です。","voiceIndex":26,"id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"さらに加速をさせていただきたいと思いますが、１００％を目指すことを私ども会派としては要望していますけれども、この洋式化、やるべきところは早く達成していただきたいという思いで、加速していただきたいと思いますので、よろしくお願いいたします。","respondent":"品川庶務課長","answer":"学校でのトイレ教育ですが、基本的にはまず市民科のほうで、１年生のときに和式トイレの使い方というものを市民科の教科書に載せております。その中でトイレ教育について、教員のほうが少し進めてお話をするというようなところでやってあります。","voiceIndex":28,"id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"その考え方について少しお伺いをしたいのですが、設置はなかなか難しいところもあると思いますけれども、例えば携帯タイプのもの、そういう「音姫」の携帯タイプがあったりするのです。それを持ち込んでいくとか、また、設置も考えられるということもあるのか、少しお考えをお聞かせいただきたいと思います。","respondent":"品川庶務課長","answer":"それからこのあたりの、例えば温水洗浄便座とか、あと便座除菌クリーナーとか、そういった面も問題としてはあるかと思いますけれども、この辺につきましては国や都の動向、それから他の市区町村の動きなども見て考えていきたいと、このように考えております。","voiceIndex":30,"id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"ぜひ品川区として寄り添ったご検討をお願いしたいと思います。最後にまちづくり緊急推進事業補助金についてお伺いいたします。洋式化をするときに、このトイレの中に、用を足しているときに赤ちゃんを座らせておく、メーカーによってはベビーキープであったり、ベビーチェアーといっているようですけれども、この設置を必ずするということを前向きにご検討いただきたいと思うのですがいかがでしょうか。","respondent":"溝口公園課長","answer":"現在だれでもトイレの設置を進めておりまして、その中でベビーチェアーというものは設置をしていくところです。そのほかにつきましても、今後整備する中で検討していきたいと考えているものです。","voiceIndex":32,"id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"私からは、５９ページの衛生費、保健所の職員給与費に関連して、保健所の役割、カプセルホテルと近隣住民の関係についてお伺いしたいと思います。このカプセルホテルを建設する際、旅館業法に基づいて看板の設置が行われますけれども、この看板設置の趣旨は何か、そして近隣住民への説明をどう指導されているのか、現状をお聞かせください。","respondent":"井浦生活衛生課長","answer":"事前に許可申請予定者に対する指導といたしまして、標識を設置して近隣によく説明をしまして、トラブルのないように進めていただくというようなことを指導しています。","voiceIndex":35,"id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"標識を設置して近隣によく説明するようにというご説明でした。具体的に、西大井駅近くの西大井六丁目において、株式会社イノベーターズによる計画で、敷地面積は１１３m2、２階建て、客室は１９室のカプセルホテルの計画です。この計画がカプセルホテルだと電話で説明があったのは、看板設置から約１カ月後のことでありました。このような業者の対応は問題だと思うのですけれども、いかがでしょうか。","respondent":"井浦生活衛生課長","answer":"許可申請の前の事前相談の段階の手続ですが、さまざまな近隣の声を頂戴しながら、ときには業者に直接連絡をする、そして監督・指導するというような形で、適切に説明をしていただけるように努めているところです。","voiceIndex":37,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問","question":"区は指導されていると思うのですけれども、今伺ったのは、このような対応は問題ではないのかと思うのですが、その点についてお伺いしたいと思います。西大井六丁目は準工業地域ということですが、現状ではほとんどが住宅地です。ぜひ旅館業法に基づく建物を建てる場合は、最低限説明会の開催をしっかり条例で義務化して、良好な住環境を守るルールづくりが急がれていると思いますが、いかがでしょうか。","respondent":"井浦生活衛生課長","answer":"旅館業法につきましては、もともと用途地域の指定というものがございまして、さらに学校施設、教育福祉施設等につきましては、それぞれの関係行政機関に意見を聞きまして、さらに品川区の要綱に基づき。","voiceIndex":39,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"私が伺ったのは、今回のこのケースはまず問題ではないのかと。それを解決するために説明会の開催の条例化が必要ではないかと、そう指摘をいたしました。改めて問題ではないのか、条例化をなぜ検討しないのかお伺いしたいと思います。","respondent":"井浦生活衛生課長","answer":"その結果、説明会の開催ということも業者のほうで提案されたということで聞いているところです。","voiceIndex":41,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"この現状がある中で、これを問題だと思わないのか、解決のために条例で説明会の開催を義務づけることが必要ではないかと思うのですけれども、はっきりとお答えいただきたいと思います。一体保健所は誰の何を守ろうとしているのか、しっかり良好な住環境を守る責任があると思うのですけれども、いかがでしょうか。","respondent":"井浦生活衛生課長","answer":"その中で旅館につきましては、もともと説明会というようなところまで制度が構築されているところではございませんので、東京都、特別区等の動向も踏まえながら、私ども、どのようなところに課題があるというようなところは研究しています。","voiceIndex":43,"id":"exchange-018"},{"speaker":"中塚委員","kind":"確認","question":"でも、現状ほとんどが住宅街になっているというのが実態です。私も調べてわかったのですけれども、今回の業者は１月１４日に看板を設置して、２日後の１月１６日に建築確認を受けております。そしてこうしたケースが、２０２０年東京オリンピックに向けて、区内各地で広がっているのではないかと私は思うのですけれども、この簡易宿所、カプセルホテルの動きについては、区内ではいかがでしょうか。","respondent":"井浦生活衛生課長","answer":"旅館業営業許可申請に伴う標識の設置につきましては、営業許可申請の１５日前までに標識を設置して、建築確認の表示が国土交通省令に基づいて出されるまで継続して掲示するようにというようなところで、要綱で定めているところです。","voiceIndex":45,"id":"exchange-019"},{"speaker":"中塚委員","kind":"確認","question":"今回のケースは、その要綱が守られていないということなのです。大体標識が出て２日後に建築確認の審査が通っている。住民がその標識にある電話番号に電話をしてもつながらない。つながらないのです。何回電話しても。これでもその要綱が守られているという認識なのか、私はしっかりと条例化して、説明会の開催を義務づけるべきだと思うのですけれども、いかがでしょうか。","respondent":"井浦生活衛生課長","answer":"いずれにしましても、このような手続面も含めたトラブルの防止という意味では、旅館業営業許可申請と建築確認申請については同時に行うように指導してまいりたいと考えています。","voiceIndex":47,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"この業者は品川区が電話すると出るのです。住民が電話すると出ないのです。この旅館業法に基づく建物について、最終的に営業許可をおろすのは保健所長と伺いました。これを問題なしとしてしまったら、このように住宅街にカプセルホテルができ、近隣住民とのトラブルになるケースが今後も広がっていくのではないかと私は心配しているのですけれども、その現状認識についても伺いたいと思います。","respondent":"井浦生活衛生課長","answer":"そのような中で、どのように規制していくのか、あるいは区として誘導していくのかというようなところについては、大きな都市計画、まちづくりというようなところの分野もかかわってまいりますので、庁内関係課とも連携いたしまして、また、東京都。","voiceIndex":49,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"先ほど来、適切な指導とおっしゃるのですけれども、今回のケースは単に建物の基準が合っているとか、保健衛生とか、そこがクリアしているというだけではなくて、近隣住民との関係がつくられていないのに計画を進めるというのは問題ではないかと、そう伺っているのです。それだけに、改めて説明会の開催を義務化する、そのような規制が必要だと思いますけれども、いかがでしょうか。","respondent":"井浦生活衛生課長","answer":"その高さ制限に今回は該当しないというような建築物の許可をめぐる事前の手続ですので、再三申し上げてありますが、品川区の要綱に基づきまして適切に指導していくという中で、生活環境の確保を図ってまいりたいと考えています。","voiceIndex":51,"id":"exchange-022"},{"speaker":"大倉委員","kind":"質問・要望","question":"私からは３７ページの公園・児童遊園整備についてと、５７ページの認証保育所運営費について伺います。","respondent":"大澤待機児童対策担当課長、溝口公園課長","answer":"２月の上旬に認証保育所１園から、近隣で工事が予定されているので、保育に懸念があるということでご相談を受けました。それについて、区と事業者で３回にわたって話し合いを持ったところです。健康遊具につきましては、しながわ中央公園等含めて３４公園に、そういった健康遊具というものが設置されているものです。児童遊園につきましては、児童福祉法に基づく公園というのは２カ所指定されたものがあります。","voiceIndex":54,"id":"exchange-023"},{"speaker":"大倉委員","kind":"質問・要望","question":"健康遊具３４公園ということで、あと１点、児童福祉法における児童遊園の設置が２カ所ということで、そのほかの、例えばここに書いてある児童遊園１００カ所ぐらい、ここというのは今名前などは公園になっていなくて、そのまま児童遊園なのか、この辺の名前などという部分の考え方、一方では児童遊園というのは何ですかというような声もあったりする中で、名前について今後どのような。","respondent":"大澤待機児童対策担当課長、溝口公園課長","answer":"近隣での工事の場合、保育施設は工事箇所からの距離にもよりますし、あとはその保育施設が木造か、鉄骨かというような、いろいろ条件によっても変わってくるとは思いますので、一概に近隣で工事があるからといって。そのほかにつきましては、例えば敷地の権原をお借りして公園に設置しているとか、また防災目的で設置している防災広場ですとか。","voiceIndex":57,"id":"exchange-024"},{"speaker":"大倉委員","kind":"質問・要望","question":"公園についてなのですが、今後改修が計画されている中で、もう既にいろいろなところで子どものアイデアを活かした公園等やられているところで、学校とか、児童センターとか、特に子どもが利用する環境がある公園については、ぜひ子どもの声も、聞いていただいているとは思いますが、そういった地域の施設の声を聞きながら取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":60,"id":"exchange-025"},{"speaker":"藤原委員","kind":"質問","question":"１３ページの国保ですけれども、まず、１７億８,０００万円余減額しているのですが、その理由についてお伺いします。それと６３ページの補助１６３号線整備なのですけれども、今区役所のガードの東急線の工事をしていますが、これの進捗状況、完成の見通しについて変更はないのか、そして今回のＪＲの大崎支線というのですか、区役所の大崎寄りの坂下、これの見通しは甘かったのでしょうか。","respondent":"三ッ橋国保医療年金課長、大澤待機児童対策担当課長、黒田人事課長、品川庶務課長、多並道路課長","answer":"こちらが一番大きいです。次に窓口業務に関しましては、引き続き品川区が今までどおり対応してまいります。最終的に２０年後とか、２５年後では、閉園するような園も出てくるかとは思いますが、そのときに利用者に混乱がないように。この寄附元ですが、こちら共済企画センターという有限会社でございまして。以前勤めていた学校のほうでこれを使うというようなことになっております。大井町線ガードにつきましては、当初の予定どおり平成３２年度の道路整備完了ということで、工事を順調に進めているところです。","voiceIndex":62,"id":"exchange-026"},{"speaker":"藤原委員","kind":"質問・要望","question":"それと補正予算全体について伺いたいのですけれども、今回の一般会計の補正予算なのですが、トータルで約２６億円の増額補正となっているのですけれども、これを見ると当初予算の精度がどうなのかなという思いがでます。そこで今回の補正の増額分で幾らか、減額分で幾らか、またそれぞれ何％に当たるのかお伺いします。","respondent":"秋山財政課長","answer":"パーセントにつきましては、今１,６５５億円の内訳ですので、数％ということだと認識しております。","voiceIndex":68,"id":"exchange-027"},{"speaker":"藤原委員","kind":"質問","question":"補正予算の意義といいますか、位置づけです。当初予算の精度はどうなのでしょうか。本当に高いと言えるのでしょうか。これだけ多くの額を基金に積み立てに回せるなら、その品川区の各施策はすばらしいと思うのですけれども、これはもう当初予算から計上してもいいのではないかと私は思うのですが、その辺についてはいかがでしょうか。","respondent":"秋山財政課長","answer":"当初予算の精度というものは高めていかなければいけないとは思っておりますけれども、今回の増額、減額というのはタイムリーに施策を行っていくという面で必要不可欠だったということで、今回補正という形で出させていただいていると認識しております。","voiceIndex":70,"id":"exchange-028"},{"speaker":"吉田委員","kind":"質問","question":"順番は違うのですけれども、最初に７２ページの後地小学校の用地の購入について、校内の一部の国有地を買い取るということで、ほぼうまくいくというふうに、以前お問い合わせをしたとき伺っていたのですが、それが減額になった理由を教えてください。この基金の積立ての考え方を伺いたいと思います。このように書かれた場合、目標額があるなら、普通は当初予算で３０億円計上するのではないでしょうか。","respondent":"品川庶務課長、秋山財政課長","answer":"こういったものを算定はしていたのですけれども、国のほうでの算定と大きくずれてしまったということで、こういった状況になってあります。このような基金のほうに積み立てるというのは、やはり万が一のときに、いざというときのためにですので、そこの部分を当初の予算で見込むというよりも、ある程度財政状況等を踏まえて歳入。","voiceIndex":73,"id":"exchange-029"},{"speaker":"吉田委員","kind":"質問","question":"申しわけありません。１つ言葉を抜かしました。後地小学校の用地購入、次年度、次の予算で計上されていないのだけれども、今後に向けた考え方について伺いたい。そうしたら、私はきちんと当初予算で計上すべきではないかと。今回質問するにあたっても、２０１０年までさかのぼってこの基金積立ての当初予算と最終補正の額を調べたのですけれども、どう考えて予算立てをしているのか、よく読み取れないのです。","respondent":"品川庶務課長、秋山財政課長","answer":"後地小学校の用地、国有地ですけれども、今年度無事購入をできましたので、来年度のほうは予算計上してございません。予算の積み方というか、基金の積み方ですけれども、条例に書いてある予算で定めるということについては、補正予算も予算ですので、今回予算の中で定めているというのが答えといえば答えなのですが、ただ。","voiceIndex":76,"id":"exchange-030"},{"speaker":"吉田委員","kind":"質問","question":"基金なのですけれども、やはりこれ、前のときも補正の考え方というところで伺っているのです。当初予算は１０月の現人数で予算が立てられているということは承知しております。ですから、補正がかかるのは当然かなと思いますが、これ多少でも増減があれば全部この補正予算に記載されるのか、まずそれ１点伺いたいのと、それから５８ページの保健衛生施設費の職員給与費の追加分、増額の要因を教えてください。","respondent":"黒田人事課長","answer":"児童福祉施設費の減額につきましては、こちら１０月１日の現員現給では、当初は職員数自体は、例えば保育園ですと７１２名だったものが、平成２９年１０月１日の現員ですと７２８人ということで、人数は増えているのですけれども、採用しますと初任給という形で。","voiceIndex":79,"id":"exchange-031"},{"speaker":"吉田委員","kind":"質問","question":"保健衛生施設費の職員給与費の追加について、あらかじめお問い合わせしたのとお答えが違ったので、それでいいのかもう１回教えてください。若い方が入れば人件費が少し減って、その分ベテランがやめればということで増減があるというのは理解できるのですけれども、この額でいうと、本当にそれだけでこれだけの差が出るのかなということで、現人数、定数に照らし合わせて今どうなのかも教えてください。","respondent":"黒田人事課長","answer":"保育園につきましては、どうしても女性が多い職場ということで、育休者がおりますと年度途中に職員が欠になるというような状況がございまして、そういった意味では職員が減っているという状況がありますので、今年度、先ほど７２８人と申し上げましたのは。","voiceIndex":81,"id":"exchange-032"},{"speaker":"吉田委員","kind":"質問","question":"申しわけありません。要は言いたいのは、これ増減出ておりますけれども、仕事の忙しさとか、そういう人の問題とかで、人数が足りないのではないかということを感じているものですから、このような質問をさせていただきました。時間がないので次に行きます。ここに計上されている返還分が２０１６年度事業に関するもので、どのように算定されているかについてはあらかじめ伺いました。","respondent":"矢木生活福祉課長","answer":"この点につきましては、そもそもこちらの国庫支出金返還金の性質を申し上げなければいけないと思うのですが、この返還金の性質の主な内容といたしましては、医療扶助と介護扶助、すなわち緊急時のインフルエンザなどの対応ですとか、あと入院ですとか。","voiceIndex":85,"id":"exchange-033"},{"speaker":"吉田委員","kind":"質問","question":"この返還の額については了解をしましたが、やはり生活保護費でいうと、この１０％を限度に減額というのは影響があったかと思うのですけれども、その辺の影響について改めて教えていただけますか。","respondent":"矢木生活福祉課長","answer":"こちらにつきましては、厚生労働省標準世帯というものがございまして、３３歳の父、２９歳の母、４歳の子の世帯で推移を見るものですが、生活扶助基準額の推移ですけれども、平成２４年４月１日では１６万２,１７０円。","voiceIndex":87,"id":"exchange-034"},{"speaker":"吉田委員","kind":"質問","question":"そうすると３年間、ここまで１０％限度の減額ですので、全部が１０％ということではないかと思うのですが、その辺ざっくりでいいので、合計でいうとどれくらいの影響が出ているかということを教えてください。","respondent":"矢木生活福祉課長","answer":"全体の影響というのはなかなか難しいものでございまして、こちら算定はしてございません。","voiceIndex":89,"id":"exchange-035"},{"speaker":"吉田委員","kind":"質問","question":"算定は難しいということなのですけれども、その厚生労働省モデル家庭でいったらどうかだけでも教えてください。","respondent":"矢木生活福祉課長","answer":"失礼いたしました。生活扶助基準額、厚生労働省標準世帯につきましては１万２,０６０円の生活扶助基準額の減額でございました。","voiceIndex":91,"id":"exchange-036"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはり全体の額からの１家族で約１万２,０００円の減額というのは、かなり大きなものかなと思います。今年の１０月から生活扶助費がまた減額となっております。３年間の減額の検証がされないままではないかという識者からの批判もあります。国としての検証を品川区として求めるべきと考えますが、その点についてお考えをお知らせください。","respondent":"矢木生活福祉課長","answer":"品川区での検証ですが、こちら生活保護制度はそもそも第一号法定受託事務ということで、国の事務です。国としての動向調査等は平成３０年度のこちらの基準の見直しの中で、国の生活保護基準部会が扱っているところですので、特に品川区独自の影響を算定する考えはございません。","voiceIndex":93,"id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"国の事業ではありますけれども、やはりそれがどのように影響してくるかというのは、その区のその後の施策に関連してくるかと思うのです。算定が難しいというのはよく理解できますけれども、それでもやはり何らかの形で検証する、もしくは、やはり国の事業ということであれば、国全体として検証をしながら進めるべきということは、品川区としてもぜひ意見を言っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-038"},{"speaker":"横山委員","kind":"確認","question":"私からは、３７ページのオアシスルーム運営費、１０６ページ、特定健康診査等事業費についてをお伺いいたします。１点目に、特定健康診査等事業費についてお伺いをいたします。今年度の取組みと来年度の取組み、それぞれどのようなものか確認させてください。","respondent":"三ッ橋国保医療年金課長","answer":"今年度の健診受診率の向上対策ですけれども、この未受診者勧奨の通知、また早得キャンペーンの実施など、医師会と連携をしながら、共同で受診啓発を実施してまいりました。来年度も引き続き、早得キャンペーンなどを継続実施してまいります。","voiceIndex":97,"id":"exchange-039"},{"speaker":"横山委員","kind":"質問","question":"風邪ですとか、インフルエンザなどが流行する冬の時期ではなくて、年度初めの春からの健診を促すという早得キャンペーンでしょうか、こちら大変よい取組みだと考えております。早得キャンペーンの内容なのですけれども、具体的にはどのようなものでしょうか。","respondent":"三ッ橋国保医療年金課長","answer":"この早得キャンペーンの内容ですが、５月から８月までの早期受診者を対象にいたしまして、平成３０年度につきましては品川浴場組合の入浴券をプレゼントいたします。","voiceIndex":99,"id":"exchange-040"},{"speaker":"横山委員","kind":"質問・要望","question":"キャンペーンの内容、品川浴場組合の入浴券ということで、１月２２日の厚生委員会のほうで、我が会派の鈴木真澄委員より、「公衆浴場のない地域への配慮をお願いしたい」という要望をしていますので、さらなる受診啓発につながるキャンペーンの利用のしやすさについて、今後も工夫のほうをお願いできればと考えています。より参加のしやすい保健指導のあり方について、区はどのようにお考えでしょうか。","respondent":"三ッ橋国保医療年金課長","answer":"今回軽度リスク者対策を中心に行いまして、そちらにつきましては、測定会と、またセミナー形式での初回面談の実施をしてまいる予定です。","voiceIndex":101,"id":"exchange-041"},{"speaker":"横山委員","kind":"確認","question":"軽度リスク保持者の対策というところ、測定会とセミナー形式での初回面談の実施ということで、忙しくて受診できない方への配慮をされるです。医師会や業者と調整のほう、ぜひよろしくお願いいたします。平成２９年度の決算特別委員会の総括質疑の中でも、データヘルス計画や実施計画の内容を確認させていただきましたが、今年度完成予定のデータヘルス計画と、実施計画の冊子作成状況を教えてください。","respondent":"三ッ橋国保医療年金課長","answer":"今、データヘルス計画、そしてこの実施計画の合冊という考えに基づいて実施しております。冊子は最終確認作業中でございまして、今月末には完成する予定です。","voiceIndex":103,"id":"exchange-042"},{"speaker":"横山委員","kind":"質問・要望","question":"冊子のほう、完成に向けてよろしくお願いいたします。データヘルス計画で目指す全体目標として、被保険者を含む区民のＱＯＬの向上、健康寿命の延伸が挙げられています。図書館とのコラボヘルスなど、広く区民の皆様に健康情報の発信を実施していただきたいのですが、ＩＣＴを活用した健康情報の発信についてはいかがでしょうか。区のお考えをお聞かせください。","respondent":"三ッ橋国保医療年金課長","answer":"これからの時代はＩＣＴを活用した発信というものはとても重要な手段だと考えています。今後はデータヘルス計画評価委員会の中でご意見をいただきながら、どのようなことができるのか区として考えてまいります。","voiceIndex":105,"id":"exchange-043"},{"speaker":"横山委員","kind":"質問","question":"ＩＣＴの活用につきましても前向きに、ほかの委員の方々とご検討いただければと思います。今後の見通しをお伺いいたします。","respondent":"三ッ橋国保医療年金課長","answer":"健康ポイントとして、特定健診の受診者などにポイントを付与する検討をしていると聞いております。国保のデータ活用などを含む詳細につきましては、業者のプロポーザルの提案を踏まえて、今後検討してまいります。","voiceIndex":107,"id":"exchange-044"},{"speaker":"横山委員","kind":"提案","question":"２点目に、オアシスルーム運営費についてお伺いいたします。平成２９年決算特別委員会において、我が会派の渡部委員よりインターネット予約システムの導入と、品川区役所第三庁舎内オアシスルームにおける日曜日の開館についての提案がありました。インターネット、電話予約ともに変更点などはありますでしょうか。","respondent":"佐藤保育課長","answer":"次に予約の変更点ですが、電話予約は廃止いたしまして、インターネット予約のみにしたいと考えております。インターネット予約の画面操作がわからない場合は、コールセンター等で予約を代行して、利用率の向上につなげていきたいと考えております。","voiceIndex":109,"id":"exchange-045"},{"speaker":"横山委員","kind":"質問・要望","question":"これらは子育て中でどのような方でも一度は感じる思いではないでしょうか。区は区内９カ所のオアシスルームに加えて、品川区役所第三庁舎オアシスルーム、平塚シルバーセンター跡にオアシスルームの開設を進めておりますが、在宅子育て家庭が社会からの孤立感を感じることのないように、育児負担の軽減と保護者のリフレッシュを今後もさらに応援していただきたいと要望いたします。","respondent":"佐藤保育課長","answer":"現時点で制度上はご利用いただけませんが、ファミリー・サポート・センターやベビーシッター等をご紹介しております。地域による子育て支援の必要性はより高まっておりますので、保育園、幼稚園等で行っているチャイルドステーション事業等を拡充してまいりたいと考えております。","voiceIndex":111,"id":"exchange-046"},{"speaker":"横山委員","kind":"意見","question":"民間企業では子育て中の女性の活躍を応援するお子さん連れが可能なコワーキングスペースですとか、シェアオフィスなどの取組みも年々広がっているかと思うのですけれども、今後のオアシスルームが担っていく役割について、この直近から５年、１０年後あたりくらいなのですが、現在の区のお考えをお聞かせください。","respondent":"佐藤保育課長","answer":"オアシスルームの設置の目的は、在宅子育て世帯の社会参加を図るとともに、育児疲れや保護者の心理的負担の軽減でもあります。今後も委員ご指摘の趣旨を踏まえまして、在宅子育て支援のさまざまな支援について努力してまいります。","voiceIndex":113,"id":"exchange-047"},{"speaker":"横山委員","kind":"意見","question":"在宅子育て、ワンオペ育児などという言葉もありますけれども、お母様、お父様が孤立してリフレッシュができないなど育児疲れ等ないように、今後もオアシスルーム、キャンセルを減らしていただき、利用率の向上に努めていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":115,"id":"exchange-048"},{"speaker":"つる委員","kind":"質問","question":"７３ページ、学校改築推進経費更正減額、３９、４５ページの校舎等整備、それから３７、４１ページのすまいるスクール運営費について伺っていきたいと思います。学校改築推進経費更正減額ですが、この更正減額７億３,４１０万円の理由、国の算定とのずれという理由で簡単なご説明はありましたけれども、もう少し詳しくこのあたりを教えてください。","respondent":"品川庶務課長","answer":"当初そういったところも勘案して算定はしたのですけれども、やはり国のほうでの算定評価と大きくずれが出たです。","voiceIndex":118,"id":"exchange-049"},{"speaker":"つる委員","kind":"確認","question":"わかりました。購入された土地は３,３００m2で、坪に直すとちょうど１,０００坪ということです。今回更正減額されて実際の購入金額で、単純に１坪当たりの単価を比較すると、３９万円ですか。もともとの算定で出していた、予算で出していたのが１坪１１２万円ぐらいかと思うのですが、これでよろしいかどうかという確認をお願いします。","respondent":"品川庶務課長","answer":"おおむね、こちらも平米単価で出していたもので、坪変換まではしていませんが、計算上そのような差が出ているです。ですので、単価のところで大きく違いが出ると、そこで平米数がかなり大きいので、金額にも大きな差が出るです。","voiceIndex":120,"id":"exchange-050"},{"speaker":"つる委員","kind":"質問","question":"それが当初が坪でいうと１１２万円ぐらい、１m2でいうと１１８万４,５００円ぐらいですか、１１８万円ぐらいになると思うのですが、たしか。計算したらそうなっていました。その上で全体の話ですが、当初予算で後地小学校のほかは大井第一小学校、延山小学校、それから鮫浜小学校も含めての予算立てがあったかと思いますので、それぞれどこからの土地の購入で、購入金額は幾らなのか教えてください。","respondent":"品川庶務課長","answer":"今回大井第一小学校、それから鮫浜小学校、それと延山小学校と、学校の近隣の用地、これについて空きが出たというか、引っ越し等をされて売却の予定があったというようなところで、学校用地として少しでも広げていくほうが、子どもたちのためにも利用しやすいということで。","voiceIndex":122,"id":"exchange-051"},{"speaker":"つる委員","kind":"質問","question":"そうすると１億２,９００万円ぐらいですか。１億２,９００万円足す、先ほどの３億９,０００万円だから、５億円ぐらいが合計でという計算で、単純な足し算の話ですけれども、わかりました。それで、これは教育債で起債をされていると思うのですけれども、その起債についてはいつされるのか、そのタイミングを教えてください。","respondent":"秋山財政課長","answer":"こちら教育債で今回補正をしています４億１,５６０万円につきましては、金額が確定して国や都との協議が整った後ということで、これから起債の手続に入る、平成２９年度中に歳入の予定です。","voiceIndex":126,"id":"exchange-052"},{"speaker":"つる委員","kind":"意見","question":"私も基本的なところですけれども、このような起債の場合は９割が起債でできて、土地の代金ですね。９割が起債にできて、その後、これについては財調の措置がされるということの流れになると思うのですが、その辺の仕組みについて少し詳しく、改めて教えください。","respondent":"秋山財政課長","answer":"今回起債をする予定が４億１,５６０万円ということで、これについては平成３０年度以降、財調の基準財政需要額の算定に、元利償還金分ですね。毎年返済する元金と利子の分が財調の基準財政需要額の中に算定されるという仕組みになってあります。","voiceIndex":128,"id":"exchange-053"},{"speaker":"つる委員","kind":"質問","question":"ちょっと単純に引き算したのですけれども、予算ベースですが、そうすると３４１万円ぐらいが後地小学校の年間の借地料になるのかなと思ったのですけれども、まずこの後地小学校の借地料が幾らなのかというところと、それから後地小学校以外の６校、その小学校が借地の部分について何小学校なのかというところと、借地については、先ほど後地小学校については旗ざお状の形状で一部というところでしたが。","respondent":"品川庶務課長","answer":"それから学校、今全校で７校あるのですけれども、山中小学校、延山小学校、大原小学校、宮前小学校、源氏前小学校、旗台小学校、後地小学校、今年度のトータルの借地料としましては、約３,１００万円になります。","voiceIndex":130,"id":"exchange-054"},{"speaker":"つる委員","kind":"確認","question":"今お聞きした借地料についてなのですが、ここは３年に一度、２００９年とか２０１０年ぐらいの質疑をちょっと確認させていただいたら、３年に一度見直しをするという中で、当初はその当時２０％一気に上がるというところが、段階的に３％ずつぐらいとなっていましたけれども、その３年に一度のタイミングというのが、この近年だと何年になるのか教えてください。","respondent":"品川庶務課長","answer":"３年に一度のタイミングですと、ちょうど今年度がタイミングとなっております。大体３年間で増加分としましては、先ほどお話あったように３％程度上昇をしているです。","voiceIndex":134,"id":"exchange-055"},{"speaker":"つる委員","kind":"確認","question":"そうすると３年に１回３％アップしているので、２００９年、２０１０年から８年ぐらいですから３回ぐらい、二、三回アップされて都合６％とか９％とか、そのときよりも上がっているという理解をしました。","respondent":"品川庶務課長","answer":"現在のところ、各年において３％から４％ずつ上昇しているようなペースで進めてあります。先ほどもお話ししましたが、来年度末には７０％達成するという見込みでありますので、このペース、他区の状況なども見ながらペースのほうは考えていきたいと考えています。","voiceIndex":136,"id":"exchange-056"},{"speaker":"石田（ち）委員","kind":"質問","question":"私は５８ページ、５９ページの生活保護費にかかわって、２０１８年の生活保護制度改正について伺いたいと思います。国は生活保護利用世帯の６８％、約７割が食費や日常生活に充てる生活扶助費を最大５％削減する方針を決定しました。２０１３年には最大１０％という過去最大の生活保護基準の引き下げを行っております。これが１０月に行われたら、生活保護受給世帯はどうなってしまうのか。伺います。","respondent":"矢木生活福祉課長","answer":"そして考え方といたしましては、一般低所得者の消費実態などを踏まえながら、その生活水準とバランスのとれた適切な基準に設定するということになってあります。","voiceIndex":139,"id":"exchange-057"},{"speaker":"石田（ち）委員","kind":"質問","question":"今私はこの生活保護を受給されている区民の方を一番近くで見ている自治体として、これが実行されたら、この大改悪がまた実行されたら、どういう生活に追いやられてしまうのかということを伺いましたので、もう一度お願いします。","respondent":"矢木生活福祉課長","answer":"こちら、先ほど申し上げたとおり、一般低所得者の消費実態を踏まえて、その生活水準とバランスをとるという形で国が決めているものです。","voiceIndex":141,"id":"exchange-058"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですから、そういったことも含めて、さらにこの生活保護受給世帯、最後のセーフティネットと言われている、この生活保護がさらに引き下げられるというのは、本当に厳しい状況に追いやられていくということであると思いますし、また今回は３歳未満のいる家庭、先ほども言いましたけれども、児童養育加算が月５,０００円減らされます。区は、この辺はどのように考えているでしょうか。","respondent":"矢木生活福祉課長","answer":"２点目、生活保護基準の影響を及ぼす範囲ですが、委員ご指摘のとおり、こちらもまたほかの制度に影響を与えないようにということで考えているようですので、そのような形になると考えます。","voiceIndex":143,"id":"exchange-059"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"先ほども他の委員の質問の中で、検証は区独自ではしていかないということを言われていましたが、やはり区民の生活実態ですから、ぜひそこは把握していっていただきたいと思います。品川区ではどうなのでしょうか。生活保護受給対象となる、今保護を受けていない低所得世帯の把握はされているのでしょうか。そしてまた、捕捉率が低い理由は、区としてはどう考えているか教えてください。","respondent":"矢木生活福祉課長","answer":"生活保護の制度は申請主義でございまして、生活にお困りの方がさまざまなご相談をされるという中で、最低生活費に満たない収入の方につきましては、生活保護の受給を開始するという、そういった制度です。","voiceIndex":145,"id":"exchange-060"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ各窓口、税金滞納や国保滞納などされている、困窮されているなという状況が見られる方々には、生活福祉課だけでなく、各窓口で生活保護のしおりだけでもいいので、配っていただきたいと思いますし、制度の周知、そしてセーフティネットがあるということを周知していただきたいと思いますけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-061"},{"speaker":"筒井委員","kind":"質問","question":"私からは３４ページ、特別区民税、４０ページ、待機児童解消区市町村支援事業補助金、そして４６ページ、繰越金についてお伺いをいたします。平成２９年度、今回の補正予算の特別区民税についてなのですけれども、９億７,７９０万円となっております。そうした景気や個人の所得が向上したということも考えられるかなと思うのですけれども、そのあたりのご見解をお聞かせください。","respondent":"伊東税務課長","answer":"それと１人当たりの税額ですけれども、こちらに関しても当初見込んでいた額よりも７,０００円ほど増加ということで計算しています。","voiceIndex":149,"id":"exchange-062"},{"speaker":"筒井委員","kind":"質問","question":"そうした背景というものについてのご見解をお聞きしたかったのですけれども、そうした景気の動向とか、そういったことも関連しているのかということをお聞きしたいのですが、いかがでしょうか。","respondent":"伊東税務課長","answer":"背景ですけれども、１つには納税義務者が増えたというところがありますが、それともう１点、昨年の状況、労働力調査等々を見ますと、完全失業率も下がっているということと、あとは都内の賃金に関しても０.４％の増というような報告もありますので。","voiceIndex":151,"id":"exchange-063"},{"speaker":"筒井委員","kind":"質問","question":"２年連続でかなり大きな補正なのですけれども、こうした特別区民税の増額というのは予測が難しいものなのでしょうか。特にここをしっかり正確に予測しないと、各施策に影響や、特に人の数でいくと各施設、特に教育施設などにも影響があると思うのですけれども、そうした予測が困難なのはどうしてかということをお聞きしたいのですが、いかがでしょうか。","respondent":"伊東税務課長","answer":"今言ったように１年おくれで収納というか、払っていただくということになりますので、そのときの状況によっては収納率ということにも影響してまいりまして、その辺を全体的に考えていくという中では、非常に困難性はあるのかと思っておるところです。","voiceIndex":153,"id":"exchange-064"},{"speaker":"筒井委員","kind":"質問","question":"わかりました。ところが、参考までに平成２８年度の場合は４億７,０００万円でした。その差が１３億５,０００万円ほどになっているのですけれども、こうした差が出てきた理由というものは何かあるのでしょうか。もちろん品川区も待機児童解消に取り組んでおりますし、東京都がより力強く待機児童解消施策を打ってきたということも関連すると思うのですけれども、そのあたりの区のご見解はいかがでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"当初予算では、子ども・子育て計画に沿いまして、毎年６園ずつ当初予算で組んでおります。結果的に前倒しで開設を進めまして、平成２９年度は１２園、平成３０年度４月には１６園ということで、開設数が当初予算とは違ってきておりますので、その差額ということになります。","voiceIndex":155,"id":"exchange-065"},{"speaker":"筒井委員","kind":"質問・要望","question":"今後もこうした区のほうも取組みを進めているので、また補正でこうした大きな額が出てくる可能性というのはあるのでしょうか。平成３０年度は東京都も前の平成２９年度より９０億円ぐらい予算案を増額する予定ですけれども、引き続き東京都と品川区のこうした待機児童解消の取組み、進めていっていただきたいのですが、そうしたことについて区のご見解をお聞かせください。","respondent":"大澤待機児童対策担当課長","answer":"今年度、子ども・子育て計画の改定をいたしまして、平成３１年度の開設は１２園となっております。それに合わせて平成３０年度の予算も１２園で予定していますので、平成３０年度につきましては、大きな補正は今のところないかと考えています。","voiceIndex":157,"id":"exchange-066"},{"speaker":"筒井委員","kind":"質問","question":"繰越金についてお伺いしたいのですが、これも平成２８年度と平成２９年度を比べますと、補正の額が１５億円ほど、平成２９年度のほうが増えているのですけれども、その理由をお聞かせください。","respondent":"秋山財政課長","answer":"繰越金ですけれども、これは平成２８年度の歳入と歳出の差額ということで、平成２８年度の決算が６月に出ますので、それ以降、その時点で確定いたしましたので、補正予算でその歳入と歳出の差額を今回こちらで入れるという仕組みになっているところです。","voiceIndex":159,"id":"exchange-067"},{"speaker":"筒井委員","kind":"質問","question":"それは年によってやはり違ってくるものなのでしょうか。","respondent":"秋山財政課長","answer":"その年の決算ですので、決算の最終的な数字が幾らになるのかというのは、その年の使い方、それから歳入の仕方によって変わってきますので、これが一定の数になるということにはならないと考えています。","voiceIndex":161,"id":"exchange-068"},{"speaker":"筒井委員","kind":"質問・要望","question":"なかなかこうした額、差が大きいと、どうしてかなと思ってしまうのですけれども、予算の精度というものをぜひ上げていってほしいと考えておりますので、これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":163,"id":"exchange-069"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は８７ページの品川区国民健康保険事業全体について質問いたします。平成３０年度から国民健康保険制度は大きな制度変更が行われることになりました。先ほども質問がありましたが、補正予算審議にあたり、まずこの国保制度変更の概要と、なぜこのような制度変更が行われることになったのか、ご説明をお願いしたいと思います。","respondent":"三ッ橋国保医療年金課長","answer":"平成２４年の社会保障制度改革国民会議がございまして、それを経て平成２５年、社会保障改革プロセス法案というもの、方針が出されました。それに基づいて、平成２７年に持続可能な医療保険制度を構築するための国民健康保険法等の一部改正がございました。","voiceIndex":165,"id":"exchange-070"},{"speaker":"鈴木（博）委員","kind":"質問","question":"詳細なご説明ありがとうございました。１点だけお聞きしたいのですが、新制度になると、東京都は都内区市町村へそれぞれ納めるべき納付金や、標準的な保険料率を提示し、区はそれを参考にして保険料率を決定するとなるようです。そして品川区は、新たにつくられる特別区統一保険料率方式に参加すると聞きました。この特別区統一保険料率に品川区が参加するメリットが何か、区のお考えをご説明ください。","respondent":"三ッ橋国保医療年金課長","answer":"メリットは大きく３つあります。特別区統一基準保険料率は、平成１２年から長年継続してきた実績があること、そして同一所得、同一世帯の場合は同一の保険料で区民の皆様にわかりやすいこと、そして将来的に都内統一を目指していくための考え方に即していること、この３つです。","voiceIndex":167,"id":"exchange-071"},{"speaker":"鈴木（博）委員","kind":"質問","question":"区のお考えをお聞きしました。制度変更については、今後もさらに議論を深めていきたいと考えております。次に、増大する医療費を抑制する目的で医療費適正化施策が行われていますが、この医療費適正化施策の１つである後発医薬品利用促進についてお尋ねいたします。このジェネリックの利用促進について、その目的と現在どのような取組みが行われているか、ご説明をお願いいたします。","respondent":"三ッ橋国保医療年金課長","answer":"ジェネリック医薬品についてですけれども、こちらは花粉症や風邪に関する処方箋に加えて、区といたしましてはジェネリック医薬品の周知および使用促進を実施しております。こちらはやはり高額な医療費の抑制というものが大きくございまして、そちらを目的としております。","voiceIndex":169,"id":"exchange-072"},{"speaker":"鈴木（博）委員","kind":"質問","question":"もしも後発品を推奨するならば、幾ら医療費が安くなりましたというような価格面だけを強調するのではなくて、患者の健康と安全のために全てのジェネリックを推奨するのではなく、先発品と同様の効果を持つ後発品だけを十分な薬剤情報を患者に提供しながら推奨するべきだと考えますが、区のご見解はいかがでしょうか。","respondent":"三ッ橋国保医療年金課長","answer":"実際には医師や薬剤師の皆様方の丁寧な説明が必要でございまして、今後も引き続き医師会や歯科医師会、そして薬剤師会の皆様のご理解、ご協力を得ながら、また連携しながら取り組んでまいります。","voiceIndex":171,"id":"exchange-073"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"個々の医師、薬剤師の努力だけではなかなか話が進まないので、その辺は行政のほうでも何らかの処置とか、施策、対策を考えていただけるように、これは要望したいと思います。","respondent":"三ッ橋国保医療年金課長","answer":"こちらは高齢者の医療の確保に関する法律に基づいて生活習慣病の対策がございまして、東京都は糖尿病重症化腎症プログラムというものを策定をする予定です。その中で２回、今現在ワーキンググループで話し合いをしています。","voiceIndex":173,"id":"exchange-074"},{"speaker":"鈴木（博）委員","kind":"質問","question":"さまざまな施策を行うことによって、区民の健康レベルの改善と医療費の適正化について、今後もご努力をお願いして私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":175,"id":"exchange-075"},{"speaker":"あくつ委員","kind":"確認","question":"私からは５６ページ、児童措置費、区内私立保育園経費、国・都支出金返還金から、保育従事職員宿舎借り上げ支援事業、５９ページ、保健所等管理運営費追加分から、午前中もございましたが、簡易宿所について伺いたいと思います。保育士へのこの家賃助成、この５７ページの返還金に含まれているのかどうか、予算立てしてその分使い切らなかったので戻したのかということで、確認をしたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"都への返還金ですが、保育対策総合支援事業費補助金ということで、４８５万円の返金をしております。","voiceIndex":177,"id":"exchange-076"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それでお伺いをしたいのが、これはスキームとしては、私のほうで言ってしまいますけれども、４分の３が国・東京都、区が８分の１と。お伺いしたいのが、なぜこれが１００％の助成ではなくて８分の１、おそらく事業者にとってはそれほど大きくない金額だと思うのですけれども、そもそもなぜこの事業者負担を設定したのか教えてください。","respondent":"大澤待機児童対策担当課長","answer":"事業者負担分ですが、これはやはり民間の事業者ですので、その事業者の職員の処遇につきましては、一定のご負担を事業者にいただくという考え方があります。それによって事業者にも責任を持ってこの制度を活用していただくという趣旨もあります。","voiceIndex":179,"id":"exchange-077"},{"speaker":"あくつ委員","kind":"質問・要望","question":"例えば翻ってみるならば、わずかな８分の１の助成を惜しむような認可保育園、保育事業者。それと今、実際に伺いますけれども、これ、手を挙げていない事業者が果たしているのかどうか。それと最後、既存の保育事業者、新たな事業者もそうなのですけれども、既存の事業者に対しても、やはりこれは強制はできないにしろ、改めて徹底してもらう、周知をしていただきたいと思うのですが、いかがでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"新規に開設する事業者に対してですけれども、必ず宿舎借り上げの制度はご説明しています。品川区の場合はほかの区と比較しますと、制度を比較的緩やかに対応しているために、事業者からは保育士確保に大変有効な手段だと伺っております。","voiceIndex":181,"id":"exchange-078"},{"speaker":"あくつ委員","kind":"質問・要望","question":"次に簡易宿所の件で伺いたいと思います。こういう表記もあります。確認しますが、このホームページの記載のとおりなのかどうか。だとするならば、午前中、説明会の義務化というお話があったのですけれども、まずフロントの設置と管理者の常駐の義務化、こういうことが条例なのか、要綱なのかわかりませんが、そこについて検討が必要ではないかと思いますが、いかがでしょうか。","respondent":"井浦生活衛生課長","answer":"どこのサイトかよくわからないのですが、今、ご紹介ありましたけれども、そのようなことはございませんで、玄関帳場についての設置というのは原則義務化しています。例外的なものについては、国の省令での基準がありますので、それにのっとって厳格に指導しています。","voiceIndex":183,"id":"exchange-079"},{"speaker":"あくつ委員","kind":"質問・要望","question":"とすると、複数のホームページが虚偽の事項を記載しているということですので、これについては、品川区のほうで確認をしていただいて、「違いますよと。行政書士さん、これ違いますよ」ということで、行政書士の複数のページにそう書いてあるわけです。ぜひこれは注意をしていただきたいと思います。","respondent":"井浦生活衛生課長","answer":"そのようなご指摘をいただきましたので、どのようなサイトか確認しまして、きちんと法令に基づき、そして区の条例に基づいて指導しているというところについては説明してまいりたいと思ってあります。","voiceIndex":185,"id":"exchange-080"},{"speaker":"あくつ委員","kind":"質問・要望","question":"きちんと対応していただくということでございましたけれども、これ始まってからでは遅いのです。ですから、すぐに対応していただきたいと思いますので、どうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":187,"id":"exchange-081"},{"speaker":"いながわ委員","kind":"質問・要望","question":"７８ページの職員給与費、その辺についてお伺いをします。全体的に見ても、職員給与費追加分ということで、これはおそらく昨年の人事院勧告ですか、給与が多少増えたので、追加はわかります。総務費ですか、４８ページの総務管理費の中に、それぞれの項の中に給与費追加分、減額分ということはあるのですが、退職手当の追加分に関しては、これは総務費の中で管理をされているのか。","respondent":"黒田人事課長、矢木生活福祉課長、持田河川下水道課長","answer":"退職者数が１４７人ということで、来年度の採用見込みですが、今のところまだ採用者数確定しておりませんけれども、おおむね一般職員で１５０人弱。こちら一般的に国が４分の３、区が残りの４分の１を負担するというルールになってありますが、そのうち国が４分の３負担する部分につきまして。戸籍事務費の部分ですが、サービスコーナーを委託した関係で、再任用短時間職員につきまして減員しておりますので、その分で減額が発生しています。","voiceIndex":189,"id":"exchange-082"},{"speaker":"いながわ委員","kind":"提案","question":"特にすごく追加補正で増えてしまったわけではないので、それは安くあがったというと言い方はおかしいですけれども、しかしながらもっと地域の住民の方と区がお話をして、どうですか、つくりますからといったときに、こういう提案があります、それはちょっとやめてくれという話がおそらく、切り下げないでくれという話があれば、その流れでいくと思うので。","respondent":"持田河川下水道課長、鈴木建築課長","answer":"今言われたように、地元のほう、早目に絵を見せて、早目に意見をいただいてというところは必要なところだと考えていますので、今後設計を進めるにあたりましては、そのような形でしっかり検討していきたいと思ってあります。次年度送りにするにあたっても、前年度で設計を終わらせる等々対応して、できるだけお待ちいただかないような形で私道のほうの整備、今後も進めていきたいです。","voiceIndex":194,"id":"exchange-083"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"９０ページの国保会計と、１３０ページからの介護保険会計についてお伺いしたいと思います。この取り立ての問題についてお伺いをします。東京都の収納率向上にかかわる取組成績別交付算定表による平成２９年度に品川区に入る交付金の総額は幾らなのか、これは何年度分でいつごろ入るのかについてもお聞かせいただきたいと思います。総額だけで結構です。","respondent":"三ッ橋国保医療年金課長","answer":"それが新規口座の振替世帯率という東京都自身が算定するもので、そちらの部分、不明な部分がありますけれども、そのほかの部分につきましては要綱に沿って金額等が算定される予定です。","voiceIndex":199,"id":"exchange-084"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それからこの実地支援研修は希望する自治体だけということなのですけれども、何区ぐらいになったのかということも、もしわかったら教えていただきたいですし、また品川区がなぜ希望したかということも教えていただけたらと思います。そしてもう一つ、平成２９年６月１５日に滞納整理部門の職場研修、職場講師育成というものが行われていると思いますけれども、ここには品川区から参加しているのでしょうか。","respondent":"三ッ橋国保医療年金課長","answer":"こちら２３区全てなのかどうかは、参加しただけですのでそのあたりは不明です。２回目の研修ですけれども、こちらは実施されており、品川区としても２名参加しております。先ほどの整理係の者です。マニュアルです。","voiceIndex":201,"id":"exchange-085"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"このマニュアルについては、国のほうとしても作成について、東京都に対して各保険者において収納対策緊急プランの策定を行うように助言指導をお願いしたいということも、これは平成１７年くらいのときから出しているものですけれども、これにかわるものが何らかの形で品川区にはあるということなのでしょうか。","respondent":"三ッ橋国保医療年金課長","answer":"差し押さえの意味ということだと思いますが、こちらはやはり収納率の向上が一番大きいと思います。その中で、やはり国保と申しますのは自主納付が原則と考えております。","voiceIndex":203,"id":"exchange-086"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この件はさまざまなところでやりとりをしているので、私は改めて品川区がこの差し押さえのところも国税徴収法に基づいてというふうに言われておりますが、差し押さえ禁止財産も預貯金に入れば、それを継承しないということで、そこまで差し押さえるという方針でやっているのだということも先日の厚生委員会の中でも改めて確認されたところですけれども、この研修の中でも。","respondent":"寺嶋高齢者福祉課長","answer":"１点目の基金の取崩し額が当初の見込みよりも少なくて済んだという部分ですが、想定の範囲か否かということですけれども、この基金の取崩しにつきましては、最大限給付が発生した場合、それから保険料の歳入が少なかった場合を見越しての基金取崩し額を設定しておりますので。","voiceIndex":205,"id":"exchange-087"},{"speaker":"渡辺委員","kind":"質問","question":"４３ページ、公衆便所について伺います。トイレについては、公明党会派を中心に学校トイレ、ずっといろいろ聞いていてなるほどなと思うことと、そもそものところを考えながら質問させていただければと思います。それと２つ目が、学校トイレでもありました和式と洋式の比率、先ほど学校のほうが、直近ですが６６対３４の比率、公衆トイレに当てはめると、おおむねどのぐらいなのか教えてください。","respondent":"溝口公園課長","answer":"トイレのそれぞれの数です。公衆トイレにつきましては３６カ所、区内全体であります。公園、これは児童遊園も含めてになりますが、公園、児童遊園に設置されているトイレといたしましては、１２７個整備しているものです。","voiceIndex":208,"id":"exchange-088"},{"speaker":"渡辺委員","kind":"質問・要望","question":"洋式率３３％、確かにそうだなと思い浮かべればというところがあるかと思います。利用状況のところに行きます。これ今設置を聞いて、地域によっても、品川区も広いですからエリアによっても違うかと思います。ただ、私たちがよく耳にするのは、女性がトイレ行きたいといったときにも、やはり公衆トイレというよりは何か屋内の商業施設等を求めるケースがよく見受けられます。","respondent":"溝口公園課長","answer":"２５０メートルのメッシュを切ると、おおむねその範囲に必ずトイレがあるような形、これは大体５分ぐらい歩いていくとトイレがあるような形になっておりますので、おおむねそういった形で区内では充足していると考えているところです。利用状況です。","voiceIndex":210,"id":"exchange-089"},{"speaker":"渡辺委員","kind":"質問","question":"これも財政基盤等がかかわってくるのかなと。そういう意味で、次に、改修等があるときの方針を教えてください。クラブハウス等も改修をされている。そういう中で、改修の主な計画ですか、単年度なのか、複数年なのかも含めて教えてください。個別案件も含めてしまうのですが、ほかの清掃等の管理は抜群にいいと思うのですけれども、この辺がもったいないなという思いもあったので伺いたいと思います。","respondent":"溝口公園課長","answer":"順次今進めているところですが、今年度、来年度を含めて改修工事をして、全てクラブハウスの改修または増築、そういったものの工事が終わりますと、更衣室も含めてバリアフリー対応、またシャワーも車椅子の方がご利用いただけるようなシャワー室。","voiceIndex":212,"id":"exchange-090"},{"speaker":"渡辺委員","kind":"確認","question":"もうある程度既に考えられているのだなということを確認できて、何か晴れやかな気分といったら変ですが、見通しが立っていいかなと思います。そういう中で情報発信です。やはりトイレの場所等、これは住んでいる方もそうですし、長く住んでいる方しかり、あるいは観光という観点で人がいらっしゃる、そういう時代ですから、特に品川区はウエルカムという体制をとっている中で、どう知られていくか。","respondent":"溝口公園課長","answer":"先行しているところでいきますと、豊島区などは民間と協定を結んでトイレマップをつくって、その中で民間で使えるもの、また公共のもの、あわせて挙げている、そういった事例もうかがえますので、そういったものも含めて、どのような形で区民の方たちに情報提供していくのか。","voiceIndex":214,"id":"exchange-091"},{"speaker":"渡辺委員","kind":"確認","question":"もう１点、高齢者福祉の点では、やはり外出を習慣化する、これは力を入れられている施策なのですが、やはり町場の声の中で、当人もそうですし、付き添い、介護の方もやはりトイレの場所どこだろうと確認をされているケースが多いそうです。あるいは２０２０年、最後これはまとめのようになってしまいますが、やはりオリンピック・パラリンピックに力を入れている品川区としてバリアフリーを加速させる。","respondent":"柏原企画調整課長","answer":"２０２０年のオリンピック・パラリンピックに向けて、こういったところの事業というものは、我々としても加速させやすい時期だと考えていますので、そういった中でより施設のあり方とか、整備というものを、区全体として進めていきたいと考えています。","voiceIndex":216,"id":"exchange-092"},{"speaker":"塚本委員","kind":"質問","question":"私からは、５７ページの障害児施設給付費追加分、３,０００万円ちょっとですけれども、それについてお伺いしたいと思います。この増加分についての内容についてというところなのですが、あわせて、おそらくこの児童発達支援事業、または子ども発達相談室といったところにかかわる増だと思いますので、そちらの利用状況なども含めてご説明をお願いいたします。","respondent":"中山障害者福祉課長","answer":"こちらは児童発達支援ということで、未就学のお子様の療育の経費ということになっております。この間、区内にあります児童発達支援事業所の数も増えておりまして、現在１２カ所ということになっております。療育を求める保護者の方も多く、この間ずっと増加傾向にあります。","voiceIndex":219,"id":"exchange-093"},{"speaker":"塚本委員","kind":"質問","question":"区としてその辺の状況をどのように考えているのか、またその増えている原因というものはどういうところだと捉えているのかというところでお伺いをいたします。","respondent":"中山障害者福祉課長","answer":"その２カ月待ちという考え方が、インテイクといいまして、発達検査をとるまでの時間になっています。","voiceIndex":221,"id":"exchange-094"},{"speaker":"塚本委員","kind":"質問","question":"現在の仮移転先でのという体制から、しっかりとした体制になります。それから戸越ルームというものが、引き続きこういった療育の場としては使われるということで、これまでの議論もあったかと思いますが、こういった今後の施設展開と育英も含めて、この発達相談体制、具体的にどのような形になるのか、具体的な計画等も含めて、もし今の段階で考え等がございましたら、教えていただければと思います。","respondent":"中山障害者福祉課長","answer":"あそこの、今、戸越ルームの使い方、今後のニーズを考えたときに、療育の場としてが良いのか、それともやはり身近な地域で保護者の方にご相談に乗れる場としての活用が良いのか、この辺のことについては民間の療育の今後の動きも見ながら検討していきたいと考えております。","voiceIndex":223,"id":"exchange-095"},{"speaker":"塚本委員","kind":"質問・要望","question":"もしこの地域的なことについて何かありましたら、一言お願いしたいと思います。各保育園を訪れて、訪問や助言ということを実施するということですけれども、これが現在どのような形のものか教えていただきたい。どのような形で実施されているか、訪問の回数とか、助言の内容とか、教えていただきたいと思います。","respondent":"中山障害者福祉課長","answer":"国のほうもすごくこの支援については大事な支援ということで、次期の障害児福祉計画の中でも保育所等訪問支援を進めるようにということで強く言っておりますので、また保育園ですとか、学校ですとか、説明してご協力いただきながら。","voiceIndex":225,"id":"exchange-096"},{"speaker":"塚本委員","kind":"意見","question":"この事業ですけれども、大切だと考えていますが、特にこのところ保育園、大変増えておりますので、これからも増えていくでしょうし、そういう意味ではしっかりとこの事業が漏れなくというか、つつがなくというか、できるようにこれからもいろいろとご配慮いただければと思いますが、最後に一言お願いいたします。","respondent":"中山障害者福祉課長","answer":"さまざまな施設と連携をして周知を図っていきたいと考えています。","voiceIndex":227,"id":"exchange-097"},{"speaker":"西本委員","kind":"質問・要望","question":"３月１１日で、東日本大震災から今年で７年が過ぎようとしております。ですからページ数は不明です。お聞きします。実態を教えていただきたいのですが、区有施設においての非常用発電機は、所管ごとでお願いしたいのですけれども、何機あって、管理がどのような状態になっているでしょうか。全体の掌握がされているのか、どこがそれを集計しているのかをお聞きしたいと思います。","respondent":"小林施設整備課長","answer":"非常用発電機のご質問ですけれども、区有施設の中には３１施設に非常用の自家発電機が設置されております。それで、今ご質問の負荷運転等については、消防用設備等点検報告というものが年に一度、消防機関のほうに報告の義務がありますので、各所管が実施しています。","voiceIndex":230,"id":"exchange-098"},{"speaker":"西本委員","kind":"質問","question":"３１施設にあるというのはわかりました。では、この法定負荷試験というのはどういうことでしょうか。それが本当になされているのか。そこはいかがですか。","respondent":"小林施設整備課長","answer":"その際、消防機関のほうからは指導がないと聞いております。しかしながら、必要なものについて今後消防機関と協議をして、実施していくものについては実施していくということで努めてまいりたいと思います。","voiceIndex":232,"id":"exchange-099"},{"speaker":"西本委員","kind":"質問","question":"この法定負荷試験、課長がおっしゃいました３０％負荷をかけて試運転をするということなのですが、電源を入れてついたからきちんと稼働ができているということではないのです、この負荷試験というのは。３０％の負荷をかけてチェックをしなければならないのです。ということは、今３１施設のこの発電機に対して、何ら法定的な規定に基づいたチェックがなされていないということではないでしょうか。","respondent":"小林施設整備課長","answer":"先ほどもご答弁いたしましたが、今後必要なものについては実施をしていくということで努めていきたいと考えています。消防機関とも協議をして、行っていきたいと思います。","voiceIndex":234,"id":"exchange-100"},{"speaker":"西本委員","kind":"質問","question":"この消防法でいいますと、担当者に対しては３０万円以下の罰金または拘留です。こういう実態を各所管の方々も知っているのかどうなのか、まず１点お聞きしたいと思います。そうなりますと、当然ながら消防署だけではなくて公的な機関、または民間ですと病院等々も含めて、このチェックをしなければならないということが、かなり追及されてくるのではないかと思いますが、その現状はご存知でしょうか。","respondent":"小林施設整備課長","answer":"その辺の動きも注視して、必要なものについては実施していくように努めてまいりたいと思います。","voiceIndex":236,"id":"exchange-101"},{"speaker":"西本委員","kind":"質問・要望","question":"必要なのではないのですか。これ、非常用発電機がなぜ必要かというと、災害があったときの非常用のものだからです。やらないといけないことなのです。全庁あわせての情報共有も、各所管に任せるということではなくて、例えば危機管理室があるわけですから、そこで全体を掌握するとか、全体を管理していくという仕組みも必要になるのではないかと思いますが、その体制についてもお答えいただきたいと思います。","respondent":"小林施設整備課長","answer":"そのような状況の把握はしております。それとあと各主管課については、今消防機関と協議をして、必要に応じたものを委託内容に盛り込むとか、そういうものをこちらのほうから指導していきたいと考えています。","voiceIndex":238,"id":"exchange-102"},{"speaker":"西本委員","kind":"質問・要望","question":"これは早急に対応していただきたい。本来は仙台市であるとか、福岡市のことの情報が入っているのであれば、早急に品川区としても取り組むべき課題ではないかなと思うのです。その理由で不具合が生じて、そこから災害が発生するということも起きておりますので、ぜひこれは早急に品川区全体として考えて進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":240,"id":"exchange-103"},{"speaker":"木村委員","kind":"質問","question":"お聞きいたします。しかし、計画がスタートしたからには、１００％を目指すお考えがなければなりません。その中で、この事業で４つの減額、３億６,１８４万円ですけれども、中でも旧同潤会地区の防災街区整備事業２億４,４６４万円が大きいわけでありますが、減額の理由は計画に無理があっての減額か、それともほかに何かあるのか、お聞きしたいと思います。","respondent":"高梨木密整備推進課長","answer":"こちらの減額の理由ですが、工事進捗による減となっております。具体的な工事進捗のおくれについてですが、基礎工事実施中に地中に障害物が発生したことによる出来高の減となっております。","voiceIndex":242,"id":"exchange-104"},{"speaker":"木村委員","kind":"質問","question":"お聞きいたしますけれども、もし本区で阪神・淡路大震災や糸魚川市のような地震・火災が起きた場合、被害を最小限に食いとめるには常日頃から何を準備しておけばいいのか、また、区民に日頃からどのような心構えや準備をしていただくのか、行政側からのお考えというものをお聞かせください。","respondent":"高梨木密整備推進課長","answer":"木密地域を多く抱える品川区におきましては、そういった被害を最小限に食いとめるために、今ある燃えやすい建物を火災に強い建物に一刻も早く変えていただくべく、今後も重点的に取組みを進めていきたいと考えております。","voiceIndex":244,"id":"exchange-105"},{"speaker":"木村委員","kind":"質問","question":"お聞きいたしますけれども、不燃化１０年プロジェクトはこれから３０年以内に起きると言われている、この大震災だけではなく、あらゆることを想定した災害に対し、しっかりとした計画のもと事業を進めることが、３９万人にも及ぶこの区民全員の願いだと私は思っています。ぜひとも行政として、都民の１人としてのお考えというものも、もう一度しっかりとお聞かせをください。","respondent":"高梨木密整備推進課長","answer":"いろいろと建替えが進まない事情等あると思いますが、改めてこの時限的な助成制度があるということをしっかりと区民の皆様に説明し、理解していただいた上でご協力いただける方を１人でも多くいただいて、燃え広がらない、燃えないまちの実現に向けて。","voiceIndex":246,"id":"exchange-106"},{"speaker":"木村委員","kind":"意見","question":"ぜひお願いをいたします。本区においても、中延や旗の台、そして豊町、西品川、大井ほか、補助２８号・２９号線、放射２号線沿道地区など、この区内１４地区において計画が今進んでいることと思いますけれども、２０２０年ごろを完成目途にしているのでしょうが、それともまたいろいろな事情により延びるような可能性もあるのかどうかということをお聞かせください。","respondent":"高梨木密整備推進課長","answer":"しかし、品川区内を燃えない、燃え広がらない、安全なまちにしていくという使命はなくならないと考えておりますが、まずは期限末である平成３２年度末を目標年次と定めて、それまでに精一杯取組みを進める必要がある、このように考えているところです。","voiceIndex":248,"id":"exchange-107"},{"speaker":"木村委員","kind":"意見","question":"１９２３年９月１日に発生した関東大震災では、マグニチュード７.９で、その後、翌日にかけてもマグニチュード７以上の余震が７回も起き、激しい揺れによる建物の倒壊や大火災による被害というもののほかにも、津波や山崩れによる被害も甚大でした。行政として、都民の１人としても、そのしっかりとした計画、またお考えをお聞かせください。","respondent":"高梨木密整備推進課長","answer":"は火災に強いまちが区民一人ひとりの生命と、それぞれの財産を守るということが第一義だと考えておりますので、引き続き強力に推し進めていきたいと考えております。","voiceIndex":250,"id":"exchange-108"},{"speaker":"木村委員","kind":"質問","question":"２０１０年４月に東京都が公表した被害想定では、広範囲に存在する木造密集地域市街地を中心に、大規模な火災延焼が起き、東京都内だけでも最大約２０万棟が焼失、火災による死者は４,０００人以上に上るとも言われています。お聞きいたしますけれども、本区でも複数箇所から出火することが予想されていますが、一斉に発生した場合、消防車や救急車の台数というものは今のままで十分と言えるのでしょうか。","respondent":"高梨木密整備推進課長","answer":"消防車等の台数については、また後ほどお答えがあろうかと思いますけれども、まず委員ご指摘のとおり、東京の被害想定では品川区の死者のうち火災の死者数が多くの想定されているところで、消防車の台数等も含めて、総合的な防災対策が必要になってくると。","voiceIndex":252,"id":"exchange-109"},{"speaker":"鈴木（真）委員","kind":"質問","question":"これが増額になっていますけれども、１,８００万円余、その増額の理由を教えてください。これはマイスクールは私も地域の方から足りないということで、八潮だけあって足りなかったときに、増やしてほしいというお声を聞きまして、それで五反田のマイスクールができたという状況がありました。この補助金が、当初予算に入っていなかった中で、補助金が入ってきた理由について教えてください。","respondent":"高山子ども育成課長、中山障害者福祉課長、大関教育総合支援センター長","answer":"こちらのほう、子ども・子育て支援交付金のほうの増額の理由ですが、年度当初、想定していたより補助の基準額が引き上げられたことと、そしてもう１点。この自立支援サービス追加分の中の特徴的なものというご質問です。全都的に各区市で適応指導教室を増設する際に、人的な補助を行うという制度が入りましたので、そちらのほうに応募いたしまして、認めていただいた結果。","voiceIndex":256,"id":"exchange-110"},{"speaker":"鈴木（真）委員","kind":"確認","question":"何かこれ特別の理由があってなのか。細かいところを見ていくと、事項別を見ると出てくるのだろうと思うのですけれども、この中で対応する部分が出てくるのが普通ではないかという点で、その確認をします。実際にやっていただけるのですから、それは十分いいことだと思っているのですけれども、当初予算でももう少しつけてもいいのかなという感じもするので、その辺はいかがでしょうか。","respondent":"秋山財政課長、中山障害者福祉課長、大関教育総合支援センター長","answer":"予算書上の財源更正の表記の仕方なのですけれども、歳入で財源更正があっても、歳出のほうで、例えば３目の児童福祉施設費のほうで。金子山を１０人の男性にすることに伴いまして、グループホーム森前、同じく福栄会が運営しているのですが。新たにマイスクールの機能を浜川中学校の一部を活用いたしまして、次年度より適応指導教室を増やすという件についてですが、ご指摘いただきましたとおり。","voiceIndex":260,"id":"exchange-111"},{"speaker":"浅野委員","kind":"質問","question":"私のほうからは、５９ページの予防接種費追加分、定期予防接種、６３ページの立会川緑道概略設計委託、時間があれば１０６ページの特定健康診査等事業費について質問します。その後、特に問題になるようなことはあったのか、なかったのか。決して起こしてはならない事故だと思いますけれども、今後とも注意を怠らないようにしていただければと思いますが、いかがでしょうか。","respondent":"舟木保健予防課長","answer":"事故対応のほうにつきましては、１０月末までを再接種の期間として実施いたしまして、そちらのほうの再接種については、特に大きな健康被害はなく終了しております。現在、最終的な報告のほうを区内に限らず、区外で受けた方の報告を待っているような状況です。","voiceIndex":265,"id":"exchange-112"},{"speaker":"浅野委員","kind":"質問・要望","question":"２点目といたしまして、立会川緑道概略設計委託の件ですけれども、緑道の改修ですが、３０年も経過をしているということで、今後進めていくという話を伺いました。この件につきまして、今回設計委託という形が出ておりますけれども、今後のタイムスケジュールというのでしょうか、計画の進め方などについて概略を教えていただきたい、よろしくお願いします。","respondent":"多並道路課長","answer":"ここの整備のあり方につきましては、今後、今年度概略設計ということを行っておりますけれども、今回の説明会の内容を踏まえまして、来年度詳細設計を進めながら、再来年度から順次工事計画を進めていきたいと思っておるところです。","voiceIndex":267,"id":"exchange-113"},{"speaker":"浅野委員","kind":"質問・要望","question":"このような場所であるからして、今回の計画が発表されたわけですので、どうか地域の住民の方にどのような形でこの計画を理解していただくといいましょうか、概要だけでも知っていただいて、それである意味協力も求められるということも考えられます。私もよく通るところです。大体完成する時期ですか、どのぐらいの期間、いつごろになるのか教えていただければと思います。","respondent":"多並道路課長","answer":"立会川緑道につきましては、来年度詳細設計を行い、そのときに、今委員のお話ありましたように、地域の方に個別にお話ししながら、整備のあり方についていろいろお話聞きながら、整備を進めていきたいと考えています。","voiceIndex":269,"id":"exchange-114"},{"speaker":"浅野委員","kind":"質問","question":"特定健康診査等事業費についてですけれども、他の委員からも質問もありましたが、特定健康診査等事業費、こちらが１１％減額補正となっているということで、この件につきまして、今後はぜひとも増額補正になるように取り組んでいただければなと、そのように考えているところですけれども、こちらの特定健診、なかなか率が上がらないということで苦慮されていると思いますが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":271,"id":"exchange-115"},{"speaker":"のだて委員","kind":"質問","question":"私からは、６９ページの不燃化１０年プロジェクトに関連して、戸越公園駅再開発と、また同じく６９ページの住宅・建築物耐震化支援事業について質問します。は戸越公園駅、戸越五丁目１９番地区の再開発についてです。再開発地域も不燃化特区の中にありますけれども、この１９番地区再開発を防災のためと説明しますが、どこが防災のためになるのか、まず伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"戸越公園駅の南側です戸越５丁目１９番地区の再開発事業についてです。こちら、防災のためということで進めているだけではございません。","voiceIndex":273,"id":"exchange-116"},{"speaker":"のだて委員","kind":"質問","question":"防災のためだけではないというご説明でしたけれども、どこが防災のためになるのかということを伺いましたので、ご答弁お願いします。","respondent":"東野まちづくり立体化担当課長","answer":"防災というところに特化してお答えしたいと思います。この戸越五丁目１９番地区にあります建物、１３棟あります。この中で旧耐震以前の建物が８棟ある、木造住宅も入れまして８棟あるという状況です。","voiceIndex":275,"id":"exchange-117"},{"speaker":"のだて委員","kind":"質問","question":"長期間の避難生活では備蓄がやはりある程度の期間しかできないと思いますので、避難所に支給を受け取りに行くたびに２４階まで上り下りをしなくてはいけないと、そのようなことはできるはずがないわけで、結局避難所生活になるということになりますけれども、やはりこの超高層でなくて、別の耐震化であれば、方法があると思います。この超高層のどこが防災になるのか、改めて伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"この戸越五丁目１９番地区につきましては、商業的なところの配置、そういったものも含めまして、必要な施設だと考えています。新たな居住空間の確保、こういったところから一定程度の高さは必要だと考えています。","voiceIndex":277,"id":"exchange-118"},{"speaker":"のだて委員","kind":"質問","question":"課題解決のため、あと商業的にも、そして住戸確保のためにもやっているというお話でしたが、商業的にということであれば、別に超高層にしなくても、商業的には沿道に商店を設けることもできると思います。この地図で見ますと、１９番地区のところはどの建物も接道していて、再開発でなくても建替えできると考えられるわけですけれども、再開発でないと建替えできないということなのか伺います。","respondent":"東野まちづくり立体化担当課長","answer":"建替えに関しましては、再開発でなくても建替えは可能です。ただ、こちらのお住まいの方々がみずから企画いたしまして、そういう再開発の手法によるまちづくりを望んでいる、それを区としては支援していくものです。","voiceIndex":279,"id":"exchange-119"},{"speaker":"のだて委員","kind":"質問","question":"地域の方が望んでいるというお話でしたけれども、この地域の中で情報発信として行われた事業者の説明会があったのですが、そこでは再開発以外の共同化ですとか、あと単独での事業の説明もありました。なぜ再開発になったのか、防災のためなのか、伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"その中には共同化による方法、それ以外の、いわゆる一般的な建替えによる方法、そういったものについても皆さんで考えた末の結果としまして、再開発事業の手法を用いたものが自分たちのまちづくりに一番ふさわしいのではないかという考え方から。","voiceIndex":281,"id":"exchange-120"},{"speaker":"のだて委員","kind":"質問","question":"超高層が防災にもなるというお話もありますけれども、この超高層とほかのもので、先ほどご紹介しました共同化ですとか、単独事業、こういったところと耐震性というのは違いがあるということなのか伺いたいと思います。","respondent":"東野まちづくり立体化担当課長","answer":"超高層の建物とほかの建物につきましては、耐震性というところでは耐火基準を満たしているものであれば、何ら変わりはないと思います。","voiceIndex":283,"id":"exchange-121"},{"speaker":"のだて委員","kind":"質問","question":"やはり超高層によって別のリスクを生み出すということにもなってきますし、今の商店街がやはり商店の方も顔を合わせてコミュニケーションを取ることができる、こういったまちづくりがいいのだということで、この防災の面から見ても、超高層ではなくて低層、そして戸建への支援で防災に強いまちづくりを進めていくべきだと思います。この目標が未達成になっていますが、これでよいと考えているのか伺います。","respondent":"鈴木建築課長","answer":"ただ、目標に対しては非常にまだ、９５％ですので、これからもしっかり耐震事業、支援事業を充実し、あるいはＰＲしながら耐震化を図っていきたいです。","voiceIndex":285,"id":"exchange-122"},{"speaker":"のだて委員","kind":"質問","question":"ただいま８８.４％までいっているというお話でしたが、一応目標までには達していないということですけれども、以前の速報値は７３.５％だったと思うのですが、これはなぜこんなに急に上がったのか伺いたいと思います。","respondent":"鈴木建築課長","answer":"先ほどご紹介しました８８.４％につきましては戸数ベース、これは先ほどもご紹介しましたように、東京都ならびに国がこの戸数ベース、より現実、世帯ベースに近い数字として採用してございまして、今その形で速報値のほうを算出しているというものです。","voiceIndex":287,"id":"exchange-123"},{"speaker":"のだて委員","kind":"質問","question":"今、戸数ベースでやっていることで８８.４％ということでしたけれども、マンションですとやはりもう数百戸という建物の戸数になるわけです。そうすると、やはり棟で考えたほうが、１棟、２棟で考えたほうが、この耐震化というものが実態に合ってできると思うのですけれども、そういったお考えは今後検討されるのか伺いたいと思います。","respondent":"鈴木建築課長","answer":"それぞれ木造の戸建住宅についても、充実した耐震化支援を今後も進めていきたいというものです。","voiceIndex":289,"id":"exchange-124"},{"speaker":"のだて委員","kind":"質問","question":"これは住宅の耐震化をすることによって、大震災のときの人命を守るということですとか、救助の際に道を塞ぐことがないようにするということが、やはり重要だと思いますけれども、今木造住宅についてどうなっているのか伺います。","respondent":"鈴木建築課長","answer":"当然ながら区全体の住宅は９５％を目指していくわけですけれども、それぞれ戸建、マンション、非木造、耐震化率を上げるべく、特に今年度からはアクションプログラムを木密地域内で開始しておりまして、特に戸建住宅についても耐震化を充実していきたいです。","voiceIndex":291,"id":"exchange-125"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひやっていただきたいのですけれども、来年度東京都の耐震改修の診断設計工事に補助が計画されております。一般質問でもお伺いしましたけれども、この区も既に補助を行っていると思います。あわせて、高齢化でなかなか建替えできないという方もいらっしゃいますけれども、そういった方にも個別に対応をしっかりとやっていっていただきたいと思いますが、いかがでしょうか。","respondent":"鈴木建築課長","answer":"来年度から東京都が全域でですが、既に区では平成１９年度から診断、設計、改修工事、全てにおいて全域で充実して、１５０万円、３００万円で助成を行っております。今後も進めていきたいです。","voiceIndex":293,"id":"exchange-126"},{"speaker":"本多委員","kind":"質問・要望","question":"４８ページから、各項別、各目別で、それぞれ職員給与費が出ております。追加分があったり、更正減額があったり、午前と午後の質疑を踏まえまして、聞かせていただきたいと思います。全体的にこの平成２９年度の最終補正としまして、特色については先ほどのやりとりで、退職者の見込みが１０２人から１４７人だった、これも特色だと思うのですが、ほかに何か特色があれば教えてください。","respondent":"黒田人事課長","answer":"７８ページの、いわゆる給与費明細から申し上げますと、今回の補正では退職手当を除くと、人数としましては３５人増えておるのですが、金額としましては９,７５０万円ほど減額となっておりますので。","voiceIndex":296,"id":"exchange-127"},{"speaker":"本多委員","kind":"質問・要望","question":"全体について聞かせていただきました。今度は個別にちょっと聞かせていただきたいと思います。７３ページの小学校・中学校の教職員ですね。両方とも減になっておりますけれども、平成２９年９月から区内公立学校において、定時退勤日を設定したということなのですが、そういったこととの関連性について何かあれば教えてください。","respondent":"黒田人事課長、品川庶務課長","answer":"職員費の減につきましては、用務職を退職不補充としている関係で、人件費が減となっているというものです。例えば広報紙等に学校の勤務時間は何時から何時までだよというような形で、教員の正規の勤務時間を区民の皆様にもはっきりと示していくというような方向で、今こういった取組みを進めているようなところです。","voiceIndex":298,"id":"exchange-128"},{"speaker":"本多委員","kind":"質問","question":"ちょっと次の質問に行きますが、６１ページの清掃総務費の職員給与費につきまして、今定例会で専決処分の報告がありましたけれども、清掃作業中に、クリーニングに出すタオルを誤って収集してしまったという、一生懸命やっていればこういうこともあると思って、本当に普段の作業には感謝しております。それと平成２９年度、平成２９年４月から回収した小型家電、「都市鉱山からつくる！解析をすると。","respondent":"工藤品川区清掃事務所長","answer":"収集職員との関係という部分につきましては、こちらのほうは拠点回収でやっておるですので、私どもの収集の部分とは、別の部分で業務をやっておりまして、拠点回収、シルバー人材センターのほうにお願いしているです。特に影響という部分は見受けられないと考えておるところです。","voiceIndex":301,"id":"exchange-129"},{"speaker":"本多委員","kind":"意見","question":"最後に１点聞かせてください。先ほど質疑のやりとりで、行政サービスコーナーの人件費が直営事業の委託化、民間活力によってコスト削減という答弁がありました。この直営の事業を民間活力でという、この考え方についてお聞かせください。","respondent":"柏原企画調整課長","answer":"それは仕事の中身、それからどのようにサービスを提供するかというものによりますけれども、民にできるものは民という考え方のもとで直営の事業、それから委託できる事業というものは、区分けをしながら行っていくというものです。","voiceIndex":303,"id":"exchange-130"},{"speaker":"松永委員","kind":"質問","question":"私からは３９ページ、国庫補助金、防災生活圏促進事業、そして同じページの避難道路機能強化事業、そして同じ事業名ですが、４３ページの防災生活圏促進事業、避難道路機能強化事業で、また同じ内容ですけれども、６９ページの防災生活圏促進事業、それぞれ伺いたいと思います。","respondent":"高梨木密整備推進課長","answer":"具体的に言いますと、林試の森公園周辺では、かむろ坂付近から林試の森公園東門に至る富士見通りと呼ばれる道路の拡幅整備を行っておりまして、それと戸越公園につきましては、大原通りの東急大井町線から四間通りの間の６メートルへの拡幅整備。","voiceIndex":306,"id":"exchange-131"},{"speaker":"松永委員","kind":"確認","question":"この補正予算の内容、今確認させていただきました。その減になってしまった理由、それぞれどのような形でこうなってしまったのか、理由について教えてください。","respondent":"高梨木密整備推進課長","answer":"しかしながら、沿道の皆様と用地取得に係る交渉をする際に、用地をいただく交渉が未了で終わったため、今年度につきましては記載のとおりの金額を減額すると、このような理由です。","voiceIndex":308,"id":"exchange-132"},{"speaker":"松永委員","kind":"質問","question":"そこで、これ測量等の委託減というのは、その内容ですか。道路の変更というか、道路以外にも、例えば用地を取得して公園にしたりとか、いろいろさまざまな形になるのかなとは思うのですけれども、そういった計画が変わってしまっているのか、ちょっとその辺がわからないので、この測量等委託というものが変わってしまうとどうなってしまうのかなと思って、その辺について伺いたいと思います。","respondent":"高梨木密整備推進課長","answer":"この内容についてなのですが、ただその用地の測量をするだけではなく、当然用地をお譲りいただく際に一体どのぐらいの面積があるのかといったところを確定するために、現地の測量をするというような委託も当然行いますけれども。","voiceIndex":310,"id":"exchange-133"},{"speaker":"松永委員","kind":"質問・要望","question":"さまざまあるということなのですけれども、今後についてなのですが、今こうした国、都、そして区が行っている事業の中で、現状今整備というものはどれくらい進んでいるのか、全体的に何％ぐらいでもいいので、完了しているのか教えていただきたいと思います。例えば雑草が生えてしまったりとか、その環境がどうなっているのか、最後にそれについても伺いたいと思います。","respondent":"高梨木密整備推進課長","answer":"最初に道路拡幅の進捗率についてお答えをいたします。林試の森公園周辺で行われている地区防災道路と呼ばれる富士見通りの拡幅整備なのですが、こちらにつきましては約３６％の進捗率となっております。","voiceIndex":312,"id":"exchange-134"},{"speaker":"松永委員","kind":"質問","question":"実はそうした用地に関してなのですけれども、ずっとそのままほったらかしにするのはもったいないので、何かほかにできないかなとか、例えばそういう場所は、ちょっと暗いのです。周りが。最後ですけれども、この目標について、大体いつごろ、このパーセンテージを見るとなかなか進まないかなとは思うのですが、もしその目標がありましたら教えてください。","respondent":"高梨木密整備推進課長","answer":"区といたしましては、事業についての普及啓発活動を活発化させて、１日も早く整備が進むように、できるだけ道路にならないで遊ぶような土地がなくなるようにということで努めてまいりたいと思います。","voiceIndex":314,"id":"exchange-135"},{"speaker":"高橋（し）委員","kind":"質問","question":"４６ページの歳入で繰越金について、それから５６ページの児童福祉施設費の職員給与費、これはほかの委員からもいろいろ質問があったと思いますが伺います。そしてここで補正をしているということです。先ほども簡単にあったのですが、もう一度見込額を４４億云々というふうに出した計算、算定の根拠と、補正においてこの繰越金についての考え方をお尋ねします。","respondent":"秋山財政課長","answer":"歳入と歳出の差額というもので、これは昨年の秋の決算特別委員会において認定いただきました実質収支４４億８,７５５万７,０００円が９月に確定いたしまして、今回平成２９年度予算で平成２９年度に繰り越す額がこちらの４４億８,７５５万７,０００円に確定いたしましたので。","voiceIndex":317,"id":"exchange-136"},{"speaker":"高橋（し）委員","kind":"質問","question":"今お話あったように実質収支の額ということです。これはちょっと平成２７年のものなのですけれども、渋谷区が５.９％、文京区は５.３％と非常に比率が高い。２３区平均だと３.２％で、品川区は中位よりもちょっと下というところなのですが、その数字と、品川区としてのこの繰越金のメッセージについてはどのようにお考えでしょうか。","respondent":"秋山財政課長","answer":"歳入と歳出の差額という実質収支という考え方が、実質収支比率という中で評価をされているというところもありますし、実質収支比率自体がそもそも地方交付税のないところで、２３区の状態でどうかという議論もありますけれども、そういう評価の中で実質収支を入れておりますので。","voiceIndex":319,"id":"exchange-137"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"これは要望します。ここで繰入金の補正額がないということは、そのまま平成２９年度当初予算で８０億円の基金繰入金を組んでいるのですけれども、それをそのまま全部歳入のほうに入れるというふうに、補正予算に繰入金が入っていないところを見ると、そのように考えてもよろしいのでしょうか。","respondent":"秋山財政課長","answer":"基金繰入金に関しましては当初予算で立てたものを、今回補正をしていないので、その額で繰り入れをしていくという予定でいるです。","voiceIndex":321,"id":"exchange-138"},{"speaker":"高橋（し）委員","kind":"確認","question":"それで、これまでの平成２６年から平成２８年までは、一応補正で数字を出していますけれども、それ以上の形で繰り入れをしないで済んでいるというところがあるのですが、今年度はここでゼロということは、もう１回お話になるのですけれども、補正等で最終処理をするのではなくて、今お話あった当初予算の８０億円をそのまま歳入のほうに繰り入れるというふうなことで確認ですがよろしいでしょうか。","respondent":"秋山財政課長","answer":"最終補正とはいえ予算ですので、実際に出納閉鎖後の決算のときにどうなっているかというのは、ここで補正をしないということはあまり動くことはないだろうという予測はしておりますけれども、８０億円を必ず繰り入れるかということには、あくまでも予算ですので。","voiceIndex":323,"id":"exchange-139"},{"speaker":"高橋（し）委員","kind":"質問","question":"昨年も一昨年も１０億円の補正をしている、それぐらい動くだろうという感じがあったのでしょうけれども、今年はそれだけ動かないだろうというようなお考えは、どのようなところから出てくるのでしょうか。平成２６年度でも４億円ぐらいの補正をしているということですので、そのあたりが全くないというところが非常に、これまでの数字から見て非常に目立ったところがあるので、お尋ねしています。","respondent":"秋山財政課長","answer":"こちら最終補正の考え方ですけれども、考え方というか、繰入金の考え方ですが、歳出に連動してそこの財源が出てきたとかいうことがあって、平成２７年、平成２８年については減額をしておりますが、そういう意味では今回はそういう影響が出ていないので。","voiceIndex":325,"id":"exchange-140"},{"speaker":"高橋（し）委員","kind":"質問","question":"先ほどの職員給与費のところは、保育士のお話がいろいろ出ていましたが、平成２８年度は２億５,０００万円余の減額があって、今年度は７,０００万円ぐらいなのですが、先ほど若い年齢の方が多かったという話があったのですけれども、昨年はちょっと予算書の書き方が違う可能性もあるのですが、ほかの事業も含んで２億円の減額だったのでしょうか。","respondent":"黒田人事課長","answer":"昨年度の予算書の書き方につきましては、現在ちょっと手元に資料がなく承知しておりませんが、今年度の保育園の職員につきましては、７１２人から７２８人に増えておりますので、人件費相当分が減っているということでは、若い職員を採用しておりますので。","voiceIndex":327,"id":"exchange-141"},{"speaker":"高橋（し）委員","kind":"質問","question":"時間のほうがないので、質問のほうがはっきりいろいろお尋ねできなくて申しわけありませんでした。保育士の退職や、あるいは採用についてはまた別の機会にお伺いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":329,"id":"exchange-142"},{"speaker":"若林委員","kind":"提案","question":"やはりこういう発達支援をする場合には、当然早期発見、早期の療育ということがずっと指摘をされている中で、こういう小さいお子さんの２カ月待ちというのが果たして、ある意味で障害児と、障害となったわけではありませんけれども、合理的配慮云々の話にかかわってくる事項なのかなという心配もありますので、改めてなぜ今この状態が続いているのかということを１つお聞きして、では平成３１年の。","respondent":"黒田人事課長、中山障害者福祉課長","answer":"非常勤職員につきましては、現在の非常勤は専門非常勤と申しまして、いわゆる区の職員よりもやや専門性が高い仕事の部分で非常勤になっていただいたりとか、保育園ですと保育補助という形で。これを受けるための待機時間というものがかかっているところなのですが、その手前のご相談を受けながら、必要に応じてこの発達検査まで持っていく、そうしたこともしていくことで、なるべく初回の相談を早目に受けて。","voiceIndex":331,"id":"exchange-143"},{"speaker":"若林委員","kind":"質問・要望","question":"障害、発達支援のほうについては、まさに現場の知恵、創意工夫でいろいろな皆さんのチームワークでできることがあられるのだろうなと今の答弁を聞きながら思いましたので、物理的な部分、またそういうインテイクをする側の職員の部分、人数が多ければ早くできるでしょうと、当初そういうものもありましたけれども、そういうものでは決してないのだということで確認をさせていただいて。","respondent":"飛田障害者施策推進担当課長","answer":"それよりまた、今後さらに強化していくということで、連携のほうを進めて、さらにまた新施設が立ち上がります。それに向けて一致団結して進めていきたいと考えております。","voiceIndex":334,"id":"exchange-144"},{"speaker":"若林委員","kind":"質問・要望","question":"連携、当然大事だと思うのですけれども、私も代表質問でやりましたが、障害児、障害者の部門にやはり連携ではなくて保健職、専門職がいるということで、この計画も、本来はこの計画自体にも参画していただきたいなという思いがあったのですけれども、そこについて一言お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":336,"id":"exchange-145"},{"speaker":"伊藤委員","kind":"確認","question":"私は３４ページの普通交付金等に関連をして、それから３７ページ、区内私立保育園経費に関連して質問します。先に普通交付金等でありますけれども、これはずっと議論のありました平成２９年度の補正予算、普通交付金が５億円の増、それから繰越金が１７億５,６００万円余の増等々、大体トータルで約４２億円ぐらいの増の結果が出ていると確認しました。ただ数字だけ出てきている。答弁をお願いいたします。","respondent":"秋山財政課長","answer":"個々のものを足し引きをしまして、いわゆる当初の予定よりも減額の補正が幾らぐらい、増額の補正が幾らぐらいというご説明はできるのかなと思ってあります。","voiceIndex":338,"id":"exchange-146"},{"speaker":"伊藤委員","kind":"質問","question":"つまり、行政の見える化といったらいいのでしょうか。プラスマイナスがわかりにくい感じがするのです。ですからこういう数字の内容も、それから議会にｉＰａｄは入りましたけれども、ここに具体的に非常にわかりやすい資料が出てきたわけです。だから、すぐにはもちろんできないと思ってはいるのだけれども、このＩＣＴ化のことについては、品川区の考え方だけをここでお聞かせください。お願いいたします。","respondent":"秋山財政課長","answer":"そういうものも含めて、膨大な量をどうやってお見せするかというようなことも課題としてはあるかと思いますけれども、その辺も含めて、何らか見え方といいますか、説明責任という言葉もありますので、そういうところも含めて。","voiceIndex":340,"id":"exchange-147"},{"speaker":"伊藤委員","kind":"確認","question":"これはいろいろと確認しましたけれども、今年の補正予算、保育園は合計で約８３億円の予算が補正されています。これはもちろん今の待機児童対策でさまざまな事業を展開されていらっしゃるから正しいことではあるのだけれども、補正だけでこの金額ですから、このほかに通常経費を考えたら結構な金額を保育園に投入していることがわかります。結果として保育士の希望は非常に多い。お願いいたします。","respondent":"佐藤保育課長","answer":"私立幼稚園関係の幼稚園教諭等の処遇改善確保の関係のご質問だと思います。品川区といたしましては、これまでも私立幼稚園が幼児教育の主たる施設として、区立幼稚園は補完の立場というところで対応してきたところです。","voiceIndex":342,"id":"exchange-148"},{"speaker":"伊藤委員","kind":"質問","question":"それは当然なことではあるのです。もちろん繰り返しますけれども、園数も違うし、目的も違う。ご承知のように。でも幼稚園教諭というのは教諭ですから、１０年に一度その免許の更新が必要だということも聞きました。それはもちろん法的な体制もあって、それから所管の官庁も違うから、一概にすぐこの場でどうこうと言えない部分はあるのだけれども、だけれどもやはり私立幼稚園の方々の思いは切実であります。","respondent":"佐藤保育課長","answer":"定期的に私立幼稚園協会等からさまざまな要望等聞く場もありますので、委員ご指摘の趣旨も踏まえまして、今後さまざま検討していきたいと思います。","voiceIndex":344,"id":"exchange-149"},{"speaker":"伊藤委員","kind":"意見","question":"その方向は。だから、すぐにこの場でどうこうはできないとはわかっていながら聞くのだけれども、補正だけで保育園は約８３億円です。それで、平成３０年度の新規予算では、私立幼稚園は約８億円です。だからこれだけの差がある中で、幼稚園がどう生き残っていくのか、私立幼稚園が。どういうふうに確保していくのかということについては、結構大きな課題でありますから、もう一言だけ答弁をお願いいたします。","respondent":"佐藤保育課長","answer":"私立幼稚園に関するご質問ですが、繰り返しになる部分もありますけれども、品川区の幼児教育を支えてきたのは私立幼稚園だと考えておりますので、今後もさまざまお話を聞いて、東京都と区と、できることの役割分担をよく確認して進めていきたいと考えています。","voiceIndex":346,"id":"exchange-150"},{"speaker":"須貝委員","kind":"質問","question":"私は３４ページ、特別区民税についてお聞きしたいと思います。政策についてなので、財政課にお聞きします。特別区民税が約１０億円増えていると。理由は品川区は人口が増えている、そしてとりわけ所得が高い納税義務者が増えているというようなお話でした。そして、この特別区民税が増えたのは、区の事業により生まれたものなのでしょうか。２点についてお聞きします。","respondent":"秋山財政課長","answer":"委員のご質問ですけれども、特別区民税につきましては、納税義務者の増ということでご説明をしています。その納税義務者の増が、いかなる理由によるものかというご質問だと思います。これは品川区の努力というものももちろんあります。","voiceIndex":349,"id":"exchange-151"},{"speaker":"須貝委員","kind":"質問","question":"さて、その一方でふるさと納税制度により、区では２０１７年度、１２億円の減収となっています。区では、継続して行財政改革に努めています。そして各事業部もそうですが、節約しつつ、効率的な予算の執行を行っています。各事業部が努力しているわけです。やはり減収を抑えるべきことを考えないといけないのではないでしょうか。それに対して何か抜本的な対策というものは行っているのでしょうか。","respondent":"伊東税務課長、秋山財政課長","answer":"さらに納付しやすい環境を整えるということでクレジット納付等を開始して、民間サイトのホームページ上にも載せてＰＲを行ってきたと。そのようなことで、何とか区のほうに目を向けていただきたいということでやってきたところです。このような制度全体に対しては、都と連携をしたり、それから区長会を含めて強く主張していきたいと考えています。","voiceIndex":351,"id":"exchange-152"},{"speaker":"須貝委員","kind":"質問・要望","question":"おかしくないですか。各事業部が予算の範囲で一生懸命やって、何とか予算オーバーしないように努力している。そして品川区には、支援を求める方がたくさんいます。累計で相当の額になっているのではないかと思うのですが、それがとまっているならわかります。このようなことをしていいのでしょうか。ちょっとその点について、もう一度ご見解をお聞かせください。そして累計額についてもお聞かせください。","respondent":"秋山財政課長、伊東税務課長","answer":"その話と、各部が歳出のほうを効率的にやっていくということは、あまり連携はしていないと考えております。平成２７年度の流失が約１億１,０００万円、平成２８年度が約６億３,０００万円、そして平成２９年度が約１１億９,０００万円、そのような数字です。","voiceIndex":354,"id":"exchange-153"},{"speaker":"須貝委員","kind":"質問","question":"これだけの額を放置して、私が言ったように努力している、結果が出なくていいのですか。これは放置しているのと同じ、今税務課長が話していました。どんどん増えていますよ。本来なら、区民のために使うべきお金を毎年放出しているのです。１２億円。我々は訴えているのですから。だけれども国の制度がどうのこうの。では、その制度に対して、こちらもやるべきことはやらなければいけないのではないですか。","respondent":"秋山財政課長","answer":"ただし、返礼品競争であるとか、そういうふるさと納税の半分以上お返しするような返礼品競争にくみするつもりは全くございません。こういう中で、ふるさと納税をどうしていくのかというのは、国に対しての制度の変更であるとか、そういうことを求めているです。","voiceIndex":357,"id":"exchange-154"},{"speaker":"須貝委員","kind":"意見","question":"私はもっと税金というものをしっかり捉えて、区も真剣に闘って、一緒に返礼品競争をやるべきだと思います。国に対する訴えです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":359,"id":"exchange-155"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"私からは１０６ページの特定健康診査等事業費についてと、５８ページの予防費、定期予防接種についてお伺いします。それと、この把握をされている中で、どのような取組みをして、いわゆる医療費の削減に向けて努力をされているのか、お知らせいただきたいと思います。５８ページの定期予防接種ですが、いわゆる子宮頸がんワクチン予防接種についてです。","respondent":"三ッ橋国保医療年金課長、舟木保健予防課長","answer":"そこで実際には、指導については委託しているのですけれども、栄養士であったり、また保健師であったりが、その個別の対応をしております。子宮頸がんワクチン予防接種についてお答えいたします。現状も積極的な勧奨については差し控えているような状況です。","voiceIndex":361,"id":"exchange-156"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"これを良しとするか悪しとするかは別としても、実際に今行われていて、本当に自治体としても多くの歳入マイナスが出てしまっているのですから、これは本当に、先ほどほかの委員からもお話がありましたけれども、真剣に考えていかなければいけないのではないのかと思いますので、その点は答弁は要らないですが、ぜひそういったものも含めて、特定健診なども活用して。","respondent":"三ッ橋国保医療年金課長、舟木保健予防課長、大関教育総合支援センター長","answer":"特に今回、来年度に関しましては、早得キャンペーンなども実施しておりまして、魅力的な健診、この特定健診というものを魅力的なものとして。改めてその対象者への対応等については検討してまいりたいと思います。がん教育につきまして、学校では取り扱っておりますが、子宮頸がんワクチンまでは踏み込まずに、健康教育の中でがんについても取り扱うという範囲です。","voiceIndex":364,"id":"exchange-157"},{"speaker":"石田（し）委員","kind":"意見","question":"そのかわり判断については最終的にはご自身、またご家庭で判断をしていただくというふうにはなるかと思いますが、ぜひその辺はしっかりと教育の現場でも行っていただければなと思いますので、よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":368,"id":"exchange-158"},{"speaker":"安藤委員","kind":"質問","question":"私から４９ページの基金積立金など、最終補正予算全体について伺いたいと思います。歳入の部分を見ますと、当初予算に比べて特別区民税が約１０億円、財調も５億円増額補正となりました。さらに繰越金は約１７億５,６００万円増額補正です。これらを合わせると約３２億円余となりますが、これらは当初予算に比べて新たに３２億円、区で自由に使える財源が増えたということでよろしいのか伺います。","respondent":"秋山財政課長","answer":"繰越金につきましては、これは既に１０月の決算特別委員会等でもご認定いただいておる実質収支額が、こちらのほうに入ってくるというものです。","voiceIndex":370,"id":"exchange-159"},{"speaker":"安藤委員","kind":"質問","question":"これは一般財源に入ると思うので、区で自由に使える新たな財源が増えたということでよろしいのですかと伺いましたので、後で聞かせてください。それと繰越金ですが、つまり黒字分が当初予算から最終補正で１７億円余増えて４４億円余となった、その要因は何でしょうか。効率的な執行とは何なのか伺います。繰出金の更正減額はそれに当たるのでしょうか。伺いたいと思います。","respondent":"秋山財政課長","answer":"したがいまして、繰越金については、この繰越金の補正額につきましては、補正額の１７億５,６５９万３,０００円に意味があるというよりも、補正後の金額４４億８,７５５万７,０００円が昨年の実質収支と同じになるとご理解をいただければと思います。","voiceIndex":372,"id":"exchange-160"},{"speaker":"安藤委員","kind":"質問","question":"効率的な執行というと、何か、ああ、すごい良いことかなというように聞こえてしまうのですけれども、伺ったのは、先ほど、例えば各特別会計繰出金を更正減額しているのですが、こういう一般会計からの繰出金を減らすということは、当然国保料が上がったりとか、そのようなことになるわけですが、それは効率的な執行に当たるのですかと伺ったので、伺わせてください。伺います。","respondent":"秋山財政課長","answer":"これも特別会計のほうの歳入歳出がありますけれども、歳出のほうでそれぞれの会計において、一般会計からの繰入金というのは、そちらの差額を補填するという性格のものですから、特別会計のほうで効率的な財政執行を行ったがゆえに。","voiceIndex":374,"id":"exchange-161"},{"speaker":"安藤委員","kind":"質問","question":"特別会計のほうで効率的な執行をしたということでございましたけれども、２つ目の質問です。この３２億円新たにできた一般財源のうち、歳出のほうを見ると２１億５,０００万円を基金積立金に大幅追加しているのです。かなりこれの基金の積立てに充てたということなのですかと伺ったので、もう一度お伺いします。","respondent":"秋山財政課長","answer":"いわゆる事業の効率化により減額をする補正のトータルが６３億円、それから増額の今回の補正による増減額は３６億円余。","voiceIndex":376,"id":"exchange-162"},{"speaker":"安藤委員","kind":"質問","question":"ですから、今答弁されたように積み立てているということなのです。私は、こうしたお金というのは、今の苦しい区民生活や地方自治体の役割に照らせば、基金の積み立てに充てるのではなく、待機児童の緊急対策ですとか、中小零細企業の支援策、あるいは障害者などの福祉の改善など、住民福祉向上の施策に使うべきだと思うのですけれども、いかがでしょうか。","respondent":"秋山財政課長","answer":"したがいまして、今この段階で最終補正をしておりますけれども、それ以前に必要な福祉の財源であるとかというものには、必要な額は入れていると考えております。","voiceIndex":378,"id":"exchange-163"},{"speaker":"安藤委員","kind":"質問","question":"二次募集の結果は３月１５日ですけれども、この最終補正をしたとしても９５５人です。この最終補正でこの４月、区が言う待機児童はゼロになるのですか。その見込みについて伺いたいと思います。少なくともとりわけ深刻な、認証保育所にも入れなくて、４月入園再申請も諦めてしまうような子ども、これはゼロにできるのでしょうか。この対応を十分にやっていると言えるのでしょうか。伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"ただ、今年度から企業主導型が始まりまして、４月には１０園になると聞いておりますので、一定、企業主導型のほうで受け入れがかなえば、もちろんマッチングの問題、地域的なマッチングの問題はありますけれども。","voiceIndex":380,"id":"exchange-164"},{"speaker":"安藤委員","kind":"質問","question":"私はやはりこの最終補正の姿勢を問われていると思うのです。区長の公約は待機児童ゼロですから。ですから、ゼロに近くなればいいという問題ではないわけです。私が伺いたいのは、二次募集発表は３月１５日ですけれども、もう既に一次の発表は２月２０日です。もう大分前です。最後の１人まで不承諾になった方々に対して手だてをとる、そのような姿勢があるのかどうか、しっかりと伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"ただ枠が、先ほども申し上げたように新しい企業主導型なども実施しておりますので、そういう意味ではこれ以上、今の時点で特に対策をとる考えはございません。","voiceIndex":382,"id":"exchange-165"},{"speaker":"安藤委員","kind":"質問","question":"財源がたっぷりあるのです。基金を積み増すだけの余裕があるわけではないですか。それを、私が聞いたのは個々の状況に対応してほしいと聞いているのです。このような緊急対策を品川区はやるべきなのではないでしょうか。私が伺ったのは、その個々の状況に対応してほしい。不承諾を出した方全てに責任を持つ、そうした姿勢があるのか、そうしたことを行うつもりがあるのか伺ったので、お答えください。","respondent":"大澤待機児童対策担当課長","answer":"そのほかに４月から定期利用保育ということで、不承諾者が多い１歳児については１年間、最長１年でお預かりするという対応も予定しておりますので、十分に対策としてはとっていると考えております。","voiceIndex":384,"id":"exchange-166"},{"speaker":"安藤委員","kind":"質問・要望","question":"その緊急対策でも足りないというところなのです。最後の１人まで責任持っていただきたい。最後に態度表明いたしますが、品川区一般会計補正予算に対しては反対いたします。区民サービスの削減や負担増を効率的な財政運営と合理化し、増やしたお金は基金にため込むのではなく、福祉の充実のために充てるべきです。反対いたします。以上、３会計に反対いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":386,"id":"exchange-167"},{"speaker":"こんの委員","kind":"質問","question":"受託事業ですので、直接品川区というところでは、なかなかできることが限られているかもしれないですが、更正減額ですから単純に受診の方が少なかったと、このように見るのですけれども、減の要因は何でしょうか。それから受診率の推移ですけれども、事務事業概要を少し見させていただいたときに、４３％前後で推移をしている。この数字をどう捉えていらっしゃいますでしょうか。","respondent":"三ッ橋国保医療年金課長","answer":"一方４３％という、この受診率ですが、５０％を目標として、区としては対応してまいりたいと思っています。この４３％は若干まだまだ少ない、到達はできていない状況ですけれども、日々推進してまいります。","voiceIndex":388,"id":"exchange-168"},{"speaker":"こんの委員","kind":"質問・要望","question":"そうしたことを考えたときに、この５０％まで持っていく、これはやはり努力していただきたいなと。そのためには何か今施策があるのでしょうか。後期高齢者の方々に健康診査を受けていただく、ご自分の健康状態を知っていただいて予防をする、あるいは治療する、そういうところにつなげる施策が必要と思いますけれども、いかがでしょうか。","respondent":"三ッ橋国保医療年金課長","answer":"今までも受診勧奨というものは、受診率向上に向けては実施しておりました。今回、平成３０年度に向けては、国保もそうなのですけれども、早得キャンペーンというものを実施していく予定です。こちらも５月から８月に向けてのキャンペーンを実施する予定です。","voiceIndex":390,"id":"exchange-169"},{"speaker":"こんの委員","kind":"意見","question":"グループホームの開設にあたって、月に一、二件ご相談があって、ですが、なかなか整備に結びつかないという現状だということです。ご相談される民間の方々がどういったところで踏み切れないのか、どういう課題があるのか、その辺の、こちらの区として手当てをしてさしあげるものがあるのか、こちらもちょっと現状をお願いいたします。","respondent":"大串福祉計画課長","answer":"それ以外にもさまざまな近隣の関係ですとか、いろいろなご事情があるというふうに伺っております。なかなかそこに対して区のほうでというのは、今現状持っております、こういった補助のスキーム、これ以上のといったところはちょっと難しいのかというふうに考えているところです。","voiceIndex":394,"id":"exchange-170"},{"speaker":"こんの委員","kind":"質問・要望","question":"開設するにあたっては区のご努力も、また民間の方々の思いもあるのですが、引き続き鋭意ご努力をいただいて、整備にあたっていただきたいと思います。すまいるスクールですけれども、すまいるスクールの教室、いろいろな地域の方の力をおかりしての伝統授業などの教室、いろいろなサークルをされていると思いますが、その地域の方々にお支払いをしている謝礼金の金額の設定の考え方をお聞きしたいと思います。","respondent":"高山子ども育成課長","answer":"その補助となる方には５００円という形で、金額のほう設定しています。","voiceIndex":396,"id":"exchange-171"},{"speaker":"こんの委員","kind":"質問","question":"補助の方には５００円ということで、正規の方には１,５００円という形で出されています。この講師の方々は、その学校の周辺から来る方ばかりではないというふうに理解をしております。そうしたときに、やはり交通費というところを考えると、補助の方の金額というのはもう少しあってもいいのかなと、このように考えますが、いかがでしょうか。","respondent":"高山子ども育成課長","answer":"先ほど申しましたように、本来無料でもやっていいといった方々の善意の中で、この事業を運営しておりますので、今後の課題とさせていただきたいと存じます。","voiceIndex":398,"id":"exchange-172"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"執行率のところを伺いたいと思います。例えば、平成２９年度当初予算繰出が１２０億円ぐらい出そうと思っていたけれども、ここでいくと特別会計の繰出金は１２億円ぐらいの更正減額があると。予算を決定したと。もちろんわかっていますよ。６月、９月、１２月の補正というのがあるのはわかっているけれども、この最終補正のときにどういうお考えでこれが出てくるのかということを改めて伺いたいと思います。","respondent":"秋山財政課長","answer":"１つは年度、もう最終補正を編成するのが年の暮れ以降になりますので、それまでの時点でどのぐらい進捗しているのかですとか、そこから先の見込みを見た上で、最終的にどこまでこれができるのかというところで考えておりますので。","voiceIndex":401,"id":"exchange-173"},{"speaker":"石田（秀）委員","kind":"質問","question":"私は９５％、９６％というのは非常に誤差の範囲で、よくやられているなという理解をしております。今回も８０億円、防災が１５億円ぐらいあるからちょっと置いておくと、８０億円ぐらいは繰り入れしますと。ためたけれどもどうするのか。このようなことをもう少し見えるようにしてほしいと思っています。その辺はどうお考えか。この辺の見え方はどう思われるのかということをお聞きします。","respondent":"秋山財政課長","answer":"最終の見込みですけれども、こちらはまだどうなるかというのはなかなか今の段階でお示しするのは難しいのかなと考えていますが、そういうことです。","voiceIndex":403,"id":"exchange-174"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"申しわけありません。区の職員だけで考えたとは思わないけれども、いろいろな方を入れて、先ほどのライザップの話ではないですが、いろいろな考えを持って、いろいろな対策を打っていくということは、私はこれはありだと思っていて、いろいろなイベントを組むことも１つ、その中に使えるものをやっていくということも１つの考え方と思うので、ここの考え方だけ教えていただきたい。","respondent":"柏原企画調整課長","answer":"そこで生まれてくるところをどういった形で区民の方とか、ふるさと納税をしようという方に気に入ってもらえるかということを種々、いろいろな部署、いろいろな方々と検討しながら、返礼品競争という、そのような特化したところではなくて。","voiceIndex":405,"id":"exchange-175"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1072#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":127566,"voices":410}}]);
